INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH0' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI12')), 'B0', 'Chương mở đầu', 1, 1, $JSON$
{
  "content": [
    "[Logo KẾT NỐI TRI THỨC VỚI CUỘC SỐNG]",
    "VŨ VĂN HÙNG (Tổng Chủ biên)",
    "NGUYỄN VĂN BIÊN (Chủ biên)",
    "TRẦN NGỌC CHẤT – PHẠM KIM CHUNG",
    "ĐẶNG THANH HẢI – TƯỞNG DUY HẢI – BÙI GIA THỊNH",
    "",
    "**VẬT LÍ 12**",
    "",
    "[Logo NHÀ XUẤT BẢN GIÁO DỤC VIỆT NAM]",
    "NHÀ XUẤT BẢN GIÁO DỤC VIỆT NAM",
    "[Tem BẢN MẪU]",
    "**HỘI ĐỒNG QUỐC GIA THẨM ĐỊNH SÁCH GIÁO KHOA**",
    "**Môn: Vật lí – Lớp 12**",
    "*(Theo Quyết định số 1882/QĐ-BGDĐT ngày 29 tháng 6 và Quyết định số 2892/QĐ-BGDĐT ngày 03 tháng 10 năm 2023 của Bộ trưởng Bộ Giáo dục và Đào tạo)*",
    "",
    "**Chủ tịch:** ĐỖ HƯƠNG TRÀ",
    "**Phó Chủ tịch:** LỤC HUY HOÀNG",
    "**Uỷ viên, Thư kí:** NGUYỄN HỮU TÌNH",
    "",
    "**Các uỷ viên:** LÊ ANH ĐỨC – NGUYỄN VĂN HỢP",
    "ĐẶNG TIẾN SƠN – VŨ THỊ THU",
    "NGUYỄN VĂN THUẬN – NGUYỄN VĂN TÚ",
    "VŨ VĂN HÙNG (Tổng Chủ biên)",
    "NGUYỄN VĂN BIÊN (Chủ biên)",
    "TRẦN NGỌC CHẤT – PHẠM KIM CHUNG – ĐẶNG THANH HẢI",
    "TƯỞNG DUY HẢI – BÙI GIA THỊNH",
    "",
    "**VẬT LÍ 12**",
    "",
    "[Tem BẢN MẪU]",
    "",
    "NHÀ XUẤT BẢN GIÁO DỤC VIỆT NAM",
    "**HƯỚNG DẪN SỬ DỤNG SÁCH**",
    "",
    "Sách giáo khoa *Vật lí 12* gồm 4 chương. Mỗi chương gồm một số bài học. Mỗi bài học là một chuỗi các nội dung kiến thức và nhiệm vụ học tập, cụ thể như sau:",
    "",
    "**Khởi động**",
    "Tiếp cận bài mới bằng sự tò mò, hứng thú học tập.",
    "",
    "**? Câu hỏi**",
    "Câu hỏi sẽ giúp học sinh:",
    "Tìm tòi, khám phá kiến thức mới.",
    "",
    "**! Những điều cần lưu ý.**",
    "",
    "**Đọc hiểu**",
    "Cung cấp hiện tượng, dữ liệu ban đầu, thuật ngữ cần thiết,... để tiến hành hoạt động tìm tòi, khám phá kiến thức tiếp theo.",
    "",
    "**Hoạt động**",
    "Tiến hành các hoạt động giúp học sinh giải quyết các vấn đề học tập và đồng thời phát triển các năng lực cần thiết.",
    "",
    "**EM ĐÃ HỌC**",
    "Tổng kết kiến thức và kĩ năng cơ bản của bài.",
    "",
    "**EM CÓ BIẾT**",
    "Mở rộng kiến thức của bài.",
    "",
    "**EM CÓ THỂ**",
    "Yêu cầu về năng lực vận dụng kiến thức, kĩ năng vào học tập và thực tiễn cuộc sống.",
    "",
    "Hoạt động trải nghiệm yêu cầu học sinh vận dụng kiến thức, kĩ năng đã học vào một số tình huống của thực tế cuộc sống.",
    "",
    "*Hãy bảo quản, giữ gìn sách giáo khoa để dành tặng các em học sinh lớp sau!*",
    "",
    "2",
    "**LỜI NÓI ĐẦU**",
    "",
    "Sách giáo khoa *Vật lí 12* với thông điệp *kết nối tri thức với cuộc sống* được biên soạn theo định hướng đổi mới giáo dục phổ thông nhằm phát triển phẩm chất, năng lực của người học. Tư tưởng chủ đạo trong việc biên soạn sách giáo khoa này là tổ chức các hoạt động học tập nhằm coi trọng việc phát triển phẩm chất, năng lực học sinh nhưng không coi nhẹ vai trò của kiến thức. Kiến thức trong sách giáo khoa *Vật lí 12* được coi là chất liệu làm cơ sở giúp học sinh hình thành và phát triển các phẩm chất và năng lực cần có trong cuộc sống hiện tại và tương lai.",
    "",
    "Sách giáo khoa *Vật lí 12* không phải là cuốn sách trình bày sẵn các nội dung kiến thức cần học mà là cuốn sách hướng dẫn học sinh hoạt động để tìm tòi, khám phá ra kiến thức mới, vận dụng chúng vào việc giải quyết các vấn đề trong học tập và cuộc sống. Thông qua các hoạt động học tập này, các em không những hình thành và phát triển các năng lực khoa học nói chung và vật lí nói riêng mà còn đồng thời hình thành và phát triển được các năng lực chung như năng lực tự chủ và tự học, giao tiếp và hợp tác, giải quyết vấn đề và sáng tạo,...",
    "",
    "Sách giáo khoa *Vật lí 12* coi trọng phương pháp thực nghiệm, phần lớn kiến thức cơ bản của cuốn sách được tổ chức và trình bày theo phương pháp thực nghiệm. Việc coi trọng phương pháp thực nghiệm còn được thể hiện ở hệ thống các bài thí nghiệm thực hành từ đơn giản đến phức tạp, tạo điều kiện cho các em tìm hiểu các thuộc tính của các đối tượng vật lí dưới nhiều góc nhìn khác nhau. Sách giáo khoa *Vật lí 12* trình bày các bài tập đan xen vào các hoạt động tương ứng trong bài.",
    "",
    "Các tác giả mong muốn sách giáo khoa *Vật lí 12* sẽ mang đến cho các em niềm vui và sự đam mê trong học tập môn Vật lí để có kết quả học tập tốt môn học này, giúp các em thấy được năng lực và sở trường của bản thân để có thể bắt đầu định hướng nghề nghiệp của mình.",
    "",
    "**CÁC TÁC GIẢ**",
    "",
    "3",
    "**MỤC LỤC**",
    "",
    "| | | Trang |",
    "|---|---|---|",
    "| | Hướng dẫn sử dụng sách | 2 |",
    "| | Lời nói đầu | 3 |",
    "| **Chương I.** | **VẬT LÍ NHIỆT** | **5** |",
    "| | Bài 1. Cấu trúc của chất. Sự chuyển thể | 6 |",
    "| | Bài 2. Nội năng. Định luật I của nhiệt động lực học | 10 |",
