INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH1' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI12')), 'B1', 'Cấu trúc của chất. Sự chuyển thể', 7, 1, $JSON$
{
  "content": [
    "# CHƯƠNG I VẬT LÍ NHIỆT",
    "",
    "[Hình ảnh đoàn tàu hơi nước đang chạy]",
    "Năm 1765, James Watt (Giêm Oát) (1736-1819) dựa vào những thành tựu nghiên cứu về Vật lí nhiệt đã phát minh ra máy hơi nước, góp phần quan trọng vào việc làm bùng nổ cuộc Cách mạng Công nghiệp lần thứ nhất. Những kiến thức về Vật lí nhiệt nào đã làm cơ sở cho việc phát minh ra máy hơi nước?",
    "",
    "**Nội dung**",
    "- Cấu trúc của chất. Sự chuyển thể",
    "- Nội năng. Định luật I của nhiệt động lực học",
    "- Nhiệt độ, thang nhiệt độ, nhiệt kế",
    "- Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng",
    "",
    "5",
    "# Bài 1 CẤU TRÚC CỦA CHẤT. SỰ CHUYỂN THỂ",
    "",
    "**Khởi động:**",
    "*Hãy dựa trên những kiến thức đã học về cấu tạo chất để giải thích tại sao cùng một chất lại có thể tồn tại ở các thể khác nhau là rắn, lỏng, khí.*",
    "",
    "## I. MÔ HÌNH ĐỘNG HỌC PHÂN TỬ VỀ CẤU TẠO CHẤT",
    "Mô hình động học phân tử về cấu tạo chất có những nội dung cơ bản sau đây:",
    "1. Các chất được cấu tạo từ các hạt riêng biệt là phân tử.",
    "2. Các phân tử chuyển động không ngừng. Nhiệt độ của vật càng cao thì tốc độ chuyển động của các phân tử cấu tạo nên vật càng lớn.",
    "3. Giữa các phân tử có lực hút và đẩy gọi chung là lực liên kết phân tử.",
    "*Dùng mô hình này có thể giải thích được cấu trúc của các chất rắn, chất lỏng, chất khí và sự chuyển thể.*",
    "",
    "**! Những điều cần lưu ý.**",
    "Thuật ngữ phân tử trong mô hình trên được dùng để chỉ chung các hạt cấu tạo chất: phân tử, nguyên tử, ion.",
    "",
    "**Hoạt động**",
    "1. Trong lịch sử phát triển của khoa học, có hai quan điểm khác nhau về cấu tạo chất là quan điểm chất có cấu tạo liên tục và chất có cấu tạo gián đoạn. Mô hình động học phân tử được xây dựng trên quan điểm nào?",
    "2. Năm 1827, khi làm thí nghiệm quan sát các hạt phấn hoa rất nhỏ trong nước bằng kính hiển vi, Brown thấy chúng chuyển động hỗn loạn, không ngừng. (Hình 1.1 và Hình 1.2). Chuyển động này được gọi là chuyển động Brown.",
    "a) Tại sao thí nghiệm của Brown được coi là một trong những thí nghiệm chứng tỏ các phân tử chuyển động hỗn loạn, không ngừng?",
    "b) Làm thế nào để với thí nghiệm của Brown có thể chứng tỏ được khi nhiệt độ của nước càng cao thì các phân tử nước chuyển động càng nhanh?",
    "3. Hãy tìm các hiện tượng thực tế chứng tỏ giữa các phân tử có lực đẩy, lực hút.",
    "",
    "[Hình 1.1. Chuyển động của các phân tử nước và các hạt phấn hoa]",
    "*Mũi tên màu đen ($\\rightarrow$) biểu diễn hướng chuyển động của các phân tử nước*",
    "*Mũi tên màu vàng ($\\rightarrow$) biểu diễn hướng chuyển động của hạt phấn hoa*",
    "",
    "[Hình 1.2. Quỹ đạo chuyển động của hạt phấn hoa trong nước]",
    "",
    "**! Những điều cần lưu ý.**",
    "Người ta thường gọi chuyển động hỗn loạn, không ngừng của các hạt rất nhỏ dưới tác dụng của các phân tử chất lỏng hoặc chất khí là chuyển động Brown.",
    "",
    "6",
    "CHƯƠNG I – VẬT LÍ NHIỆT",
    "",
    "## II. CẤU TRÚC CỦA CHẤT RẮN, CHẤT LỎNG VÀ CHẤT KHÍ",
    "Dựa vào các đặc điểm sau đây của phân tử có thể nêu được sơ lược cấu trúc của hầu hết các chất rắn, chất lỏng, chất khí:",
    "- Khoảng cách giữa các phân tử càng lớn thì lực liên kết giữa chúng càng yếu.",
    "- Các phân tử sắp xếp có trật tự thì lực liên kết giữa chúng mạnh.",
    "",
    "**Hoạt động**",
    "1. Hãy dựa vào Hình 1.3 để mô tả, so sánh khoảng cách và sự sắp xếp (a), chuyển động (b) của phân tử ở các thể khác nhau. Từ đó mô tả một cách sơ lược về cấu trúc của chất rắn, chất lỏng, chất khí.",
    "[Hình 1.3. (a) Khoảng cách và sự sắp xếp các phân tử ở các thể khác nhau, (b) Chuyển động của phân tử ở các thể khác nhau. Hình cầu là phân tử, mũi tên là hướng chuyển động của phân tử. a) và b) ở Thể khí, Thể rắn, Thể lỏng]",
    "2. Hãy giải thích các đặc điểm sau đây của thể khí, thể rắn, thể lỏng.",
    "a) Chất khí không có hình dạng và thể tích riêng, luôn chiếm toàn bộ thể tích bình chứa và có thể nén được dễ dàng.",
    "b) Vật ở thể rắn có thể tích và hình dạng riêng, rất khó nén.",
    "c) Vật ở thể lỏng có thể tích riêng nhưng không có hình dạng riêng.",
    "",
    "## III. SỰ CHUYỂN THỂ",
    "**1. Sự chuyển thể**",
    "Các chất có thể chuyển từ thể này sang thể khác. Đa số các chất ở thể rắn khi nóng lên có thể chuyển sang thể lỏng, rồi từ thể lỏng sang thể khí. Ngược lại, đa số chất khí khi lạnh đi có thể chuyển sang thể lỏng, rồi từ thể lỏng sang thể rắn. Một số chất có thể chuyển trực tiếp từ thể rắn sang thể khí và ngược lại (Hình 1.4).",
    "",
    "[Hình 1.4. Sơ đồ các hình thức chuyển thể. Khí -> (Ngưng kết, Thăng hoa) -> Rắn; Rắn -> (Đông đặc, Nóng chảy) -> Lỏng; Lỏng -> (Hoá hơi, Hoá lỏng) -> Khí]",
    "",
    "7",
    "CHƯƠNG I – VẬT LÍ NHIỆT",
    "",
    "**2. Dùng mô hình động học phân tử giải thích sự chuyển thể**",
    "Dựa vào đặc điểm của mô hình động học phân tử có thể giải thích sơ lược các hiện tượng liên quan đến sự chuyển thể như sự hoá hơi, sự nóng chảy:",
    "Trong khi chuyển động hỗn loạn, các phân tử có thể va chạm vào nhau, truyền năng lượng cho nhau. Càng nhận được nhiều năng lượng thì các phân tử chuyển động hỗn loạn càng nhanh, khoảng cách trung bình giữa chúng càng tăng, lực liên kết giữa chúng càng yếu.",
    "*a) Giải thích sự hoá hơi*",
    "Sự hoá hơi có thể xảy ra dưới hai hình thức là bay hơi và sôi.",
    "- Sự bay hơi là sự hoá hơi xảy ra ở mặt thoáng của chất lỏng. Nước đựng trong một cốc không đậy kín cạn dần là một ví dụ về sự bay hơi.",
    "Do các phân tử chuyển động hỗn loạn có thể va chạm vào nhau, truyền năng lượng cho nhau nên có một số phân tử ở gần mặt thoáng của chất lỏng có thể có động năng đủ lớn để thắng lực liên kết của các phân tử chất lỏng khác, thoát được ra khỏi mặt thoáng của chất lỏng trở thành các phân tử ở thể hơi.",
    "- Sự sôi: Hình 1.5 là đồ thị biểu diễn sự thay đổi nhiệt độ của nước theo thời gian khi được đun nóng. Khi nhiệt độ của nước tăng tới khoảng 100 $^\\circ$C dưới áp suất tiêu chuẩn (1,01.10$^5$ Pa) thì nước bắt đầu sôi. Khi đó các bọt chứa không khí và hơi nước nổi lên trong lòng nước càng ngày càng nhiều, càng nổi lên trên thể tích các bọt khí này càng tăng, tới mặt thoáng thì vỡ, không khí và hơi nước thoát ra ngoài khí quyển. Do đó sự sôi là sự hoá hơi xảy ra đồng thời ở bên trong và trên mặt thoáng của chất lỏng.",
    "",
    "**? Câu hỏi:**",
    "Tại sao khi bay hơi nhiệt độ của chất lỏng giảm?",
    "",
    "**Hoạt động**",
    "1. Hãy dựa vào đồ thị ở Hình 1.5 để mô tả sự thay đổi nhiệt độ của nước khi được đun từ 20 $^\\circ$C tới khi sôi.",
    "2. Khi nước đang sôi thì năng lượng mà nước nhận được từ nguồn nhiệt có được chuyển hoá thành động năng của các phân tử nước không? Tại sao?",
    "",
    "[Hình 1.5. Đồ thị về sự thay đổi nhiệt độ của nước theo thời gian khi được đun sôi]",
    "",
    "**EM CÓ BIẾT**",
    "**Chất rắn kết tinh và chất rắn vô định hình**",
    "Chất rắn kết tinh là chất mà các hạt (phân tử, nguyên tử, ion) cấu tạo nên nó ở thể rắn, liên kết với nhau một cách chặt chẽ, sắp xếp theo một trật tự hình học tuần hoàn tạo thành các mạng tinh thể (Hình 1.6). Chất rắn vô định hình là chất ở thể rắn mà các hạt tạo nên nó không tạo thành mạng tinh thể.",
    "Hầu hết các kim loại là các chất kết tinh; thuỷ tinh, nhựa đường, các chất dẻo,... là các chất vô định hình.",
    "Mỗi chất rắn kết tinh có nhiệt độ nóng chảy (hoặc đông đặc) riêng xác định.",
    "",
    "[Hình 1.6. Tinh thể muối ăn]",
    "",
    "8",
    "CHƯƠNG I – VẬT LÍ NHIỆT",
    "",
    "b) Giải thích sự nóng chảy của chất rắn kết tinh",
    "**Hoạt động**",
    "1. Tại sao chất rắn kết tinh khi được đun nóng có thể chuyển thành chất lỏng?",
    "2. a) Hãy dựa vào Hình 1.7 để mô tả quá trình nóng chảy của chất kết tinh.",
    "b) Giải thích tại sao khi đang nóng chảy, nhiệt độ của chất rắn kết tinh không tăng dù vẫn nhận được nhiệt năng. Năng lượng mà chất rắn kết tinh nhận được lúc này dùng để làm gì?",
    "",
    "[Hình 1.7. Đồ thị sự thay đổi nhiệt độ của chất rắn kết tinh khi được làm nóng chảy. Giai đoạn a: Chất rắn chưa nóng chảy; Giai đoạn b: Chất rắn đang nóng chảy; Giai đoạn c: Chất rắn đã nóng chảy hoàn toàn.]",
    "",
    "**EM ĐÃ HỌC**",
    "- Mô hình động học phân tử về cấu tạo chất:",
    "  - Các chất được cấu tạo từ các hạt riêng biệt là phân tử.",
    "  - Các phân tử chuyển động không ngừng. Nhiệt độ của vật càng cao thì tốc độ trung bình của các phân tử càng lớn.",
    "  - Giữa các phân tử có lực liên kết phân tử.",
    "- Các chất có thể chuyển từ thể này sang thể khác.",
    "",
    "**EM CÓ THỂ**",
    "- Giải thích được sự khác nhau giữa các thể của chất và cơ chế của sự chuyển thể.",
    "- Tìm hiểu và trình bày được vai trò của sự chuyển thể đối với cuộc sống con người như vòng tuần hoàn nước, công nghệ đúc,...",
    "",
    "**EM CÓ BIẾT**",
    "Ở nhiệt độ hàng triệu độ, chất không tồn tại ở các thể rắn, lỏng, khí mà ở một thể đặc biệt gọi là Plasma. Ở thể này, chất không tồn tại dưới dạng các nguyên tử, phân tử mà dưới dạng các ion. Plasma rất ít gặp trên Trái Đất nhưng trong vũ trụ có tới trên 99% các chất tồn tại ở thể Plasma (Hình 1.8).",
    "",
    "[Hình 1.8. Luồng Plasma phóng ra từ Mặt Trời]",
    "",
    "9"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH1' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI12')), 'B2', 'Nội năng. Định luật I của nhiệt động lực học', 12, 2, $JSON$
{
  "content": [
    "# Bài 2 NỘI NĂNG ĐỊNH LUẬT I CỦA NHIỆT ĐỘNG LỰC HỌC",
    "",
    "**Khởi động:**",
    "*Khi nước được đun tới lúc bắt đầu sôi thì dù có tiếp tục đun, nhiệt độ của nước cũng không thay đổi. Vậy nhiệt năng mà nước nhận được lúc này làm tăng dạng năng lượng nào của nước?*",
    "",
    "## I. KHÁI NIỆM NỘI NĂNG",
    "**1. Nội năng của một vật**",
    "Vì các phân tử chuyển động không ngừng nên chúng có động năng. Động năng này được gọi là động năng phân tử. Động năng phân tử phụ thuộc vào tốc độ chuyển động của phân tử.",
    "Vì các phân tử tương tác với nhau nên chúng có thế năng. Thế năng này được gọi là thế năng tương tác phân tử, gọi tắt là thế năng phân tử. Thế năng phân tử phụ thuộc vào khoảng cách giữa các phân tử.",
    "Tổng động năng và thế năng của các phân tử cấu tạo nên vật được gọi là nội năng của vật. Nội năng được kí hiệu bằng chữ U và có đơn vị là jun (J).",
    "Nội năng của một vật phụ thuộc vào nhiệt độ và thể tích của vật.",
    "",
    "**? Câu hỏi:**",
    "Tại sao nội năng của vật lại phụ thuộc vào nhiệt độ và thể tích của vật?",
    "",
    "**! Những điều cần lưu ý.**",
    "1. Vì các phân tử cấu tạo nên vật chuyển động không ngừng nên tốc độ và khoảng cách giữa các phân tử luôn thay đổi làm cho động năng và cả thế năng của các phân tử cũng không ngừng thay đổi. Do đó, khi nói động năng và thế năng của phân tử thì phải hiểu đó là động năng và thế năng trung bình của các phân tử cấu tạo nên vật.",
    "2. Vì số phân tử trong một vật vô cùng lớn và các phân tử chuyển động hỗn loạn nên không thể xác định được chính xác độ lớn nội năng của một vật. Trong vật lí người ta chủ yếu quan tâm đến độ biến thiên nội năng ($\\Delta$U) của vật.",
    "",
    "**EM CÓ BIẾT**",
    "[Hình 2.1. James Joule (Giêm Giun) (1818-1889), nhà vật lí người Anh có nhiều đóng góp cho sự hình thành và phát triển nhiệt động lực học]",
    "Nhiệt động lực học là lĩnh vực vật lí nghiên cứu về năng lượng nhiệt và sự truyền nhiệt. Nhiệt động lực học ra đời vào giữa thế kỉ XIX trong quá trình con người tìm hiểu về sự chuyển hoá năng lượng dự trữ trong các nhiên liệu thành cơ năng để chế tạo các động cơ nhiệt.",
    "",
    "10",
    "CHƯƠNG I – VẬT LÍ NHIỆT",
    "",
    "**2. Thí nghiệm về mối liên hệ nội năng của vật với năng lượng của các phân tử cấu tạo nên vật**",
    "",
    "**Hoạt động**",
    "Thí nghiệm sau đây cho thấy mối liên hệ giữa nội năng của vật với năng lượng của các phân tử cấu tạo nên vật.",
    "*Chuẩn bị:*",
    "- Ống nghiệm (1).",
    "- Nút bấc có kích thước vừa khít miệng ống nghiệm (2).",
    "- Đèn cồn (3).",
    "- Giá đỡ thí nghiệm (4).",
    "*Tiến hành:*",
    "- Bố trí thí nghiệm như Hình 2.2.",
    "- Dùng đèn cồn đun nóng ống nghiệm cho đến khi nút bấc bật ra.",
    "*Thực hiện các yêu cầu sau:*",
    "1. Khi đun ống nghiệm tới một lúc nào đó thì thấy nút bấc bật ra. Giải thích vì sao nút bấc bật ra.",
    "2. Khi nút chưa bị bật ra:",
    "a) Nội năng của không khí trong ống nghiệm tăng hay giảm? Vì sao?",
    "b) Nội năng của không khí trong ống nghiệm tăng có phải do thế năng phân tử khí tăng không? Tại sao?",
    "c) Tại sao hiện tượng nút ống nghiệm bị bật ra lại chứng tỏ động năng của các phân tử khí trong ống nghiệm tăng?",
    "",
    "[Hình 2.2. Thí nghiệm về mối liên hệ giữa nội năng của vật với năng lượng của các phân tử khí]",
    "",
    "## II. ĐỊNH LUẬT I CỦA NHIỆT ĐỘNG LỰC HỌC",
    "**1. Cách làm thay đổi nội năng**",
    "Có hai cách làm thay đổi nội năng là *thực hiện công* và *truyền năng lượng nhiệt* (gọi tắt là truyền nhiệt).",
    "- Ví dụ về thực hiện công: Khi dùng tay thực hiện công cọ xát một miếng kim loại lên sàn nhà thì miếng kim loại nóng lên, nội năng của nó đã thay đổi.",
    "- Ví dụ về truyền nhiệt: Cũng có thể làm miếng kim loại nóng lên bằng cách cho nó tiếp xúc với một nguồn nhiệt. Khi đó nội năng của nó cũng thay đổi.",
    "",
    "[Hình ảnh a) Thực hiện công, b) Truyền nhiệt]",
    "[Hình 2.3. Hai cách làm thay đổi nội năng của vật]",
    "",
    "**? Câu hỏi:**",
    "1. Mô tả sự thay đổi nội năng của lượng khí trong xi lanh ở Hình 2.3.",
    "2. Tìm thêm ví dụ về thực hiện công và truyền nhiệt làm thay đổi nội năng của vật.",
    "",
    "11",
    "CHƯƠNG I – VẬT LÍ NHIỆT",
    "",
    "**2. Định luật I của nhiệt động lực học**",
    "Định luật I của nhiệt động lực học là sự vận dụng định luật bảo toàn năng lượng vào các quá trình thay đổi nội năng.",
    "*Nếu vật vừa nhận được công vừa được truyền nhiệt thì: Độ biến thiên nội năng của vật bằng tổng công và nhiệt lượng mà vật nhận được:*",
    "$\\Delta$U = A + Q (2.1)",
    "Với quy ước về dấu thích hợp thì hệ thức trên có thể áp dụng cho các quá trình thay đổi nội năng khác như vật truyền nhiệt cho vật khác, vật thực hiện công lên vật khác, vật vừa thực hiện công vừa truyền nhiệt cho vật khác.",
    "",
    "Quy ước về dấu của A và Q trong hệ thức (2.1):",
    "Q > 0: Vật nhận nhiệt lượng từ vật khác.",
    "Q < 0: Vật truyền nhiệt lượng cho vật khác.",
    "A > 0: Vật nhận công từ vật khác.",
    "A < 0: Vật thực hiện công lên vật khác.",
    "",
    "[Hình 2.4. Quy ước về dấu của Q và A trong hệ thức (2.1)]",
    "",
    "**! Những điều cần lưu ý.** Vật ở đây là vật rắn, khối chất lỏng và khối chất khí.",
    "",
    "**? Câu hỏi:**",
    "Các hệ thức sau đây mô tả các quá trình thay đổi nội năng nào?",
    "1. $\\Delta$U = Q khi Q > 0 và khi Q < 0.",
    "2. $\\Delta$U = A khi A > 0 và khi A < 0.",
    "3. $\\Delta$U = A + Q khi Q > 0 và A < 0.",
    "4. $\\Delta$U = A + Q khi Q < 0 và A > 0.",
    "",
    "**! Những điều cần lưu ý.**",
    "- Nhiệt lượng là số đo nhiệt năng được truyền từ vật này sang vật khác trong quá trình truyền nhiệt. Khi *không* có quá trình truyền nhiệt thì không có nhiệt lượng.",
    "- Nội năng là một dạng năng lượng. Mọi vật luôn có nội năng.",
    "",
    "**EM CÓ BIẾT**",
    "**Thí nghiệm minh hoạ định luật I của nhiệt động lực học**",
    "Định luật I của nhiệt động lực học được hình thành từ những thí nghiệm mà nhà vật lí người Anh Joule đã tiến hành trong những năm từ 1844 đến 1854.",
    "Một trong những thí nghiệm này được mô tả ở Hình 2.5. Thí nghiệm cho thấy công A mà nước nhận được từ vật nặng chuyển động làm quay các cánh cản khiến nước nóng lên (nội năng của nước tăng) có độ lớn tương đương với độ tăng nội năng của nước.",
    "Vào thời kì đó, người ta chưa đo được phần nhiệt lượng mà nước truyền cho các thiết bị thí nghiệm và môi trường xung quanh. Nếu tính cả phần nhiệt lượng này thì: $\\Delta$U = A + Q với Q có giá trị âm vì vật truyền nhiệt cho môi trường.",
    "",
    "[Hình 2.5. Sơ đồ mô tả thí nghiệm của Joule]",
    "",
    "12",
    "CHƯƠNG I – VẬT LÍ NHIỆT",
    "",
    "**Hoạt động**",
    "Định luật I của nhiệt động lực học có nhiều ứng dụng thực tế, một trong những ứng dụng quan trọng là để chế tạo các loại động cơ nhiệt. Ngoài ra, định luật này còn dùng để giải thích các hiện tượng liên quan đến sự truyền và biến đổi nội năng.",
    "",
    "Động cơ nhiệt là động cơ hoạt động dựa trên nguyên tắc biến nội năng của nhiên liệu thành cơ năng.",
    "Mỗi động cơ nhiệt đều có ba bộ phận chính (Hình 2.6a):",
    "- Nguồn nóng có nhiệt độ T$_1$ cung cấp nhiệt lượng cho động cơ.",
    "- Bộ phận phát động trong đó tác nhân nhận nhiệt từ nguồn nóng, giãn nở sinh công (Trong máy hơi nước, tác nhân là hơi nước; trong động cơ đốt trong, tác nhân là khí do nhiên liệu bị đốt cháy toả ra trong xi lanh).",
    "- Nguồn lạnh có nhiệt độ T$_2$ < T$_1$ nhận nhiệt lượng do động cơ toả ra.",
    "Hãy dựa vào các sơ đồ trong Hình 2.6b, c để trình bày sơ lược về cấu tạo và hoạt động của máy hơi nước và động cơ đốt trong.",
    "",
    "[Hình 2.6a. Sơ đồ nguyên tắc hoạt động của động cơ nhiệt]",
    "Q$_1$: Nhiệt lượng tác nhân nhận được từ nguồn nóng.",
    "Q$_2$: Nhiệt lượng tác nhân truyền cho nguồn lạnh.",
    "A: Công cơ học (công do tác nhân thực hiện để đẩy pit-tông và công do pit-tông thực hiện để đưa tác nhân về trạng thái ban đầu)",
    "",
    "[Hình 2.6b. Sơ đồ nguyên tắc hoạt động của máy hơi nước]",
    "1. Nồi súp de (nguồn nóng)",
    "2. Xi lanh và pit-tông",
    "3. Bình ngưng hơi (nguồn lạnh)",
    "",
    "[Hình 2.6c. Sơ đồ nguyên tắc hoạt động của động cơ đốt trong]",
    "1. Xi lanh",
    "2. Pit-tông",
    "3. Bu-gi (tạo tia lửa điện đốt cháy hỗn hợp nhiên liệu và không khí)",
    "",
    "13",
    "CHƯƠNG I – VẬT LÍ NHIỆT",
    "",
    "**? Câu hỏi:**",
    "1. Nội năng của vật biến đổi như thế nào trong các trường hợp sau:",
    "a) Vật rắn đang nóng chảy.",
    "b) Nước đá đang tan.",
    "c) Hơi nước ngưng tụ ở nhiệt độ không đổi.",
    "2. Một vật khối lượng 1 kg trượt không vận tốc ban đầu từ đỉnh xuống chân một mặt phẳng dài 21 m, nghiêng 30$^\\circ$ so với mặt nằm ngang. Tốc độ của vật ở chân mặt phẳng là 4,1 m/s. Tính công của lực ma sát và độ biến thiên nội năng của vật trong quá trình chuyển động trên. Lấy g = 9,8 m/s$^2$. Bỏ qua sự trao đổi nhiệt với mặt phẳng nghiêng.",
    "",
    "**EM ĐÃ HỌC**",
    "- Tổng động năng và thế năng của các phân tử cấu tạo nên vật được gọi là nội năng của vật. Nội năng được kí hiệu bằng chữ U và có đơn vị là jun (J).",
    "- Có thể làm thay đổi nội năng của vật bằng cách: thực hiện công, truyền nhiệt.",
    "- Định luật I của nhiệt động lực học: Độ biến thiên nội năng của vật bằng tổng công và nhiệt lượng vật nhận được: $\\Delta$U = A + Q.",
    "Quy ước về dấu của A và Q:",
    "Q > 0: Vật nhận nhiệt lượng từ vật khác.",
    "Q < 0: Vật truyền nhiệt lượng cho vật khác.",
    "A > 0: Vật nhận công từ vật khác.",
    "A < 0: Vật thực hiện công lên vật khác.",
    "",
    "**EM CÓ THỂ**",
    "- Dùng mô hình động học phân tử giải thích được một số hiện tượng liên quan đến sự chuyển thể của các chất.",
    "- Dùng khái niệm nội năng và định luật I của nhiệt động lực học để giải thích một số hiện tượng đơn giản như sự chuyển hoá năng lượng trong các quá trình chuyển thể, nguyên tắc hoạt động của động cơ nhiệt (máy hơi nước, động cơ đốt trong).",
    "",
    "14"
  ]
}
