INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH1' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI12')), 'B3', 'Nhiệt độ. Thang nhiệt độ – Nhiệt kế', 17, 3, $JSON$
{
  "content": [
    "# Bài 3 NHIỆT ĐỘ. THANG NHIỆT ĐỘ – NHIỆT KẾ",
    "",
    "**Khởi động:**",
    "*Làm thế nào để nhận biết được sự truyền nhiệt năng giữa các vật? Ví dụ, làm thế nào để nhận biết: \"Vật nào là vật truyền nhiệt năng, vật nào là vật nhận nhiệt năng; sự truyền nhiệt năng đã dừng lại hay còn đang tiếp tục;...\"?*",
    "",
    "## I. KHÁI NIỆM NHIỆT ĐỘ",
    "Thí nghiệm sau đây sẽ giúp chúng ta hiểu được ý nghĩa của khái niệm nhiệt độ, nhận biết được khi nào có hoặc không có quá trình truyền nhiệt năng và chiều truyền nhiệt năng giữa hai vật tiếp xúc nhau.",
    "",
    "**Thí nghiệm**",
    "[Hình 3.1. Thí nghiệm sự truyền nhiệt năng]",
    "a) Ảnh chụp thí nghiệm",
    "b) Sơ đồ bố trí thí nghiệm",
    "(1) Cốc nhôm, (2) Bình cách nhiệt, (3) Hai nhiệt kế.",
    "",
    "*Chuẩn bị:*",
    "- Cốc nhôm đựng khoảng 200 mL nước ở nhiệt độ khoảng 30 $^\\circ$C (1).",
    "- Bình cách nhiệt đựng khoảng 500 mL nước ở nhiệt độ khoảng 60 $^\\circ$C (2).",
    "- Hai nhiệt kế (3).",
    "*Tiến hành:*",
    "- Đặt cốc nhôm vào trong lòng bình cách nhiệt sao cho nước trong bình cách nhiệt ngập một phần cốc nhôm (Hình 3.1).",
    "- Quan sát sự thay đổi nhiệt độ của nước trong bình và trong cốc từ khi bắt đầu thí nghiệm tới khi hai nhiệt độ này bằng nhau.",
    "*Trả lời các câu hỏi sau:*",
    "1. Tại sao có thể biết nước trong bình truyền nhiệt năng cho nước trong cốc?",
    "2. Làm thế nào để nhận biết quá trình truyền nhiệt năng giữa nước trong bình và nước trong cốc đã kết thúc?",
    "",
    "Từ kết quả trên có thể rút ra kết luận sau:",
    "Nhiệt độ cho biết trạng thái cân bằng nhiệt của các vật tiếp xúc nhau và chiều truyền nhiệt năng:",
    "- Khi hai vật có nhiệt độ chênh lệch tiếp xúc nhau thì nhiệt năng truyền từ vật có nhiệt độ cao hơn sang vật có nhiệt độ thấp hơn.",
    "- Khi hai vật có nhiệt độ bằng nhau tiếp xúc nhau thì không có sự truyền nhiệt năng giữa chúng. Hai vật ở trạng thái cân bằng nhiệt.",
    "",
    "15",
    "CHƯƠNG I – VẬT LÍ NHIỆT",
    "",
    "**? Câu hỏi:**",
    "Có thể nói khi hai vật tiếp xúc với nhau thì nhiệt năng luôn tự truyền từ vật có nội năng lớn hơn sang vật có nội năng nhỏ hơn hay không? Tại sao? Tìm ví dụ minh hoạ.",
    "",
    "## II. THANG NHIỆT ĐỘ – NHIỆT KẾ",
    "**1. Các thang nhiệt độ**",
    "*a) Thang nhiệt độ Celsius*",
    "Thang nhiệt độ chúng ta vẫn dùng hằng ngày là thang Celsius. Hai nhiệt độ dùng làm mốc của thang này là nhiệt độ đóng băng và nhiệt độ sôi của nước tinh khiết, ở áp suất tiêu chuẩn (Hình 3.2a). Khoảng cách giữa hai nhiệt độ này được chia thành 100 phần bằng nhau, mỗi phần là 1 độ. Vì được chia thành 100 phần bằng nhau nên ban đầu thang nhiệt độ này được gọi là thang nhiệt độ bách phân (centigrade).",
    "Năm 1948, Hội đồng quốc tế về trọng lượng và đo lường đã quyết định công nhận thang nhiệt độ này và đổi tên nó thành *thang nhiệt độ Celsius* để vinh danh nhà khoa học Thuỵ Điển Anders Celsius (An-đơ Xen-xi-út) (1701–1774), người đầu tiên xây dựng thang nhiệt độ này vào năm 1742.",
    "Nhiệt độ trong thang Celsius thường được kí hiệu bằng chữ t, đơn vị là độ C ($^\\circ$C ). Các nhiệt độ cao hơn 0 $^\\circ$C có giá trị dương, thấp hơn 0 $^\\circ$C có giá trị âm.",
    "",
    "[Hình 3.2. Các nhiệt độ mốc trong thang nhiệt độ Celsius và Kelvin]",
    "a) Thang Celsius: 100,00 $^\\circ$C (Điểm sôi của nước), 0 $^\\circ$C (Điểm ba của nước, Điểm đóng băng của nước), -273,15 $^\\circ$C (Độ không tuyệt đối).",
    "b) Thang Kelvin: 373,15 K (Điểm sôi của nước), 273,16 K (Điểm ba của nước), 273,15 K (Điểm đóng băng của nước), 0 K (Độ không tuyệt đối).",
    "",
    "Hiện nay, hầu hết các nước trên thế giới đều sử dụng thang nhiệt độ này, trừ một số nước nói tiếng Anh vẫn sử dụng thang nhiệt độ Fahrenheit do nhà khoa học người Đức Gabriel Fahrenheit (Ga-bri-en Pha-ren-hai) (1686 – 1736) xây dựng năm 1714.",
    "",
    "*b) Thang nhiệt độ Kelvin*",
    "Năm 1848, nhà vật lí người Ireland là William Thomson (Wi-li-am Tôm-sơn) – Nam tước Kelvin thứ nhất (1824 – 1907) đề xuất một thang nhiệt độ trong đó mọi nhiệt độ đều có giá trị dương. Hai nhiệt độ được dùng làm mốc là:",
    "1. Nhiệt độ thấp nhất mà các vật có thể có. Không có vật ở bất kì trạng thái nào có thể có nhiệt độ thấp hơn nhiệt độ này. Nhiệt độ này được gọi là \"*Độ không tuyệt đối*\" vì thế thang nhiệt độ này được gọi là *Thang nhiệt độ tuyệt đối*. Ở nhiệt độ không tuyệt đối, tất cả các chất đều có động năng chuyển động nhiệt của các phân tử bằng 0 và thế năng của chúng là tối thiểu. Người ta xác định được giá trị của độ không tuyệt đối trong thang Celsius là –273,15 $^\\circ$C. Cách xác định và ý nghĩa của độ không tuyệt đối sẽ được giới thiệu trong bài Định luật Charles (Bài 10) ở chương sau.",
    "2. Nhiệt độ mà nước tinh khiết có thể tồn tại đồng thời ở cả ba thể rắn, lỏng và hơi, trong trạng thái cân bằng nhiệt ở áp suất tiêu chuẩn (nhiệt độ này có độ lớn là 0,01 $^\\circ$C), được gọi là nhiệt độ *điểm ba của nước* (Hình 3.2b).",
    "",
    "16",
    "CHƯƠNG I – VẬT LÍ NHIỆT",
    "",
    "Hình 3.2 cho thấy mối quan hệ giữa các nhiệt độ của mốc trong thang nhiệt độ Celsius và Kelvin.",
    "",
    "[Hình 3.3. Nhiệt độ của một số sự vật, hiện tượng, quá trình]",
    "Thang Celsius ($^\\circ$C):",
    "100$^\\circ$C",
    "80$^\\circ$C (79$^\\circ$C Điểm sôi của rượu etylic)",
    "60$^\\circ$C (60$^\\circ$C Nhiệt độ của nước có thể làm bỏng tay khi nhúng vào)",
    "40$^\\circ$C (37$^\\circ$C Nhiệt độ của cơ thể người khoẻ mạnh)",
    "20$^\\circ$C (25$^\\circ$C Nhiệt độ không khí vào ngày mát mẻ)",
    "0$^\\circ$C",
    "",
    "Thang Kelvin (K):",
    "Lõi của Mặt Trời",
    "5772 K (Bề mặt của Mặt Trời)",
    "4000 K (Lõi của Trái Đất)",
    "1500 K (Nóng sáng)",
    "1340 K (Điểm nóng chảy của vàng)",
    "630 K (Điểm sôi của thuỷ ngân)",
    "505 K (Điểm nóng chảy của thiếc)",
    "373 K = 100$^\\circ$C (Điểm hoá hơi của nước)",
    "273 K = 0$^\\circ$C (Điểm đông đặc của nước)",
    "156 K (Điểm sôi của rượu etylic)",
    "90 K (Điểm sôi của oxygen)",
    "20 K (Điểm sôi của hydrogen)",
    "0 K = (-273,15$^\\circ$C) (Độ không tuyệt đối)",
    "",
    "Năm 1954, Hội đồng quốc tế về trọng lượng và đo lường đã chính thức công nhận thang nhiệt độ tuyệt đối, gọi thang này là thang nhiệt độ Kelvin, nhiệt độ trong thang được gọi là nhiệt độ nhiệt động lực học, có đơn vị đo là Kelvin (K). Mỗi độ chia (1 K) trong thang nhiệt độ Kelvin có độ lớn bằng $\\frac{1}{273,16}$ khoảng cách giữa hai nhiệt độ mốc của thang nhiệt độ này.",
    "",
    "**Hoạt động**",
    "Hình 3.3 giới thiệu nhiệt độ của một số sự vật, hiện tượng, quá trình.",
    "1. Nhiệt độ không tuyệt đối là nhiệt độ nào trong hai thang nhiệt độ Celsius và Kelvin?",
    "2. Nêu ý nghĩa của nhiệt độ không tuyệt đối.",
    "3. Hãy dựa vào bảng so sánh hai thang nhiệt độ Celsius và Kelvin ở Hình 3.2 để chứng minh rằng: mỗi độ chia (1 $^\\circ$C) trong thang nhiệt độ Celsius có độ lớn bằng 1 độ chia (1K) trong thang nhiệt độ Kelvin.",
    "4. Chứng minh công thức chuyển nhiệt độ từ thang Celsius sang thang Kelvin và ngược lại:",
    "t ($^\\circ$C) = T (K) – 273,15",
    "T (K) = t ($^\\circ$C) + 273,15.",
    "",
    "17",
    "CHƯƠNG I – VẬT LÍ NHIỆT",
    "",
    "**! Những điều cần lưu ý.**",
    "Người ta thường làm tròn số như sau:",
    "t ($^\\circ$C) = T (K) – 273 (1)",
    "T (K) = t ($^\\circ$C) + 273 (2)",
    "",
    "**? Câu hỏi:**",
    "1. Chuyển đổi nhiệt độ:",
    "a) Từ thang Celsius sang thang Kelvin: 270 $^\\circ$C; –270 $^\\circ$C; 500 $^\\circ$C.",
    "b) Từ thang Kelvin sang thang Celsius: 0 K; 500 K; 1 000 K.",
    "2. Một vật được làm lạnh từ 100 $^\\circ$C xuống 0 $^\\circ$C. Hỏi nhiệt độ của vật theo thang Kelvin giảm đi bao nhiêu độ?",
    "3. Thang nhiệt độ Kelvin có những ưu điểm gì so với thang nhiệt độ Celsius?",
    "",
    "**EM CÓ BIẾT**",
    "1. Một số nước nói tiếng Anh còn sử dụng thang nhiệt độ Fahrenheit. Trong thang này, nhiệt độ của nước đá đang tan là 32 $^\\circ$F, của nước đang sôi là 212 $^\\circ$F.",
    "Công thức chuyển đổi:",
    "t ($^\\circ$F) = 32 + 1,8t ($^\\circ$C).",
    "2. Trong nhiệt động lực học người ta coi nhiệt độ là đại lượng đặc trưng cho động năng trung bình của chuyển động nhiệt của phân tử. Động năng trung bình của các phân tử cấu tạo nên vật càng lớn thì nhiệt độ của vật càng cao.",
    "",
    "**2. Nhiệt kế**",
    "Nhiệt kế là thiết bị dùng để đo nhiệt độ. Nhiệt kế được chế tạo dựa trên một số tính chất vật lí phụ thuộc vào nhiệt độ của các chất, các vật liệu, các linh kiện điện và điện tử,...",
    "Tính chất vật lí được sử dụng nhiều trong trong việc chế tạo nhiệt kế là sự nở vì nhiệt.",
    "Các nhiệt kế thường dùng là các nhiệt kế được chế tạo dựa trên sự nở dài của cột chất lỏng trong ống thuỷ tinh (nhiệt kế rượu, nhiệt kế thuỷ ngân, nhiệt kế dầu). Sự nở dài của một thanh kim loại mỏng thẳng hoặc xoắn ốc được dùng trong việc chế tạo các loại nhiệt kế kim loại; sự nở vì nhiệt của thể tích một lượng khí xác định ở áp suất không đổi được dùng để chế tạo các loại nhiệt kế khí.",
    "",
    "**EM CÓ BIẾT**",
    "Các tính chất vật lí sau đây cũng đang được sử dụng một cách rộng rãi trong việc chế tạo nhiệt kế:",
    "- Sự phụ thuộc vào nhiệt độ của điện trở (nhất là điện trở nhiệt) theo các hệ thức khác nhau tuỳ theo phạm vi nhiệt độ cần đo và vật liệu làm điện trở. Ví dụ, trong phạm vi từ 0$^\\circ$ C đến 600$^\\circ$ C thì điện trở của một dây platin phụ thuộc vào nhiệt độ theo hệ thức R$_t$ = R$_0$(1 + At + Bt$^2$), trong đó các hệ số tỉ lệ A và B phụ thuộc vào cách lắp ráp điện trở.",
    "",
    "18",
    "CHƯƠNG I – VẬT LÍ NHIỆT",
    "",
    "- Sự phụ thuộc vào nhiệt độ của hiệu điện thế cặp nhiệt điện (U = kt, trong đó hệ số tỉ lệ k thay đổi tuỳ theo loại cặp nhiệt điện).",
    "- Sự phụ thuộc vào nhiệt độ của bước sóng của sóng điện từ theo hệ thức Wien: $\\lambda_{\\text{max}}.T = 2 900 \\text{ \\mu m.K}$ được dùng vào việc chế tạo các nhiệt kế thường dùng hằng ngày như nhiệt kế hồng ngoại, cũng như các nhiệt kế dùng trong thiên văn để đo nhiệt độ bề mặt các thiên thể.",
    "Việc sử dụng các linh kiện điện và điện tử có các tính chất vật lí phụ thuộc vào nhiệt độ để lắp các mạch điện cảm biến trong đó các thay đổi về tính chất của cảm biến theo nhiệt độ được chuyển thành các tín hiệu điện từ đang được sử dụng nhiều trong việc chế tạo các nhiệt kế dùng trong khoa học, kĩ thuật.",
    "",
    "**EM ĐÃ HỌC**",
    "- Nhiệt độ cho biết trạng thái cân bằng nhiệt của các vật tiếp xúc nhau và chiều truyền nhiệt năng.",
    "  - Khi hai vật có nhiệt độ chênh lệch tiếp xúc nhau thì nhiệt năng truyền từ vật có nhiệt độ cao sang vật có nhiệt độ thấp.",
    "  - Khi hai vật có nhiệt độ bằng nhau tiếp xúc nhau thì chúng ở trạng thái cân bằng nhiệt và không có sự truyền nhiệt năng giữa chúng.",
    "- Thang nhiệt độ Celsius có hai mốc là nhiệt độ đóng băng của nước tinh khiết (0 $^\\circ$C) và nhiệt độ sôi của nước tinh khiết (100 $^\\circ$C), ở áp suất tiêu chuẩn. Thang nhiệt độ Kelvin có hai mốc là nhiệt độ thấp nhất mà các vật có thể có được (0 K) và nhiệt độ mà nước tinh khiết có thể tồn tại đồng thời ở cả ba thể rắn, lỏng và hơi (273,16 K).",
    "- Công thức chuyển nhiệt độ từ thang Celsius sang thang Kelvin:",
    "T (K) = t ($^\\circ$C) + 273",
    "- Nhiệt kế là thiết bị đo nhiệt độ được chế tạo dựa trên một số tính chất vật lí phụ thuộc vào nhiệt độ.",
    "",
    "**EM CÓ THỂ**",
    "- Giải thích được các hiện tượng truyền nhiệt năng thường gặp trong đời sống.",
    "- Phân biệt được hai thang nhiệt độ Celsius và Kelvin.",
    "- Chuyển đổi được nhiệt độ Celsius sang nhiệt độ Kelvin và ngược lại.",
    "",
    "19"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH1' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI12')), 'B4', 'Nhiệt dung riêng', 22, 4, $JSON$
{
  "content": [
    "# Bài 4 NHIỆT DUNG RIÊNG",
    "",
    "**Khởi động:**",
    "*Nhiệt lượng cần để làm nóng 1 kg nước lên thêm 1 $^\\circ$C khác với nhiệt lượng cần để làm nóng 1 kg rượu lên thêm 1 $^\\circ$C. Đại lượng vật lí nào có thể dùng để mô tả sự khác biệt như trên của các chất khác nhau?*",
    "",
    "## I. KHÁI NIỆM NHIỆT DUNG RIÊNG",
    "**1. Hệ thức tính nhiệt lượng trong quá trình truyền nhiệt để làm thay đổi nhiệt độ của vật**",
    "Các hiện tượng quan sát được hằng ngày cho thấy độ lớn của nhiệt lượng cần cung cấp cho vật để làm tăng nhiệt độ của nó phụ thuộc vào các yếu tố sau:",
    "- Khối lượng của vật;",
    "- Độ tăng nhiệt độ của vật;",
    "- Tính chất của chất làm vật.",
    "",
    "**? Câu hỏi:**",
    "Hãy tìm ví dụ trong đời sống để minh hoạ cho nội dung trên.",
    "",
    "**Bảng 4.1. Giá trị gần đúng nhiệt dung riêng của một số chất**",
    "| Chất | Nhiệt dung riêng (J/kg.K) |",
    "|---|---|",
    "| Nước | 4 200 |",
    "| Nước đá | 2 100 |",
    "| Không khí | 1 000 |",
    "| Thuỷ tinh | 840 |",
    "| Đất | 800 |",
    "| Sắt | 440 |",
    "| Đồng | 380 |",
    "| Thuỷ ngân | 140 |",
    "| Chì | 130 |",
    "",
    "Các thí nghiệm chứng tỏ rằng nhiệt lượng Q cần cung cấp cho vật để làm nó nóng lên tỉ lệ thuận với khối lượng m và độ tăng nhiệt độ $\\Delta$t của vật nên:",
    "$\\frac{Q}{m\\Delta t} =$ hằng số (4.1)",
    "Trong đó: Q là nhiệt lượng cần truyền cho vật (J);",
    "m là khối lượng vật (kg);",
    "$\\Delta$T là độ tăng nhiệt độ của vật (K).",
    "Với mỗi chất, hằng số trong hệ thức trên có độ lớn riêng. Hằng số này gọi là nhiệt dung riêng của chất làm vật, kí hiệu là c, có giá trị là $c = \\frac{Q}{m\\Delta T}$ (4.2), đơn vị là J/kg.K.",
    "Do đó, hệ thức tính nhiệt lượng trong quá trình truyền nhiệt để làm thay đổi nhiệt độ của vật là:",
    "Q = mc$\\Delta$T (4.3)",
    "",
    "**2. Định nghĩa nhiệt dung riêng**",
    "Vì $c = \\frac{Q}{m\\Delta T}$ nên có thể định nghĩa nhiệt dung riêng của một chất như sau:",
    "",
    "20",
    "CHƯƠNG I – VẬT LÍ NHIỆT",
    "",
    "Nhiệt dung riêng của một chất là nhiệt lượng cần truyền cho 1 kg chất đó để làm cho nhiệt độ của nó tăng thêm 1 $^\\circ$C.",
    "Nhiệt dung riêng là thông tin quan trọng thường được dùng khi thiết kế các hệ thống làm mát, sưởi ấm,...",
    "",
    "**Hoạt động**",
    "1. Biết nhiệt dung riêng của nước lớn gấp hơn hai lần của dầu, tại sao trong bộ tản nhiệt (làm mát) của máy biến thế, người ta lại dùng dầu mà không dùng nước như trong bộ tản nhiệt của động cơ nhiệt?",
    "2. Hãy dựa vào giá trị của nhiệt dung riêng của nước và của đất trong Bảng 4.1 để giải thích tại sao ban ngày có gió mát thổi từ biển vào đất liền, ban đêm có gió ấm thổi từ đất liền ra biển.",
    "3. Một thùng đựng 20 lít nước ở nhiệt độ 20 $^\\circ$C. Cho khối lượng riêng của nước là 1 000 kg/m$^3$.",
    "a) Tính nhiệt lượng cần truyền cho nước trong thùng để nhiệt độ của nó tăng lên tới 70 $^\\circ$C.",
    "b) Tính thời gian truyền nhiệt lượng cần thiết nếu dùng một thiết bị điện có công suất 2,5 kW để đun lượng nước trên. Biết chỉ có 80% điện năng tiêu thụ được dùng để làm nóng nước.",
    "",
    "## II. THỰC HÀNH ĐO NHIỆT DUNG RIÊNG CỦA NƯỚC",
    "**1. Mục đích thí nghiệm**",
    "Xác định nhiệt dung riêng của nước.",
    "**2. Dụng cụ thí nghiệm**",
    "- Biến thế nguồn (1).",
    "- Bộ đo công suất nguồn điện (oát kế) có tích hợp chức năng đo thời gian (2).",
    "- Nhiệt kế điện tử hoặc cảm biến nhiệt độ có thang đo từ –20 $^\\circ$C đến 110 $^\\circ$C và độ phân giải $^{(*)}$ nhiệt độ $\\pm$ 0,1 $^\\circ$C (3).",
    "- Nhiệt lượng kế bằng nhựa có vỏ xốp, kèm dây điện trở (gắn ở mặt trong của nắp bình) (4).",
    "- Cân điện tử (5) (hoặc bình đong).",
    "- Các dây nối.",
    "",
    "[Hình 4.1. Bộ thí nghiệm thực hành đo nhiệt dung riêng của nước]",
    "",
    "**3. Thiết kế phương án thí nghiệm**",
    "**Hoạt động**",
    "Hãy trả lời các câu hỏi sau:",
    "- Từ hệ thức (4.3), cho biết cần đo đại lượng nào để xác định nhiệt dung riêng của nước?",
    "- Nhiệt lượng mà nước trong bình nhiệt lượng kế thu được lấy từ đâu?",
    "- Xác định nhiệt lượng mà nước thu được bằng cách nào?",
    "- Mô tả các bước tiến hành thí nghiệm.",
    "",
    "$^{(*)}$ Độ phân giải là sự thay đổi nhỏ nhất của đại lượng cần đo mà cảm biến có thể phát hiện được.",
    "",
    "21",
    "CHƯƠNG I – VẬT LÍ NHIỆT",
    "",
    "**4. Tiến hành thí nghiệm**",
    "- Đổ một lượng nước vào bình nhiệt lượng kế, sao cho toàn bộ dây điện trở chìm trong nước, xác định khối lượng nước này.",
    "- Cắm đầu đo của nhiệt kế vào nhiệt lượng kế.",
    "- Nối oát kế với nhiệt lượng kế và nguồn điện.",
    "- Bật nguồn điện.",
    "- Khuấy liên tục để nước nóng đều. Cứ sau mỗi khoảng thời gian 1 phút, đọc công suất dòng điện từ oát kế, nhiệt độ từ nhiệt kế rồi điền kết quả vào vở theo mẫu tương tự Bảng 4.2.",
    "- Tắt nguồn điện.",
    "",
    "**Bảng 4.2.** *Ví dụ về kết quả thí nghiệm đo nhiệt dung riêng của nước.*",
    "*Khối lượng nước m = 0,15 kg*",
    "| Nhiệt độ t ($^\\circ$C) | Thời gian $\\tau$ (s) | Công suất P (W) |",
    "|---|---|---|",
    "| 25,2 | 60 | 15,04 |",
    "| 25,4 | 120 | 15,07 |",
    "| 27,0 | 180 | 15,03 |",
    "| 28,7 | 240 | 15,94 |",
    "| 31,2 | 300 | 15,84 |",
    "| 32,3 | 360 | 15,94 |",
    "| 33,8 | 420 | 15,94 |",
    "",
    "**5. Kết quả thí nghiệm**",
    "**Hoạt động**",
    "- Vẽ đồ thị nhiệt độ t theo thời gian $\\tau$ và vẽ đường thẳng đi gần nhất các điểm thực nghiệm (tham khảo Hình 4.2).",
    "- Chọn hai điểm M, N trên đồ thị, xác định các giá trị thời gian $\\tau_M$, $\\tau_N$ và nhiệt độ t$_M$, t$_N$ tương ứng.",
    "",
    "[Hình 4.2. Đồ thị biểu diễn sự thay đổi nhiệt độ theo thời gian của nước trong bình nhiệt lượng kế được vẽ từ Bảng 4.2]",
    "",
    "22",
    "CHƯƠNG I – VẬT LÍ NHIỆT",
    "",
    "Từ kết quả thí nghiệm thu được, thực hiện yêu cầu sau:",
    "- Tính giá trị trung bình của công suất dòng điện.",
    "- Tính nhiệt dung riêng của nước theo hệ thức:",
    "$c_{H_2O} = \\frac{Q}{m\\Delta t} = \\frac{\\bar{P}(\\tau_N - \\tau_M)}{m(t_N - t_M)}$",
    "- Xác định sai số của phép đo nhiệt dung riêng của nước.",
    "- So sánh kết quả đo với nhiệt dung riêng của nước ở Bảng 4.1 và giải thích tại sao có sự sai khác (nếu có).",
    "",
    "**EM ĐÃ HỌC**",
    "- Nhiệt dung riêng của một chất là nhiệt lượng cần truyền cho 1 kg chất đó để làm cho nhiệt độ của nó tăng thêm 1 $^\\circ$C. Đơn vị của nhiệt dung riêng là: J/kg.K.",
    "- Hệ thức tính nhiệt lượng trong quá trình truyền nhiệt để làm thay đổi nhiệt độ của vật: Q = mc$\\Delta$T.",
    "- Cách xác định nhiệt dung riêng của nước.",
    "",
    "**EM CÓ THỂ**",
    "- Xác định được nhiệt dung riêng của một chất.",
    "- Dùng khái niệm nhiệt dung riêng để giải thích các hiện tượng thực tế có liên quan.",
    "",
    "**EM CÓ BIẾT**",
    "**Nhiệt dung riêng của nước**",
    "Nước là chất có nhiệt dung riêng lớn hơn nhiều so với các chất lỏng thông thường khác. Nhờ đó, nước có vai trò quan trọng đối với đời sống con người. Khoảng 70% bề mặt của Trái Đất được bao phủ bởi nước. Nhờ có nhiệt dung riêng lớn nên lượng nước này có thể hấp thụ lượng nhiệt khổng lồ của năng lượng mặt trời mà vẫn giữ cho nhiệt độ của bề mặt Trái Đất tăng không nhanh và không nhiều, tạo điều kiện thuận lợi cho sự sống của con người và các sinh vật khác. Cũng nhờ có nhiệt dung riêng lớn mà nước biển nóng lên và nguội đi chậm hơn các vùng đất xung quanh. Do sự ổn định này của nhiệt độ nước biển mà các đảo và các vùng đất ven biển có khí hậu tương đối ôn hoà, thích hợp với con người.",
    "Cũng nhờ có nhiệt dung riêng lớn mà nước thường được dùng trong các thiết bị làm mát của động cơ nhiệt.",
    "",
    "23"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH1' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI12')), 'B5', 'Nhiệt nóng chảy riêng', 26, 5, $JSON$
{
  "content": [
    "# Bài 5 NHIỆT NÓNG CHẢY RIÊNG",
    "",
    "**Khởi động:**",
    "*Khi vật bắt đầu nóng chảy phải tiếp tục cung cấp nhiệt lượng cho vật để vật nóng chảy hoàn toàn. Nhiệt lượng này phụ thuộc vào những đại lượng nào?*",
    "",
    "## I. KHÁI NIỆM NHIỆT NÓNG CHẢY RIÊNG",
    "**1. Hệ thức tính nhiệt lượng trong quá trình truyền nhiệt để làm vật nóng chảy hoàn toàn**",
    "Nhiệt lượng cần truyền cho vật khi vật bắt đầu nóng chảy tới khi vật nóng chảy hoàn toàn phụ thuộc vào khối lượng của vật và tính chất của chất làm vật.",
    "",
    "Thí nghiệm cho thấy nhiệt lượng này tỉ lệ thuận với khối lượng của vật:",
    "$\\frac{Q}{m} =$ hằng số (5.1)",
    "Trong đó: Q là nhiệt lượng cần truyền cho vật (J);",
    "m là khối lượng của vật (kg);",
    "Với mỗi chất, hằng số trong hệ thức (5.1) có độ lớn riêng. Hằng số này được gọi là nhiệt nóng chảy riêng của chất làm vật, kí hiệu là $\\lambda$, có giá trị là $\\lambda = \\frac{Q}{m}$ (5.2), đơn vị là J/kg.",
    "Do đó, hệ thức tính nhiệt lượng trong quá trình truyền nhiệt để làm vật nóng chảy hoàn toàn là:",
    "Q = $\\lambda$m (5.3)",
    "",
    "**Bảng 5.1. Giá trị gần đúng của nhiệt nóng chảy riêng ở nhiệt độ nóng chảy dưới áp suất tiêu chuẩn của một số chất**",
    "| Chất | Nhiệt độ nóng chảy ($^\\circ$C) | Nhiệt nóng chảy riêng (J/kg) |",
    "|---|---|---|",
    "| Nước đá | 0 | 3,34.10$^5$ |",
    "| Sắt | 1535 | 2,77.10$^5$ |",
    "| Đồng | 1084 | 1,80.10$^5$ |",
    "| Chì | 327 | 0,25.10$^5$ |",
    "",
    "**2. Định nghĩa nhiệt nóng chảy riêng**",
    "Vì $\\lambda = \\frac{Q}{m}$ nên có thể phát biểu định nghĩa nhiệt nóng chảy riêng của một chất như sau: Nhiệt nóng chảy riêng của một chất là nhiệt lượng cần để làm cho một kilôgam chất đó nóng chảy hoàn toàn ở nhiệt độ nóng chảy.",
    "Nhiệt nóng chảy riêng và nhiệt độ nóng chảy là những thông tin giúp xác định được năng lượng cần cung cấp cho lò nung, thời gian nung, thời điểm đổ kim loại nóng chảy vào khuôn, thời điểm lấy sản phẩm ra khỏi khuôn. Các đại lượng này cũng cần cho việc lựa chọn vật liệu chế tạo hợp kim phù hợp với từng yêu cầu sử dụng khác nhau, tách các kim loại nguyên chất ra khỏi quặng hỗn hợp,...",
    "",
    "**? Câu hỏi:**",
    "1. Tại sao khi chế tạo các vật bằng chì, đồng, thường hay dùng phương pháp đúc?",
    "2. Tính thời gian cần thiết để làm nóng chảy hoàn toàn 2 kg đồng có nhiệt độ ban đầu 30 $^\\circ$C, trong một lò nung điện có công suất 20 000 W. Biết chỉ có 50% năng lượng tiêu thụ của lò được dùng vào việc làm đồng nóng lên và nóng chảy hoàn toàn ở nhiệt độ không đổi.",
    "",
    "24",
    "CHƯƠNG I – VẬT LÍ NHIỆT",
    "",
    "## II. THỰC HÀNH ĐO NHIỆT NÓNG CHẢY RIÊNG CỦA NƯỚC ĐÁ",
    "**1. Mục đích thí nghiệm**",
    "Xác định nhiệt nóng chảy riêng của nước đá.",
    "**2. Dụng cụ thí nghiệm**",
    "- Bộ dụng cụ thí nghiệm như bài đo nhiệt dung riêng (Hình 4.1).",
    "- Các viên nước đá nhỏ và nước lạnh.",
    "**3. Thiết kế phương án thí nghiệm**",
    "",
    "**Hoạt động**",
    "Hãy trả lời các câu hỏi sau:",
    "- Từ công thức (5.3), hãy cho biết cần đo đại lượng nào để xác định nhiệt nóng chảy riêng của nước đá?",
    "- Nhiệt lượng làm các viên nước đá trong nhiệt lượng kế nóng chảy được lấy từ đâu?",
    "- Nhiệt lượng nước đá thu được trong bình nhiệt lượng kế được xác định bằng cách nào?",
    "- Mô tả các bước tiến hành thí nghiệm.",
    "",
    "**4. Tiến hành thí nghiệm**",
    "- Cho viên nước đá (khối lượng m kg) và một ít nước lạnh vào bình nhiệt lượng kế, sao cho toàn bộ điện trở chìm trong hỗn hợp nước và nước đá.",
    "- Cắm đầu đo của nhiệt kế vào bình nhiệt lượng kế.",
    "- Nối oát kế với nhiệt lượng kế và nguồn điện.",
    "- Bật nguồn điện.",
    "- Khuấy liên tục nước đá, cứ sau mỗi khoảng thời gian 2 phút lại đọc số đo thời gian trên oát kế và nhiệt độ trên nhiệt kế rồi ghi kết quả vào vở theo mẫu tương tự Bảng 5.2.",
    "- Tắt nguồn điện.",
    "",
    "**Bảng 5.2. Ví dụ về kết quả thí nghiệm đo nhiệt nóng chảy riêng của nước đá.**",
    "*Khối lượng nước đá m = 0,25 kg*",
    "| Thời gian $\\tau$ (s) | Nhiệt độ t ($^\\circ$C) | Công suất P (W) |",
    "|---|---|---|",
    "| 0 | 0 | 14,25 |",
    "| 120 | 0 | 14,23 |",
    "| 240 | 0 | 14,19 |",
    "| 360 | 0 | 14,25 |",
    "| 480 | 0 | 14,23 |",
    "| 600 | 0 | 14,24 |",
    "| 720 | 0,3 | 14,22 |",
    "| 840 | 0,8 | 14,32 |",
    "| 960 | 1,5 | 14,26 |",
    "",
    "[Hình 5.1. Đồ thị biểu diễn sự thay đổi nhiệt độ theo thời gian của nước trong bình nhiệt lượng kế từ số liệu Bảng 5.2]",
    "",
    "25",
    "CHƯƠNG I – VẬT LÍ NHIỆT",
    "",
    "**5. Kết quả thí nghiệm**",
    "**Hoạt động**",
    "Từ kết quả thí nghiệm thu được thực hiện yêu cầu sau:",
    "- Vẽ đồ thị sự phụ thuộc nhiệt độ t theo thời gian $\\tau$.",
    "- Vẽ hai đường thẳng đi gần nhất các điểm trên đồ thị (tham khảo Hình 5.1).",
    "- Chọn điểm M là giao điểm của hai đường thẳng, đọc giá trị $\\tau_M$.",
    "- Tính công suất trung bình $\\bar{P}$ của dòng điện qua điện trở trong nhiệt lượng kế.",
    "- Tính nhiệt nóng chảy riêng của nước đá theo công thức:",
    "$\\lambda_{H_2O} = \\frac{\\bar{P}\\tau_M}{m}$",
    "Trong đó $\\bar{P}\\tau_M$ là nhiệt lượng do dòng điện qua điện trở toả ra trong thời gian $\\tau_M$ và m là khối lượng nước đá.",
    "- Xác định sai số của phép đo nhiệt nóng chảy riêng của nước đá.",
    "- So sánh giá trị nhiệt nóng chảy riêng của nước đá đo được với giá trị ở Bảng 5.1 và giải thích nguyên nhân gây ra sự sai khác (nếu có).",
    "",
    "**EM ĐÃ HỌC**",
    "- Nhiệt nóng chảy riêng của một chất là nhiệt lượng cần để làm cho một kilôgam chất đó nóng chảy hoàn toàn ở nhiệt độ nóng chảy.",
    "- Đơn vị của nhiệt nóng chảy riêng là: J/kg.",
    "- Hệ thức tính nhiệt lượng trong quá trình truyền nhiệt để làm vật nóng chảy hoàn toàn ở nhiệt độ nóng chảy: Q = $\\lambda$m.",
    "- Cách xác định nhiệt nóng chảy riêng của nước đá.",
    "",
    "**EM CÓ THỂ**",
    "- Xác định được nhiệt nóng chảy riêng của một chất.",
    "- Dùng khái niệm nhiệt nóng chảy riêng để giải thích các hiện tượng thực tế có liên quan. Ví dụ: công nghệ phân kim (tách kim loại) bằng nóng chảy, dùng thiếc để hàn,...",
    "",
    "26"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH1' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI12')), 'B6', 'Nhiệt hoá hơi riêng', 29, 6, $JSON$
{
  "content": [
    "# Bài 6 NHIỆT HOÁ HƠI RIÊNG",
    "",
    "**Khởi động:**",
    "*Khi nước bắt đầu sôi, phải tiếp tục cung cấp nhiệt lượng cho nước để nước tiếp tục sôi (hoá hơi). Làm thế nào để xác định được độ lớn của nhiệt lượng làm hoá hơi hoàn toàn một lượng nước ở nhiệt độ không đổi?*",
    "",
    "## I. KHÁI NIỆM NHIỆT HOÁ HƠI RIÊNG",
    "**1. Hệ thức tính nhiệt lượng trong quá trình truyền nhiệt khi một lượng chất lỏng hoá hơi ở nhiệt độ không đổi**",
    "Nhiệt lượng cần cung cấp cho một lượng chất lỏng hoá hơi ở nhiệt độ không đổi phụ thuộc vào khối lượng và bản chất của chất lỏng. Thí nghiệm cho thấy nhiệt lượng này tỉ lệ thuận với khối lượng của chất lỏng:",
    "$\\frac{Q}{m} =$ hằng số (6.1)",
    "Trong đó: Q là nhiệt lượng cần truyền cho chất lỏng (J);",
    "m là khối lượng chất lỏng (kg);",
    "Với mỗi chất lỏng, hằng số trong hệ thức (6.1) có độ lớn riêng. Hằng số này được gọi là nhiệt hoá hơi riêng của chất lỏng, kí hiệu là L, có giá trị là L = $\\frac{Q}{m}$ (6.2), đơn vị là J/kg.",
    "",
    "**Bảng 6.1. Giá trị gần đúng của nhiệt hoá hơi ở nhiệt độ sôi dưới áp suất tiêu chuẩn của một số chất**",
    "| Chất | Nhiệt độ sôi ($^\\circ$C) | Nhiệt hoá hơi riêng (J/kg) |",
    "|---|---|---|",
    "| Nước | 100 | 2,26.10$^6$ |",
    "| Rượu | 78 | 8,57.10$^5$ |",
    "| Thuỷ ngân | 357 | 2,85.10$^5$ |",
    "| Ether | 34,5 | 0,40.10$^6$ |",
    "",
    "Do đó, hệ thức tính nhiệt lượng cần cung cấp cho một lượng chất lỏng hoá hơi hoàn toàn ở nhiệt độ không đổi là:",
    "Q = Lm (6.3)",
    "",
    "**2. Định nghĩa nhiệt hoá hơi riêng**",
    "Vì L = $\\frac{Q}{m}$ nên có thể định nghĩa nhiệt hoá hơi riêng của một chất lỏng ở một nhiệt độ xác định như sau: Nhiệt hoá hơi riêng của một chất lỏng là nhiệt lượng cần để làm cho một kilôgam chất lỏng đó hoá hơi hoàn toàn ở nhiệt độ xác định.",
    "",
    "**! Những điều cần lưu ý.**",
    "Chất lỏng có thể hoá hơi ở các nhiệt độ khác nhau. Thường thì nhiệt hoá hơi riêng của một chất tăng khi nhiệt độ giảm. Ví dụ, nhiệt hoá hơi riêng của nước ở 100 $^\\circ$C là 2,26.10$^6$ J/kg, ở 50 $^\\circ$C là 2,39.10$^6$ J/kg.",
    "",
    "Nhiệt hoá hơi riêng là thông tin cần thiết trong việc thiết kế, chế tạo các sản phẩm có sử dụng hiện tượng hoá hơi nhằm tiết kiệm năng lượng, bảo vệ môi trường. Ví dụ như các thiết bị làm lạnh (máy điều hoà nhiệt độ, dàn lạnh, dàn bay hơi,...), nồi hấp tiệt trùng trong y học, thiết bị xử lí rác thải ứng dụng công nghệ nhiệt hoá hơi,...",
    "",
    "27",
    "CHƯƠNG I – VẬT LÍ NHIỆT",
    "",
    "**Hoạt động**",
    "1. Tính nhiệt lượng cần thiết để làm cho 10 kg nước ở 25 $^\\circ$C chuyển hoàn toàn thành hơi ở 100 $^\\circ$C. Cho nhiệt dung riêng của nước là 4 200 J/kg.K; nhiệt hoá hơi riêng của nước ở 100 $^\\circ$C là 2,26.10$^6$ J/kg.",
    "2. Vận động viên chạy Marathon mất rất nhiều nước trong khi thi đấu. Các vận động viên thường chỉ có thể chuyển hoá khoảng 20% năng lượng hoá học dự trữ trong cơ thể thành năng lượng dùng cho các hoạt động của cơ thể, đặc biệt là hoạt động chạy. Phần năng lượng còn lại chuyển thành nhiệt thải ra ngoài nhờ sự bay hơi của nước qua hô hấp và da để giữ cho nhiệt độ của cơ thể không đổi. Nếu vận động viên dùng hết 11 000 kJ trong cuộc thi thì có khoảng bao nhiêu lít nước đã thoát ra khỏi cơ thể? Coi nhiệt độ cơ thể của vận động viên hoàn toàn không đổi và nhiệt hoá hơi riêng của nước trong cơ thể vận động viên là 2,45.10$^6$ J/kg.",
    "",
    "## II. THỰC HÀNH ĐO NHIỆT HOÁ HƠI RIÊNG CỦA NƯỚC",
    "**1. Mục đích thí nghiệm**",
    "Xác định nhiệt hoá hơi riêng của nước ở nhiệt độ sôi (100 $^\\circ$C).",
    "**2. Dụng cụ thí nghiệm**",
    "- Chuẩn bị bộ dụng cụ thí nghiệm như bài đo nhiệt dung riêng (Hình 4.1).",
    "- Một lượng nước nóng.",
    "**3. Thiết kế phương án thí nghiệm**",
    "",
    "**Hoạt động**",
    "Hãy trả lời các câu hỏi sau:",
    "- Từ công thức (6.3), cho biết cần đo đại lượng nào để xác định nhiệt hoá hơi riêng của nước?",
    "- Nhiệt lượng làm cho nước trong bình nhiệt lượng kế hoá hơi được lấy từ đâu?",
    "- Xác định nhiệt lượng nước trong bình nhiệt lượng kế thu được để hoá hơi bằng cách nào?",
    "- Mô tả các bước tiến hành thí nghiệm.",
    "- Để đảm bảo an toàn trong khi làm thí nghiệm cần phải chú ý điều gì?",
    "",
    "**4. Tiến hành thí nghiệm**",
    "- Đặt nhiệt lượng kế lên cân. Đổ nước nóng vào nhiệt lượng kế. Xác định khối lượng nước trong bình.",
    "- Tháo nắp bình ra khỏi nhiệt lượng kế.",
    "- Nối oát kế với điện trở và nguồn điện.",
    "- Đặt dây điện trở vào nhiệt lượng kế sao cho toàn bộ dây điện trở chìm trong nước.",
    "- Bật nguồn điện.",
    "- Đun sôi nước trong bình nhiệt lượng kế. Sau mỗi khoảng thời gian 2 phút, đọc số đo công suất trên oát kế, khối lượng nước trong bình nhiệt lượng kế trên cân. Ghi các kết quả vào vở theo mẫu tương tự Bảng 6.2.",
    "- Tắt nguồn điện.",
    "",
    "28",
    "CHƯƠNG I – VẬT LÍ NHIỆT",
    "",
    "**5. Kết quả thí nghiệm**",
    "**Bảng 6.2.** *Ví dụ về kết quả thí nghiệm đo nhiệt hoá hơi riêng của nước*",
    "| Thời gian $\\tau$ (s) | 0 | 120 | 240 | 360 | 480 | 600 | 720 | 840 |",
    "|---|---|---|---|---|---|---|---|---|",
    "| Công suất P (W) | 0 | 15,21 | 15,19 | 15,21 | 15,23 | 15,19 | 15,21 | 15,19 |",
    "| Khối lượng m (kg) | 0,1200 | 0,1191 | 0,1184 | 0,1179 | 0,1170 | 0,1161 | 0,1152 | 0,1141 |",
    "",
    "[Hình 6.1. Đồ thị quan hệ giữa khối lượng và thời gian của quá trình hoá hơi của nước được vẽ từ số liệu Bảng 6.2]",
    "",
    "**Hoạt động**",
    "Từ kết quả thí nghiệm thu được, thực hiện các yêu cầu sau:",
    "- Vẽ đồ thị khối lượng m theo thời gian $\\tau$.",
    "- Vẽ đường thẳng đi gần các điểm thực nghiệm nhất (tham khảo Hình 6.1). Chọn hai điểm P, Q tuỳ ý trên đồ thị, xác định giá trị khối lượng m$_P$, m$_Q$ và thời gian $\\tau_P$, $\\tau_Q$ tương ứng.",
    "- Tính công suất trung bình của dòng điện qua điện trở của nhiệt lượng kế.",
    "- Tính nhiệt hoá hơi riêng của nước theo công thức:",
    "$L = \\frac{Q}{m} = \\frac{\\bar{P}(\\tau_Q - \\tau_P)}{m_P - m_Q}$",
    "Trong đó $\\bar{P}(\\tau_Q - \\tau_P)$ là nhiệt lượng do dòng điện qua điện trở toả ra trong thời gian $\\tau_Q - \\tau_P$; $(m_P - m_Q)$ là khối lượng nước đã hoá hơi trong khoảng thời gian trên.",
    "- Xác định sai số của phép đo nhiệt hoá hơi riêng của nước.",
    "",
    "**EM ĐÃ HỌC**",
    "- Nhiệt hoá hơi riêng của một chất lỏng là nhiệt lượng cần để làm cho một kilôgam chất lỏng đó hoá hơi hoàn toàn ở nhiệt độ xác định.",
    "- Đơn vị của nhiệt hoá hơi riêng là: J/kg.",
    "- Hệ thức tính nhiệt lượng trong quá trình truyền nhiệt để làm chất lỏng hoá hơi hoàn toàn ở nhiệt độ xác định: Q = Lm.",
    "- Cách xác định nhiệt hoá hơi riêng của nước.",
    "",
    "**EM CÓ THỂ**",
    "- Xác định được nhiệt hoá hơi riêng của nước ở nhiệt độ sôi.",
    "- Sử dụng khái niệm nhiệt hoá hơi riêng để giải thích các hiện tượng có liên quan.",
    "",
    "**EM CÓ BIẾT**",
    "Người ta gọi nhiệt nóng chảy riêng và nhiệt hoá hơi riêng là \"ẩn nhiệt riêng\" vì sự truyền nhiệt trong các trường hợp này không được biểu hiện bằng sự thay đổi nhiệt độ.",
    "",
    "29"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH1' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI12')), 'B7', 'Bài tập về vật lí nhiệt', 32, 7, $JSON$
{
  "content": [
    "# Bài 7 BÀI TẬP VỀ VẬT LÍ NHIỆT",
    "",
    "**Khởi động:**",
    "*Để giải các bài tập Vật lí nhiệt cần đến những kiến thức và công thức cơ bản nào?*",
    "",
    "## I. MỘT SỐ LƯU Ý TRONG VIỆC GIẢI BÀI TẬP VỀ VẬT LÍ NHIỆT",
    "Phần vật lí nhiệt bao gồm ba nội dung chính: Cấu trúc của chất và sự chuyển thể; định luật I của Nhiệt động lực học; các khái niệm nhiệt dung riêng, nhiệt nóng chảy riêng và nhiệt hoá hơi riêng.",
    "**1. Lưu ý khi giải bài tập định tính**",
    "Các bài tập này thường yêu cầu vận dụng các kiến thức cơ bản của ba nội dung chính kể trên vào việc giải thích các hiện tượng, các ứng dụng thực tế giúp học sinh hiểu rõ bản chất vật lí của hiện tượng.",
    "**2. Lưu ý khi giải bài tập định lượng**",
    "Các bài tập này thường yêu cầu vận dụng định luật I của Nhiệt động lực học và định luật bảo toàn năng lượng vào các quá trình biến đổi nội năng của vật.",
    "Trong việc giải các bài tập này cần phải xác định được cách làm biến đổi nội năng của vật trong đề bài để lựa chọn được các hệ thức thích hợp.",
    "a) Khi nội năng của vật biến đổi chỉ bằng cách truyền nhiệt: $\\Delta$U = Q",
    "- Nếu quá trình truyền nhiệt chỉ làm thay đổi nhiệt độ của vật:",
    "Q = mc$\\Delta$T",
    "- Nếu quá trình truyền nhiệt làm vật chuyển từ thể này sang thể khác ở nhiệt độ không đổi:",
    "Q = $\\lambda$m; Q = Lm",
    "- Trong các quá trình này nếu có nhiều vật chỉ truyền nhiệt cho nhau không truyền nhiệt ra bên ngoài thì độ lớn của nhiệt lượng các vật toả ra bằng độ lớn nhiệt lượng của các vật thu vào:",
    "$|Q_{\\text{toả}}| = |Q_{\\text{thu}}| \\Rightarrow Q_{\\text{toả}} + Q_{\\text{thu}} = 0$",
    "b) Khi nội năng của vật biến đổi bằng cả hai cách truyền nhiệt và thực hiện công thì ngoài công thức: $\\Delta$U = Q + A, các công thức tính nhiệt lượng nêu trên còn phải sử dụng các công thức tính công cơ học đã học ở lớp 10 như: A = Fscos$\\alpha$; A = W$_{d2}$ – W$_{d1}$; A = mgh; A = Pt;...",
    "**3. Lưu ý khi giải bài tập thí nghiệm**",
    "Các bài tập này có thể yêu cầu từ thiết kế phương án đến tiến hành thí nghiệm và xử lí số liệu để rút ra kết luận cần thiết hoặc chỉ yêu cầu xử lí các số liệu đã cho từ thí nghiệm để rút ra kết luận cần thiết.",
    "",
    "30",
    "CHƯƠNG I – VẬT LÍ NHIỆT",
    "",
    "## II. BÀI TẬP VÍ DỤ",
    "1. Một lượng khí được truyền 10 kJ nhiệt năng để nóng lên đồng thời bị nén bởi một công có độ lớn 100 kJ. Tính độ biến thiên nội năng của lượng khí này.",
    "*Giải*",
    "Vì khí nhận được năng lượng và công nên: Q = +10 kJ và A = +100 kJ.",
    "Theo định luật I của nhiệt động lực học: $\\Delta$U = A + Q = 100 + 10 = 110 kJ.",
    "Độ biến thiên nội năng của lượng khí là: $\\Delta$U = 110 kJ.",
    "",
    "2. Người ta cung cấp nhiệt lượng 25 J cho một lượng khí trong một xi-lanh đặt nằm ngang. Lượng khí nở ra đẩy pit-tông chuyển động trong xi-lanh được 10 cm. Tính độ biến thiên nội năng của lượng khí. Biết lực ma sát giữa pit-tông và xi-lanh có độ lớn là 20 N và coi chuyển động của pit-tông trong xi lanh là đều.",
    "*Giải*",
    "Công mà lượng khí thực hiện để thắng lực ma sát có độ lớn là: A = Fs = 20.0,1 = 2 J.",
    "Áp dụng định luật I của nhiệt động lực học: $\\Delta$U = A + Q. Vì lượng khí thực hiện công nên A = –2 J; vì lượng khí nhận nhiệt lượng nên Q = +25 J.",
    "Do đó: $\\Delta$U = –2 + 25 = 23 J.",
    "Độ biến thiên nội năng của lượng khí là: $\\Delta$U = 23 J.",
    "",
    "3. Muốn có 30 lít nước ở nhiệt độ 40 $^\\circ$C thì cần phải đổ bao nhiêu lít nước đang sôi ở áp suất tiêu chuẩn vào bao nhiêu lít nước ở nhiệt độ 10 $^\\circ$C? Lấy khối lượng riêng của nước là 1 kg/lít; bỏ qua sự thay đổi khối lượng riêng của nước theo nhiệt độ và sự trao đổi nhiệt với bên ngoài.",
    "*Giải*",
    "Gọi m$_1$ là khối lượng của nước đang sôi ở 100 $^\\circ$C; m$_2$ là khối lượng của nước ở 10 $^\\circ$C.",
    "Nhiệt lượng nước sôi toả ra: Q$_1$ = m$_1$c$\\Delta$t$_1$ = m$_1$c(100 – 40) = 60m$_1$c.",
    "Nhiệt lượng nước ở 10$^\\circ$ C thu vào: Q$_2$ = m$_2$c$\\Delta$t$_2$ = m$_2$c (40 – 10) = 30m$_2$c.",
    "Vì không có sự trao đổi nhiệt với bên ngoài nên: Q$_1$ = Q$_2$, suy ra: 2m$_1$ = m$_2$. (1)",
    "Vì lượng nước muốn có là 30 lít, khối lượng riêng của của nước được coi là không đổi và bằng 1 kg/lít nên ta có: m$_1$ + m$_2$ = 30 kg. (2)",
    "Giải hệ hai phương trình (1) và (2) sẽ được: m$_1$ = 10 kg và m$_2$ = 20 kg.",
    "Vậy phải đổ 10 lít nước đang sôi vào 20 lít nước 10 $^\\circ$C để có 30 lít nước 40 $^\\circ$C.",
    "",
    "31",
    "CHƯƠNG I – VẬT LÍ NHIỆT",
    "",
    "## III. BÀI TẬP VẬN DỤNG",
    "1. Quy ước dấu nào sau đây phù hợp với định luật I của nhiệt động lực học?",
    "A. Vật nhận công: A < 0; vật nhận nhiệt lượng: Q < 0.",
    "B. Vật nhận công: A > 0; vật nhận nhiệt lượng: Q > 0.",
    "C. Vật thực hiện công: A > 0; vật truyền nhiệt lượng: Q > 0.",
    "D. Vật thực hiện công: A > 0; vật truyền nhiệt lượng: Q < 0.",
    "2. Một lượng nước và một lượng rượu có thể tích bằng nhau được cung cấp các nhiệt lượng tương ứng là Q$_1$ và Q$_2$. Biết khối lượng riêng của nước là 1 000 kg/m$^3$ và của rượu là 800 kg/m$^3$, nhiệt dung riêng của nước là 4 200 J/kg.K và của rượu là 2 500 J/kg.K. Để độ tăng nhiệt độ của nước và rượu bằng nhau thì:",
    "A. Q$_1$ = Q$_2$.",
    "B. Q$_1$ = 1,25 Q$_2$.",
    "C. Q$_1$ = 1,68 Q$_2$.",
    "D. Q$_1$ = 2.10 Q$_2$.",
    "3. Lấy hai túi trà lọc giống nhau. Thả nhẹ nhàng một túi vào cốc thuỷ tinh đựng nước nguội, một túi vào cốc thuỷ tinh đựng nước nóng để các túi nằm yên ở đáy cốc. Quan sát và dùng mô hình động học phân tử về cấu tạo chất để giải thích hiện tượng xảy ra trong hai cốc.",
    "4. a) Một ấm điện công suất 1 000 W. Tính thời gian cần thiết để đun 300 g nước có nhiệt độ ban đầu là 20 $^\\circ$C đến khi sôi ở áp suất tiêu chuẩn. Tại sao kết quả chỉ được coi là gần đúng?",
    "b) Nếu để nước trong ấm sôi thêm 2 phút thì lượng nước còn lại trong ấm là bao nhiêu? Lấy nhiệt dung riêng và nhiệt hoá hơi riêng của nước là c = 4,2.10$^3$ J/kg.K và L = 2,26.10$^6$ J/kg.",
    "5. Dùng bếp điện để đun một ấm nhôm khối lượng 600 g đựng 1,5 lít nước ở nhiệt độ 20 $^\\circ$C. Sau 35 phút đã có 20% lượng nước trong ấm hoá hơi ở nhiệt độ sôi 100 $^\\circ$C. Tính nhiệt lượng trung bình mà bếp điện cung cấp cho ấm nước trong mỗi giây, biết chỉ có 75% nhiệt lượng mà bếp toả ra được dùng vào việc đun ấm nước. Biết nhiệt dung riêng của nhôm là 880 J/kg.K, của nước là 4 200 J/kg.K; nhiệt hoá hơi riêng của nước ở nhiệt độ sôi 100 $^\\circ$C là 2,26.10$^6$ J/kg. Khối lượng riêng của nước là 1 kg/lít.",
    "",
    "**EM ĐÃ HỌC**",
    "- Cách giải bài tập về vật lí nhiệt.",
    "",
    "**EM CÓ THỂ**",
    "- Giải thích được các hiện tượng và tính toán được các đại lượng liên quan đến định luật I của nhiệt động lực học, các quá trình truyền nhiệt và chuyển thể.",
    "",
    "32"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH2' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI12')), 'B8', 'Mô hình động học phân tử chất khí', 36, 1, $JSON$
{
  "content": [
    "# Bài 8 MÔ HÌNH ĐỘNG HỌC PHÂN TỬ CHẤT KHÍ",
    "",
    "**Khởi động:**",
    "*Khi học môn Khoa học tự nhiên ở lớp 6, các em đã biết một số tính chất đặc biệt của chất ở thể khí so với chất ở thể lỏng và thể rắn. Tại sao chất ở thể khí lại có một số tính chất vật lí khác chính chất đó ở các thể khác?*",
    "",
    "## I. CHUYỂN ĐỘNG VÀ TƯƠNG TÁC CỦA CÁC PHÂN TỬ KHÍ",
    "**1. Chuyển động Brown trong chất khí**",
    "Chuyển động Brown không chỉ xảy ra trong chất lỏng mà xảy ra cả trong chất khí.",
    "Hình 8.1 vẽ sơ đồ thí nghiệm dùng để quan sát chuyển động Brown trong chất khí.",
    "",
    "[Hình 8.1. Sơ đồ thí nghiệm quan sát chuyển động Brown trong không khí]",
    "(1) Ống kính của kính hiển vi",
    "(2) Nắp đậy thuỷ tinh",
    "(3) Ống thuỷ tinh đựng khói",
    "(4) Ánh sáng",
    "(5) Khói",
    "",
    "**Hoạt động**",
    "1. Dựa vào Hình 8.1, hãy mô tả thí nghiệm dùng để quan sát chuyển động Brown trong không khí.",
    "2. Hãy dựa vào quỹ đạo chuyển động của hạt khói trong không khí (Hình 8.2) để chứng tỏ rằng các phân tử không khí chuyển động hỗn loạn, không ngừng.",
    "3. Khi quan sát tia nắng mặt trời chiếu qua cửa sổ vào trong phòng, ta có thể thấy các hạt bụi trong ánh nắng chuyển động không ngừng. Chuyển động này có phải là chuyển động Brown không? Tại sao?",
    "",
    "[Hình 8.2. Quỹ đạo chuyển động của hạt khói trong không khí]",
    "",
    "Thí nghiệm mô tả ở Hình 8.1 còn cho thấy, khi tăng nhiệt độ của không khí trong ống thuỷ tinh chứa khói thì các hạt khói chuyển động nhanh hơn.",
    "Từ thí nghiệm trên có thể rút ra các kết luận sau:",
    "- Chất khí được cấu tạo từ các phân tử chuyển động hỗn loạn, không ngừng.",
    "- Nhiệt độ của khí càng cao thì tốc độ chuyển động hỗn loạn của các phân tử khí càng lớn.",
    "",
    "**! Những điều cần lưu ý.**",
    "Trong khi chuyển động hỗn loạn, các phân tử khí không ngừng va chạm với nhau và với thành bình (Hình 8.3) nên tốc độ chuyển động của chúng không ngừng thay đổi. Do đó, tốc độ phân tử mà ta nói tới ở trên là tốc độ trung bình của các phân tử. Trong một khối khí có thể có các phân tử chuyển động nhanh hơn, bằng hoặc nhỏ hơn tốc độ trung bình. Người ta nói tốc độ chuyển động của phân tử có tính thống kê và chỉ có ý nghĩa khi có rất nhiều phân tử. Tốc độ này có độ lớn:",
    "$\\bar{v} = \\frac{v_1 + v_2 + ... + v_n}{n}$",
    "",
    "[Hình 8.3. Chuyển động và va chạm của các phân tử khí (C và D là các điểm mà các phân tử khí va chạm nhau)]",
    "",
    "34",
    "CHƯƠNG II – KHÍ LÍ TƯỞNG",
    "",
    "Ở điều kiện chuẩn [ T = 273 K (0 $^\\circ$C) và p = 1 atm (10$^5$ Pa)], các phân tử khí oxygen chuyển động với tốc độ trung bình vào khoảng 400 m/s.",
    "",
    "**2. Tương tác giữa các phân tử khí**",
    "Giữa các phân tử khí cũng có lực đẩy và lực hút, gọi chung là lực liên kết. Khoảng cách giữa các phân tử ở thể khí rất lớn so với ở thể lỏng và thể rắn nên lực liên kết giữa các phân tử ở thể khí rất yếu so với ở thể lỏng và thể rắn.",
    "",
    "**Hoạt động**",
    "1. Hãy nêu các hiện tượng thực tế chứng tỏ lực liên kết giữa các phân tử ở thể khí rất yếu so với ở thể lỏng và thể rắn.",
    "2. Hãy dựa vào khối lượng riêng ở cùng điều kiện nhiệt độ và áp suất của cùng một chất ở các thể khác nhau để chứng tỏ khoảng cách giữa các phân tử ở thể khí rất lớn so với ở thể lỏng và thể rắn.",
    "",
    "## II. MÔ HÌNH ĐỘNG HỌC PHÂN TỬ CHẤT KHÍ",
    "Từ các thí nghiệm và thực tế, người ta đưa ra mô hình động học phân tử chất khí:",
    "1. Chất khí được cấu tạo từ các phân tử có kích thước rất nhỏ so với khoảng cách giữa chúng. Lực liên kết giữa các phân tử ở thể khí rất yếu so với ở thể lỏng và thể rắn.",
    "2. Các phân tử khí chuyển động hỗn loạn, không ngừng. Chuyển động này càng nhanh thì nhiệt độ của khí càng cao.",
    "3. Khi chuyển động hỗn loạn, các phân tử khí va chạm với nhau và với thành bình. Khi va chạm với thành bình các phân tử khí tác dụng lực, gây áp suất lên thành bình.",
    "",
    "**Hoạt động**",
    "Hãy điền vào các ô còn trống trong Bảng 8.1.",
    "**Bảng 8.1.** *Bảng các thí nghiệm và hiện tượng thực tế làm cơ sở cho việc đưa ra mô hình động học phân tử chất khí*",
    "| STT | Mô hình động học phân tử chất khí | Các thí nghiệm và hiện tượng thực tế |",
    "|---|---|---|",
    "| 1 | Phân tử khí chuyển động hỗn loạn, không ngừng. | Chuyển động Brown trong không khí |",
    "| 2 | Kích thước của các phân tử khí rất nhỏ so với khoảng cách giữa chúng. | ? |",
    "| 3 | Khi chuyển động các phân tử khí va chạm với nhau và với thành bình. | ? |",
    "",
    "35",
    "CHƯƠNG II – KHÍ LÍ TƯỞNG",
    "",
    "## III. KHÍ LÍ TƯỞNG",
    "Để tìm hiểu các tính chất của chất khí, người ta dùng một mô hình khí đơn giản hơn khí thực (khí tồn tại trong thực tế) nhưng vẫn phản ánh được các đặc điểm cơ bản của khí này:",
    "1. Các phân tử khí được coi là các chất điểm, không tương tác với nhau khi chưa va chạm.",
    "2. Các phân tử khí tương tác khi va chạm với nhau và va chạm với thành bình. Các va chạm này là va chạm hoàn toàn đàn hồi.",
    "Mô hình trên bỏ qua thể tích của phân tử khí, bỏ qua tương tác của các phân tử khi chưa va chạm và coi va chạm là hoàn toàn đàn hồi làm cho việc mô tả các hiện tượng về chất khí trở nên đơn giản, dễ dàng. Chất khí trong mô hình trên được gọi là khí lí tưởng.",
    "",
    "**Hoạt động**",
    "Hãy dùng mô hình động học phân tử chất khí để chứng tỏ với một khối lượng khí xác định thì nếu giảm thể tích của bình chứa và giữ nguyên nhiệt độ khí thì áp suất của khí tác dụng lên thành bình tăng. Hãy tìm ví dụ trong thực tế để minh hoạ cho tính chất trên của chất khí.",
    "",
    "**EM ĐÃ HỌC**",
    "- Chất khí được cấu tạo từ các phân tử có kích thước rất nhỏ so với khoảng cách giữa chúng.",
    "- Các phân tử khí chuyển động hỗn loạn, không ngừng. Chuyển động này càng nhanh thì nhiệt độ của khí càng cao.",
    "- Khi chuyển động hỗn loạn, các phân tử khí va chạm với nhau và với thành bình. Khi va chạm với thành bình chất khí gây áp suất lên thành bình.",
    "",
    "**EM CÓ THỂ**",
    "Dùng thuyết động học phân tử chất khí để giải thích được các hiện tượng có liên quan. Ví dụ: chất khí luôn chiếm toàn bộ dung tích của bình chứa; chất khí gây áp suất lên thành bình theo mọi hướng; sự phụ thuộc áp suất của một lượng khí xác định tác dụng lên thành bình vào thể tích và nhiệt độ,...",
    "",
    "36"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH2' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI12')), 'B9', 'Định luật Boyle', 39, 2, $JSON$
{
  "content": [
    "# Bài 9 ĐỊNH LUẬT BOYLE",
    "",
    "**Khởi động:**",
    "*Khi thay đổi thể tích của một khối lượng khí xác định ở nhiệt độ không đổi thì áp suất khí thay đổi như thế nào?*",
    "",
    "## I. CÁC THÔNG SỐ TRẠNG THÁI CỦA MỘT LƯỢNG KHÍ",
    "Một lượng khí đựng trong một bình kín được xác định bởi bốn đại lượng là khối lượng (m), thể tích (V), nhiệt độ (T) và áp suất (p).",
    "Khi thể tích, nhiệt độ và áp suất của một khối lượng khí xác định không thay đổi, ta nói lượng khí ở trạng thái cân bằng. Thể tích, áp suất và nhiệt độ của lượng khí được gọi là các thông số trạng thái của nó.",
    "",
    "[Hình 9.1. Xác định các thông số trạng thái của một lượng khí]",
    "- Nhiệt kế",
    "- Áp kế",
    "",
    "**? Câu hỏi:**",
    "Các thông số trạng thái của một lượng khí đều là đại lượng có thể đo hoặc xác định được bằng các dụng cụ đo lường.",
    "1. Người ta dùng các dụng cụ nào để đo, xác định các thông số trạng thái của lượng khí trong hộp kín ở Hình 9.1?",
    "2. Nêu tên đơn vị của các đại lượng này trong hệ SI.",
    "",
    "Khí chuyển từ trạng thái này sang trạng thái khác bằng các quá trình biến đổi trạng thái, gọi tắt là quá trình.",
    "Người ta thường biểu diễn trạng thái và quá trình biến đổi trạng thái của một khối lượng khí xác định bằng Hình 9.2 dưới đây:",
    "Trạng thái 1: p$_1$, V$_1$, T$_1$ $\\rightarrow$ Trạng thái 2: p$_2$, V$_2$, T$_2$",
    "[Hình 9.2. Trạng thái và quá trình]",
    "",
    "**EM CÓ BIẾT?**",
    "Các phân tử khí chuyển động hỗn loạn, không ngừng nên vận tốc và số va chạm của các phân tử khí lên thành bình thay đổi theo thời gian và áp suất chất khí tác dụng lên thành bình tại các thời điểm khác nhau có thể khác nhau. Do đó, áp suất chất khí được hiểu là áp suất trung bình của các phân tử khí tác dụng lên thành bình.",
    "",
    "**? Câu hỏi:**",
    "Hãy so sánh các thông số trạng thái của không khí trong một quả bóng bay đã được bơm khi để trong bóng mát và khi để ngoài nắng (Hình 9.3).",
    "[Hình 9.3. Quả bóng bay khi để trong bóng mát (a), khi để ngoài nắng (b)]",
