    "b)",
    "",
    "37",
    "CHƯƠNG II – KHÍ LÍ TƯỞNG",
    "",
    "Trong hầu hết các quá trình biến đổi trạng thái của một khối lượng khí xác định thì cả ba thông số trạng thái (áp suất, thể tích, nhiệt độ) đều có thể biến đổi. Tuy nhiên, để thuận lợi cho việc tìm hiểu mối quan hệ giữa các thông số trạng thái, người ta thực hiện những quá trình đơn giản trong đó chỉ có hai thông số biến đổi còn một thông số không đổi, gọi là các đẳng quá trình.",
    "Các nhà vật lí đã dùng thí nghiệm để nghiên cứu các đẳng quá trình, xác định mối quan hệ của từng cặp thông số trạng thái, từ đó xây dựng phương trình về mối quan hệ giữa cả ba thông số.",
    "",
    "## II. ĐỊNH LUẬT BOYLE",
