    "pV = hằng số (9.1)",
    "Định luật trên được nhà vật lí và hoá học người Ireland là Robert Boyle (Rô-bớt Bôi-lơ) (1627-1691) tìm ra bằng thực nghiệm năm 1662 nên được gọi là định luật Boyle.",
