    "Đường đẳng nhiệt của cùng một lượng khí ứng với các nhiệt độ khác nhau thì khác nhau. Hình 9.6 vẽ hai đường đẳng nhiệt của cùng một lượng khí ứng với hai nhiệt độ T$_1$ và T$_2$, với T$_1$ < T$_2$.",
    "Nếu gọi p$_1$, V$_1$ là áp suất và thể tích của khí ở trạng thái 1; p$_2$, V$_2$ là áp suất và thể tích của khí ở trạng thái 2 thì:",
