    "2. Một bọt khí nổi từ đáy giếng sâu 6 m lên mặt nước. Khi lên tới mặt nước, thể tích của bọt khí tăng lên bao nhiêu lần? Coi áp suất khí quyển là 1,013.10$^5$ Pa; khối lượng riêng của nước giếng là 1 003 kg/m$^3$ và nhiệt độ của nước giếng không thay đổi theo độ sâu.",
    "",
    "**EM ĐÃ HỌC**",
