INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH2' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI12')), 'B10', 'Định luật Charles', 43, 3, $JSON$
{
  "content": [
    "# Bài 10 ĐỊNH LUẬT CHARLES",
    "",
    "**Khởi động:**",
    "*Khi giữ nguyên áp suất của một khối lượng khí xác định thì thể tích của khí phụ thuộc như thế nào vào nhiệt độ của nó?*",
    "",
    "## I. ĐỊNH LUẬT CHARLES",
    "**1. Quá trình đẳng áp**",
    "Quá trình biến đổi trạng thái của một khối lượng khí xác định khi giữ áp suất không đổi được gọi là quá trình đẳng áp.",
    "**2. Nghiên cứu của Charles**",
    "Năm 1787, nhà vật lí người Pháp là Charles (Sác-lơ) đã dùng thực nghiệm để nghiên cứu sự thay đổi thể tích theo nhiệt độ của một khối lượng khí xác định trong quá trình đẳng áp. Làm thí nghiệm với các chất khí khác nhau, ông nhận thấy khi tăng nhiệt độ khí từ t$_0$ = 0 $^\\circ$C tới t $^\\circ$C đồng thời giữ áp suất không đổi thì độ tăng thể tích của 1 đơn vị thể tích khí khi được tăng thêm 1 đơn vị nhiệt độ của các chất khí khác nhau đều bằng nhau và bằng $\\frac{1}{273}$:",
    "$\\frac{V - V_0}{V_0\\Delta t} = \\frac{1}{273}$ (10.1)",
    "Trong đó V$_0$ là thể tích khí ở nhiệt độ 0 $^\\circ$C; V là thể tích khí ở nhiệt độ t $^\\circ$C; $\\Delta$t là độ tăng nhiệt độ của khí.",
    "Nếu kí hiệu $\\alpha = \\frac{1}{273}$ thì V = V$_0$(1 + $\\alpha\\Delta$t)",
    "Vì $\\Delta$t = t – t$_0$ = t nên: V = V$_0$(1 + $\\alpha$t) (10.2)",
    "Đồ thị biểu diễn sự phụ thuộc của thể tích V theo nhiệt độ Celsius được vẽ ở Hình 10.1a.",
    "",
    "[Hình 10.1. Đồ thị biểu diễn sự thay đổi thể tích khí theo nhiệt độ]",
    "a) Đồ thị biểu diễn sự thay đổi thể tích khí theo nhiệt độ Celsius",
    "b) Đồ thị biểu diễn sự thay đổi thể tích khí theo nhiệt độ Kelvin",
    "",
    "**? Câu hỏi:**",
    "Hãy giải thích cách vẽ đồ thị của hàm: V = V$_0$(1 + $\\alpha$t) trong Hình 10.1a.",
    "",
    "Đồ thị vẽ ở Hình10.1a cho thấy đường biểu diễn không đi qua gốc toạ độ chứng tỏ thể tích V của khí không tăng tỉ lệ thuận với nhiệt độ Celsius.",
    "",
    "**Hoạt động**",
    "Hãy chứng tỏ rằng nếu đổi nhiệt độ Celcius t trong hệ thức (10.2) sang nhiệt độ Kelvin T tương ứng thì sẽ được một hệ thức mới chứng tỏ thể tích V của chất khí tỉ lệ thuận với nhiệt độ Kelvin: $\\frac{V}{T} = \\text{hằng số.}$",
    "",
    "41",
    "CHƯƠNG II – KHÍ LÍ TƯỞNG",
    "",
    "**3. Định luật Charles**",
    "Khi áp suất của một khối lượng khí xác định giữ không đổi thì thể tích của khí tỉ lệ thuận với nhiệt độ tuyệt đối của nó:",
    "$\\frac{V}{T} = \\text{hằng số.}$ (10.3)",
    "Nếu gọi V$_1$, T$_1$ lần lượt là thể tích và nhiệt độ tuyệt đối ở trạng thái 1; V$_2$, T$_2$ lần lượt là thể tích và nhiệt độ tuyệt đối ở trạng thái 2 thì: $\\frac{V_1}{T_1} = \\frac{V_2}{T_2}$ (10.4)",
    "Đồ thị biểu diễn định luật Chales như Hình 10.1b.",
    "",
