    "Đồ thị vẽ ở Hình 10.1a cho thấy nếu kéo dài đường biểu diễn thì đường này sẽ cắt trục nhiệt độ ở –273 $^\\circ$C. Ở nhiệt độ này, thể tích của lượng khí sẽ bằng 0. Điều này chứng tỏ người ta không thể hạ nhiệt độ xuống tới –273 $^\\circ$C vì thể tích của một lượng khí không thể bằng 0. Chính vì thế mà người ta gọi nhiệt độ này là *độ không tuyệt đối* và dùng nó làm mốc nhiệt độ thấp nhất của thang nhiệt độ Kelvin (0 K). Tính chất của các chất ở nhiệt độ này đã được nêu trong Bài 3, Chương I.",
    "",
    "**? Câu hỏi:**",
    "1. Ứng với các áp suất khác nhau của cùng một lượng khí, ta có những đường đẳng áp khác nhau. Hình 10.2 vẽ hai đường đẳng áp của cùng một lượng khí ứng với hai áp suất p$_1$ và p$_2$. Hãy so sánh p$_1$ và p$_2$.",
