    "",
    "## II. THÍ NGHIỆM MINH HOẠ ĐỊNH LUẬT CHARLES",
    "**Hoạt động**",
    "**Chuẩn bị:**",
    "- Xi lanh thuỷ tinh dung tích 50 mL, có độ chia nhỏ nhất 1 mL (1).",
