    "Bước 1: Cho một chút dầu bôi trơn vào pit-tông để pit-tông dễ dàng di chuyển trong xi lanh. Điều chỉnh pit-tông ở mức 30 mL, bịt đầu ra của xi lanh bằng nút cao su.",
    "",
