    "Các thí nghiệm thực hiện trong điều kiện áp suất rất cao và nhiệt độ rất thấp cho kết quả không phù hợp với các định luật trên.",
    "Để phân biệt khí lí tưởng với khí thực người ta định nghĩa *khí lí tưởng là khí tuân theo đúng các định luật Boyle và Charles.*",
    "Tuy nhiên, sự khác biệt giữa khí lí tưởng và khí thực không lớn ở điều kiện bình thường về áp suất và nhiệt độ nên người ta vẫn có thể áp dụng các định luật của khí lí tưởng cho khí thực nếu không cần độ chính xác cao.",
    "",
    "**EM ĐÃ HỌC**",
    "- Định luật Charles: Khi áp suất của một khối lượng khí xác định giữ không đổi thì thể tích của khí tỉ lệ thuận với nhiệt độ tuyệt đối của nó:",
    "$\\frac{V}{T} = \\text{hằng số hay } \\frac{V_1}{T_1} = \\frac{V_2}{T_2}$",
    "",
    "**EM CÓ THỂ**",
    "- Dùng định luật Charles giải thích được các hiện tượng thực tế có liên quan.",
    "",
    "44"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH2' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI12')), 'B11', 'Phương trình trạng thái của khí lí tưởng', 47, 4, $JSON$
{
  "content": [
    "# Bài 11 PHƯƠNG TRÌNH TRẠNG THÁI CỦA KHÍ LÍ TƯỞNG",
    "",
    "**Khởi động:**",
    "*Các định luật Boyle và Charles chỉ xác định mối liên hệ giữa hai cặp thông số “áp suất – thể tích” và “thể tích – nhiệt độ” của một khối lượng khí xác định. Vậy, làm thế nào để xác định được mối liên hệ của cả ba thông số trạng thái của một khối lượng khí xác định?*",
    "",
    "## I. PHƯƠNG TRÌNH TRẠNG THÁI CỦA KHÍ LÍ TƯỞNG",
    "**1. Phương trình trạng thái của một lượng khí xác định**",
    "",
    "[Hình 11.1. Quá trình chuyển từ trạng thái (1) qua trạng thái trung gian (1') tới trạng thái (2) của một khối lượng khí xác định]",
    "Trạng thái (1): p$_1$, V$_1$, T$_1$",
    "Đẳng nhiệt $\\rightarrow$ Trạng thái (1'): p$_2$, V$_1'$, T$_1$",
    "Đẳng áp $\\rightarrow$ Trạng thái (2): p$_2$, V$_2$, T$_2$",
    "",
    "**Hoạt động**",
    "Hãy dựa vào các định luật Boyle, Charles và Hình 11.1 vẽ quá trình chuyển trạng thái của một khối lượng khí xác định để lập phương trình dưới đây về mối liên hệ giữa ba thông số trạng thái của một khối lượng khí xác định:",
    "$\\frac{p_1V_1}{T_1} = \\frac{p_2V_2}{T_2} \\Rightarrow \\frac{pV}{T} = \\text{hằng số}$ (11.1)",
    "Độ lớn của hằng số trên phụ thuộc vào lượng khí ta xét.",
    "",
    "Phương trình (11.1) được gọi là phương trình trạng thái của một khối lượng khí lí tưởng xác định, thường gọi tắt là phương trình trạng thái của khí lí tưởng.",
    "",
    "**? Câu hỏi:**",
    "1. Hãy lập phương trình $\\frac{p_1V_1}{T_1} = \\frac{p_2V_2}{T_2}$ bằng một cách biến đổi trạng thái khác cách trong Hình 11.1 để chứng tỏ: Quá trình chuyển trạng thái không phụ thuộc cách chuyển trạng thái mà chỉ phụ thuộc trạng thái đầu và trạng thái cuối.",
    "2. Tại sao không gọi phương trình (11.1) là phương trình trạng thái của chất khí mà lại gọi là phương trình trạng thái của khí lí tưởng?",
    "",
    "**Hoạt động**",
    "1. Hãy biểu diễn bằng đồ thị trong hệ toạ độ (p – V) các quá trình chuyển trạng thái vẽ ở Hình 11.1.",
    "2. Từ phương trình trạng thái của khí lí tưởng suy ra hệ thức liên hệ giữa áp suất và nhiệt độ tuyệt đối trong quá trình đẳng tích.",
    "",
    "**Bài tập ví dụ:**",
    "Một cái bơm chứa 100 cm$^3$ không khí ở nhiệt độ 27 $^\\circ$C và áp suất 10$^5$ Pa. Tính áp suất của không khí trong bơm khi nó bị nén xuống còn 20 cm$^3$ và tăng nhiệt độ lên đến 39 $^\\circ$C.",
    "*Các bước giải:*",
    "1. Xác định tính chất của bài toán: Đây là bài toán mà cả ba thông số của một lượng khí đều thay đổi.",
    "2. Xác định các trạng thái của khí",
    "Trạng thái 1: p$_1$ = 10$^5$ Pa; V$_1$ = 100 cm$^3$; T$_1$ = 273 + 27 = 300 K.",
    "Trạng thái 2: p$_2$ = ?; V$_2$ = 20 cm$^3$; T$_2$ = 273 + 39 = 312 K.",
    "",
    "45",
    "CHƯƠNG II – KHÍ LÍ TƯỞNG",
    "",
    "Áp dụng phương trình trạng thái của một khối lượng khí xác định $\\frac{p_1V_1}{T_1} = \\frac{p_2V_2}{T_2}$, ta có:",
    "$p_2 = \\frac{p_1V_1T_2}{V_2T_1} = \\frac{10^5.100.312}{20.300} = 5,2.10^5 \\text{ Pa.}$",
    "",
    "**2. Phương trình Clapeyron**",
    "Có thể xác định được độ lớn của hằng số trong phương trình trạng thái của một lượng n mol khí xác định (n = $\\frac{m}{M}$, với m là khối lượng khí, M là khối lượng mol của lượng khí).",
    "Trước hết cần xác định độ lớn của hằng số này đối với 1 mol khí. Có thể dựa vào độ lớn của thể tích, áp suất và nhiệt độ của 1 mol khí ở điều kiện tiêu chuẩn để xác định độ lớn của hằng số đối với 1 mol khí.",
    "Một mol của bất kì khí nào ở điều kiện tiêu chuẩn đều có thể tích V = 22,4.10$^{-3}$ m$^3$; áp suất p = 1,013.10$^5$ Pa và nhiệt độ T = 273 K. Do đó, phương trình trạng thái của 1 mol khí là:",
    "$\\frac{pV}{T} = \\frac{1,013.10^5.22,4.10^{-3}}{273} = 8,31$",
    "R = 8,31 được gọi là *hằng số khí lí tưởng* và có đơn vị là J/mol.K.",
    "Vì thể tích của n mol khí bằng n thể tích của 1 mol khí ở cùng nhiệt độ và áp suất nên nếu phương trình trạng thái của 1 mol khí là $\\frac{pV}{T} = R$ thì phương trình trạng thái của n mol khí là:",
    "$\\frac{pV}{T} = nR$",
    "Độ lớn của nR là độ lớn của hằng số mà ta muốn xác định.",
    "Phương trình trên thường được viết dưới dạng:",
    "pV = nRT (11.2)",
    "Phương trình (11.2) là phương trình trạng thái của một lượng n mol khí lí tưởng, cũng thường được gọi tắt là phương trình trạng thái của khí lí tưởng. Nhà vật lí Clapeyron (Cla-pây-rông) người Pháp là người lập ra phương trình này nên nó còn được gọi là phương trình Clapeyron.",
    "",
    "## II. VẬN DỤNG",
    "Phương trình trạng thái của khí lí tưởng có nhiều ứng dụng thực tế. Nó được dùng vào việc nghiên cứu, chế tạo các thiết bị có liên quan đến chất khí như khí cầu, bình đựng khí, trang phục lặn, máy điều hoà không khí, máy nén khí,...; nghiên cứu sự thay đổi áp suất và thể tích của các lớp khí tồn tại trong các vật liệu để tìm tòi, sản xuất các vật liệu đáp ứng được các yêu cầu sử dụng khác nhau. Phương trình này còn được dùng trong việc nghiên cứu sự thay đổi áp suất, nhiệt độ, khối lượng riêng của không khí trong khí quyển, tìm hiểu quá trình biến đổi khí hậu để dự báo thời tiết,...",
    "",
    "46",
    "CHƯƠNG II – KHÍ LÍ TƯỞNG",
    "",
    "**Hoạt động**",
    "1. *Bóng thám không.* Bóng thám không được sử dụng để thu thập thông tin về môi trường không khí và thời tiết. Bóng thường được bơm khí hiếm nhẹ hơn không khí, nhờ đó có thể bay lên các tầng không khí khác nhau để thu thập thông tin về nhiệt độ, độ ẩm, áp suất, tốc độ gió,...",
    "Người ta muốn chế tạo một bóng thám không có thể tăng bán kính lên tới 10 m khi bay ở tầng khí quyển có áp suất 0,3.10$^5$ Pa và nhiệt độ 200 K. Hỏi bán kính của bóng khi vừa bơm xong phải bằng bao nhiêu? Biết bóng được bơm ở áp suất 1,02.10$^5$ Pa và nhiệt độ 300 K.",
    "2. *Túi khí.* Trong ô tô, người ta thường đặt ở hệ thống tay lái một thiết bị nhằm bảo vệ người lái xe khi xe gặp tai nạn, gọi là “túi khí”.",
    "Túi khí được chế tạo bằng vật liệu co giãn, chịu được áp suất lớn. Trong túi khí thường chứa chất NaN$_3$, khi xe va chạm mạnh vào vật cản thì hệ thống cảm biến của xe sẽ kích thích chất rắn này làm nó phân huỷ tạo thành Na và khí N$_2$. Khí N$_2$ được tạo thành có tác dụng làm phồng túi lên, giúp người lái xe không bị va chạm trực tiếp vào hệ thống lái (Hình 11.2).",
    "[Hình 11.2. Túi khí trong ô tô khi phồng lên]",
    "a) Viết phương trình phân huỷ NaN$_3$.",
    "b) Tính lượng chất khí N$_2$ được giải phóng khi xảy ra phản ứng phân huỷ NaN$_3$, biết trong túi chứa 100 g NaN$_3$ và thể tích mol là 24,0 lít /mol.",
    "c) Biết thể tích túi khí khi phồng lên có độ lớn tới 48 lít. Bỏ qua thể tích khí có trong túi trước khi phồng lên và thể tích của Na được tạo thành trong túi do phản ứng phân huỷ. Tính áp suất của khí N$_2$ trong túi khí khi đã phồng lên, biết nhiệt độ là 30 $^\\circ$C.",
    "",
    "**EM ĐÃ HỌC**",
    "- Phương trình trạng thái của một khối lượng khí lí tưởng xác định: $\\frac{pV}{T} = \\text{hằng số.}$",
    "Độ lớn của hằng số phụ thuộc vào lượng khí mà ta xét.",
    "- Phương trình trạng thái của khí lí tưởng (phương trình Clapeyron):",
    "pV = nRT",
    "Trong đó, R là hằng số khí lí tưởng (R = 8,31 J/mol.K); n là số mol khí:",
    "n = $\\frac{\\text{m(kg)}}{\\text{M(kg/mol)}}$",
    "",
    "**EM CÓ THỂ**",
    "Giải thích được một số hiện tượng, thiết bị có liên quan đến phương trình trạng thái của khí lí tưởng. Ví dụ: giải thích được cách sử dụng bình oxygen trong y tế, túi khí trên ô tô; tính được thể tích, khối lượng, nhiệt độ của chất khí tạo thành trong các phản ứng hoá học.",
    "",
    "47"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH2' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI12')), 'B12', 'Áp suất khí theo mô hình động học phân tử. Quan hệ giữa động năng phân tử và nhiệt độ', 50, 5, $JSON$
{
  "content": [
    "# Bài 12 ÁP SUẤT KHÍ THEO MÔ HÌNH ĐỘNG HỌC PHÂN TỬ. QUAN HỆ GIỮA ĐỘNG NĂNG PHÂN TỬ VÀ NHIỆT ĐỘ",
    "",
    "**Khởi động:**",
    "*Áp suất khí phụ thuộc như thế nào vào những đại lượng đặc trưng sau đây của phân tử: khối lượng phân tử, tốc độ chuyển động của phân tử, mật độ phân tử, lực liên kết phân tử?*",
    "",
    "## I. ÁP SUẤT KHÍ THEO MÔ HÌNH ĐỘNG HỌC PHÂN TỬ",
    "**1. Tác dụng của một phân tử khí lên thành bình**",
    "Xét một lượng khí gồm N phân tử chứa trong một bình lập phương có cạnh $l$, trong hệ toạ độ vuông góc Oxyz (Hình 12.1).",
    "Một phân tử khối lượng m chuyển động thẳng đều song song với trục Ox với tốc độ v từ thành bình EFOH tới va chạm đàn hồi và trực diện với thành bình ABCD. Sau khi va chạm, phân tử chuyển động theo chiều ngược lại với tốc độ có cùng độ lớn v tới thành bình đối diện.",
    "[Hình 12.1. Phân tử khí gây áp suất lên thành bình]",
    "",
    "Do độ lớn của vận tốc tức thời và tốc độ tức thời của một chuyển động có độ lớn bằng nhau nên động lượng của phân tử trước khi va chạm với thành bình có giá trị là + mv, sau khi va chạm với thành bình có giá trị là – mv. Độ biến thiên động lượng của phân tử do va chạm với thành bình ABCD có độ lớn là:",
    "$|\\Delta\\vec{p}| = |- mv - (+ mv)| = |- 2mv| = 2mv.$",
    "",
    "**Hoạt động**",
    "1. Tại sao có thể coi chuyển động của phân tử khí trước và sau khi va chạm với thành bình là chuyển động thẳng đều?",
    "2. Hãy dựa vào tính chất trên của chuyển động phân tử để tính thời gian $\\Delta$t giữa hai va chạm liên tiếp của một phân tử lên thành bình ABCD theo $l$ và v.",
    "Từ đó dùng công thức tính xung lượng của lực trong thời gian $\\Delta$t (đã học ở lớp 10) để chứng minh:",
    "a) Lực do thành bình ABCD tác dụng lên một phân tử khí có giá trị là $-\\frac{mv^2}{l}$; lực do một phân tử khí tác dụng lên thành bình ABCD có giá trị là $+\\frac{mv^2}{l}$.",
    "b) Áp suất do một phân tử khí tác dụng lên thành bình ABCD có giá trị là: $p_m = \\frac{m}{V}v^2$ với thể tích lượng khí V = $l^3$.",
    "",
    "Như vậy vận dụng các định luật cơ học Newton vào mô hình khí lí tưởng có thể xác định được áp suất của một phân tử khí tác dụng lên thành bình là $p_m = \\frac{m}{V}v^2$, với v là tốc độ chuyển động của phân tử, V là thể tích của lượng khí.",
    "",
    "**! Chú ý về các kí hiệu:**",
    "- Động lượng kí hiệu là $\\vec{p}$.",
    "- Áp suất của một lượng khí kí hiệu là p.",
    "- Áp suất của một phân tử khí kí hiệu là $p_m$.",
    "",
    "48",
    "CHƯƠNG II – KHÍ LÍ TƯỞNG",
    "",
    "**2. Tác dụng của N phân tử khí lên thành bình**",
    "Vì số phân tử N vô cùng lớn và các phân tử chuyển động hỗn loạn trong bình nên các hướng Ox, Oy và Oz là bình đẳng. Do đó, số phân tử chuyển động theo hướng Ox, từ mặt EFOH sang mặt ABCD và ngược lại để gây áp suất lên hai mặt này chỉ bằng $\\frac{1}{3}$ số phân tử có trong bình ($\\frac{N}{3}$).",
    "Vì các phân tử chuyển động hỗn loạn nên tốc độ của các phân tử không bằng nhau, do đó áp suất của mỗi phân tử tác dụng lên thành bình cũng không bằng nhau. Trung bình mỗi phân tử tác dụng lên thành bình một áp suất $\\overline{p_m} = \\frac{m}{V}\\overline{v^2}$, trong đó:",
    "$\\overline{v^2} = \\frac{v_1^2 + v_2^2 + ... + v_N^2}{N}$",
    "Đại lượng này được gọi là “trung bình của các bình phương tốc độ”.",
    "Từ những lập luận trên ta có thể viết được công thức tính áp suất của khí trong bình tác dụng lên thành bình ABCD:",
    "$p = \\frac{N}{3}\\overline{p_m} = \\frac{1}{3}\\frac{Nm}{V}\\overline{v^2}$ (12.1)",
    "Trong đó $\\frac{N}{V}$ là số phân tử có trong một đơn vị thể tích, gọi là *mật độ phân tử*. Nếu kí hiệu mật độ phân tử là $\\mu$, động năng trung bình của phân tử là $\\overline{E_d} = \\frac{m\\overline{v^2}}{2}$ và thay $\\overline{E_d}$ vào (12.1) ta được:",
    "$p = \\frac{2}{3}\\mu\\overline{E_d}$ (12.2)",
    "Vì các mặt của hình lập phương là bình đẳng nên áp suất của chất khí tác dụng lên các mặt của bình đều như nhau và đều được xác định bằng các hệ thức (12.1), (12.2).",
    "",
    "**? Câu hỏi:**",
    "1. Hãy chứng tỏ hệ thức (12.1) phù hợp với định luật Boyle.",
    "2. Hệ thức (12.2) cho thấy áp suất chất khí tác dụng lên thành bình phụ thuộc vào mật độ phân tử và động năng trung bình của phân tử. Hãy giải thích tại sao.",
    "",
    "## II. MỐI QUAN HỆ GIỮA ĐỘNG NĂNG PHÂN TỬ VÀ NHIỆT ĐỘ",
    "**Hoạt động**",
    "Từ hai hệ thức pV = nRT và $p = \\frac{2}{3}\\mu\\overline{E_d}$, hãy rút ra hệ thức: $\\overline{E_d} = \\frac{3}{2}\\frac{R}{N_A}T$. Trong đó N$_A$ là số Avogadro (N$_A$ = $\\frac{N}{n}$).",
    "",
    "Vì R và N$_A$ đều là các hằng số có giá trị xác định, nên ta có thể tính được giá trị của hằng số k:",
    "$k = \\frac{R}{N_A} = \\frac{8,31 \\text{ J/molK}}{6,02.10^{23} \\text{ hạt/mol}} = 1,38.10^{-23} \\text{ J/K.}$",
    "Hằng số k được gọi là hằng số Boltzmann.",
    "",
    "49",
    "CHƯƠNG II – KHÍ LÍ TƯỞNG",
    "",
    "Do đó, động năng trung bình của phân tử được xác định bằng hệ thức:",
    "$\\overline{E_d} = \\frac{3}{2}kT$ (12.3)",
    "Từ hệ thức (12.3), ta thấy động năng trung bình của phân tử tỉ lệ thuận với nhiệt độ tuyệt đối.",
    "Từ đó có thể rút ra những hệ quả sau:",
    "- Các khí có bản chất khác nhau, khối lượng khác nhau nhưng nhiệt độ như nhau thì động năng trung bình của các phân tử bằng nhau.",
    "- Động năng trung bình của phân tử khí càng lớn thì nhiệt độ của khí càng cao.",
    "- Vì $\\overline{E_d}$ tỉ lệ thuận với T nên người ta có thể coi nhiệt độ tuyệt đối là số đo động năng trung bình của phân tử theo một đơn vị khác.",
    "",
    "**? Câu hỏi:**",
    "1. Hãy dùng các hệ thức (12.2) và (12.3) để giải thích tại sao áp suất trong quá trình đẳng tích của một lượng khí xác định tỉ lệ thuận với nhiệt độ tuyệt đối.",
    "2. Không khí chứa chủ yếu các phân tử khí nitrogen, oxygen và carbon dioxide. Hãy so sánh khối lượng, tốc độ trung bình, động năng trung bình của các phân tử khí trên trong một phòng có nhiệt độ không đổi.",
    "",
    "**EM CÓ BIẾT?**",
    "1. Hệ thức $\\overline{E_d} = \\frac{3}{2}kT$ được thành lập dựa trên mô hình của khí lí tưởng, trong đó phân tử được coi là chất điểm, chuyển động của phân tử là chuyển động tịnh tiến. Do đó, động năng trung bình trong hệ thức trên được gọi một cách đầy đủ là động năng tịnh tiến trung bình.",
    "Khi phân tử không được coi là chất điểm thì ngoài chuyển động tịnh tiến, phân tử còn có thể có chuyển động quay, chuyển động riêng của các nguyên tử trong phân tử, chuyển động riêng của các electron trong nguyên tử,... Khi đó cần thiết phải nêu rõ động năng trung bình trong biểu thức trên chỉ là động năng của chuyển động tịnh tiến của phân tử, gọi tắt là động năng tịnh tiến trung bình.",
    "2. Động năng tịnh tiến trung bình của phân tử có độ lớn bằng tổng động năng tịnh tiến của các phân tử chia cho số phân tử.",
    "$\\overline{E_d} = \\frac{\\frac{mv_1^2}{2} + \\frac{mv_2^2}{2} + ... + \\frac{mv_N^2}{2}}{N} = \\frac{m}{2}\\frac{(v_1^2 + v_2^2 + ... + v_N^2)}{N}$",
    "$\\Rightarrow \\overline{E_d} = \\frac{m\\overline{v^2}}{2}.$",
    "",
    "50",
    "CHƯƠNG II – KHÍ LÍ TƯỞNG",
    "",
    "Căn bậc hai của $\\overline{v^2}$ là $\\sqrt{\\overline{v^2}}$, độ lớn của đại lượng này không phải là trung bình cộng của các tốc độ của phân tử, nghĩa là không phải là tốc độ trung bình của các phân tử. Nó được gọi là *tốc độ căn quân phương* của phân tử.",
    "",
    "**EM ĐÃ HỌC**",
    "- Áp suất chất khí theo mô hình động học phân tử: $p = \\frac{1}{3}\\mu m\\overline{v^2} = \\frac{2}{3}\\mu\\overline{E_d}$.",
    "Trong đó $\\mu$ là mật độ phân tử khí ($\\mu = \\frac{N}{V}$), $\\overline{v^2}$ là trung bình của các bình phương tốc độ phân tử.",
    "- Liên hệ giữa động năng trung bình của phân tử và nhiệt độ: $\\overline{E_d} = \\frac{3}{2}kT$.",
    "Trong đó k là hằng số Boltzmann: k = 1,38.10$^{-23}$ J/K.",
    "",
    "**EM CÓ THỂ**",
    "- Giải thích được một số hiện tượng có liên quan đến áp suất theo mô hình phân tử. Ví dụ, tại sao trong quá trình đẳng tích áp suất tỉ lệ thuận với nhiệt độ, trong quá trình đẳng nhiệt áp suất tỉ lệ nghịch với thể tích,...",
    "",
    "51"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH2' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI12')), 'B13', 'Bài tập về khí lí tưởng', 54, 6, $JSON$
{
  "content": [
    "# Bài 13 BÀI TẬP VỀ KHÍ LÍ TƯỞNG",
    "",
    "**Khởi động:**",
    "*Để giải các bài tập về sự chuyển trạng thái của khí lí tưởng thì cần dùng những công thức nào? Nêu rõ ý nghĩa và cách dùng của từng công thức.*",
    "",
    "## I. MỘT SỐ LƯU Ý TRONG VIỆC GIẢI BÀI TẬP VỀ KHÍ LÍ TƯỞNG",
    "Phần khí lí tưởng bao gồm bốn nội dung chính: Mô hình động học phân tử chất khí, phương trình trạng thái của khí lí tưởng, áp suất khí theo mô hình động học phân tử và động năng phân tử",
    "**1. Lưu ý khi giải bài tập định tính**",
    "Các bài tập này thường yêu cầu vận dụng mô hình khí lí tưởng và mối quan hệ giữa các thông số trạng thái (p, V, T) để giải thích các hiện tượng, ứng dụng thực tế có liên quan. Khi giải các bài tập này cần lưu ý đến điều kiện về khối lượng khí xác định.",
    "**2. Lưu ý khi giải bài tập định lượng**",
    "Các bài tập định lượng chủ yếu là các bài tập về sự chuyển trạng thái của khí lí tưởng.",
    "Việc giải các bài tập này thường được tiến hành theo ba bước chính sau đây:",
    "1. Xác định lượng khí có thay đổi hay không, có biết khối lượng, khối lượng mol hoặc số mol của lượng khí hay không.",
    "2. Xác định trạng thái đầu, trạng thái cuối và quá trình chuyển trạng thái của lượng khí.",
    "3. Xác định các thông số đặc trưng cho lượng khí trong từng trạng thái như thể tích, áp suất, nhiệt độ, khối lượng, khối lượng mol, số mol.",
    "Dựa vào kết quả của ba bước trên để lựa chọn các hệ thức thích hợp cho việc giải bài tập.",
    "**3. Lưu ý khi giải bài tập thí nghiệm**",
    "Các bài tập thí nghiệm về chất khí thường tập trung vào yêu cầu xử lí số liệu đã cho từ thí nghiệm, biểu diễn bằng đồ thị mối quan hệ giữa các đại lượng p, V, T trong các hệ trục toạ độ khác nhau để rút ra những kết luận cần thiết, trả lời các câu hỏi của đề bài.",
    "",
    "## II. BÀI TẬP VÍ DỤ",
    "1. Một bình hình trụ dung tích 8 lít, đặt thẳng đứng, đậy kín bằng một nắp khối lượng 2 kg, đường kính 20 cm. Trong bình chứa khí ở nhiệt độ 100 $^\\circ$C và áp suất bằng áp suất khí quyển 10$^5$ Pa. Khi nhiệt độ trong bình giảm còn 20 $^\\circ$C thì:",
    "a) áp suất khí trong bình bằng bao nhiêu?",
    "b) muốn mở nắp bình cần một lực tối thiểu bằng bao nhiêu? Lấy g = 9,8 m/s$^2$.",
    "",
    "52",
    "CHƯƠNG II – KHÍ LÍ TƯỞNG",
    "",
    "*Giải*",
    "a) Khí trong bình có khối lượng và thể tích không đổi.",
    "- Trạng thái 1: V$_1$ = 8 L; T$_1$ = 373 K; p$_1$ = 10$^5$ Pa = 1,0.10$^5$ Pa.",
    "Trạng thái 2: V$_2$ = 8 L; T$_2$ = 293 K; p$_2$ = ?",
    "- Vì quá trình chuyển trạng thái là đẳng tích nên:",
    "$\\frac{p_1}{T_1} = \\frac{p_2}{T_2} \\Rightarrow p_2 = \\frac{p_1T_2}{T_1} = 7,86.10^4 \\text{ Pa} \\approx 7,9.10^4 \\text{ Pa.}$",
    "b) Muốn mở được nắp bình cần tác dụng vào nắp một lực tối thiểu để cùng với áp lực bên trong bình thắng trọng lực của nắp và áp lực của không khí bên ngoài:",
    "F + p$_2$S = mg + p$_1$S, với $S = \\frac{\\pi d^2}{4}$.",
    "F = 692 N.",
    "",
    "2. Hình 13.1 vẽ đường biểu diễn hai quá trình đẳng nhiệt của một lượng khí lí tưởng ở hai nhiệt độ T$_1$, T$_2$ trong hệ toạ độ (p, V). Hãy nêu cách so sánh T$_1$ và T$_2$.",
    "[Hình 13.1. Đường đẳng nhiệt]",
    "*Giải*",
    "- Từ M vẽ đường đẳng áp MC. Từ giao điểm của MC với hai đường đẳng nhiệt, kẻ đường vuông góc với trục OV ta sẽ được hai điểm V$_1$ và V$_2$ (Hình 13.2).",
    "- Hình 13.2 cho thấy: V$_1$ < V$_2$, vì quá trình chuyển từ trạng thái 1 sang trạng thái 2 là đẳng áp, suy ra T$_1$ < T$_2$.",
    "[Hình 13.2. So sánh nhiệt độ]",
    "",
    "3. Một bình kín có thể tích không đổi chứa một khối lượng khí m = 1,00 kg ở áp suất p$_1$ = 10$^7$ Pa. Lấy ở bình ra một lượng khí cho tới khi áp suất của khí còn lại trong bình là p$_2$ = 2,5.10$^6$ Pa. Tính khối lượng khí được lấy ra khỏi bình, biết nhiệt độ khí không đổi.",
    "*Giải*",
    "Lượng khí trong bài tập này có khối lượng đã biết và thay đổi khi chuyển trạng thái.",
    "Trong quá trình chuyển trạng thái có hai thông số không đổi là thể tích V và nhiệt độ T.",
    "- Lượng khí ban đầu m$_1$ = 1,00 kg có: V$_1$ = V; T$_1$ = T; p$_1$ = 10$^7$ Pa.",
    "Lượng khí còn lại m$_2$ = (m$_1$ – $\\Delta$m) có: V$_2$ = V; T$_2$ = T; p$_2$ = 2,5.10$^6$ Pa.",
    "- Viết phương trình trạng thái của khí lí tưởng cho hai lượng khí trên:",
    "$p_1V_1 = n_1RT_1 \\Rightarrow p_1V_1 = \\frac{m_1}{M}RT_1$ (1)",
    "$p_2V_2 = n_2RT_2 \\Rightarrow p_2V_2 = \\frac{m_2}{M}RT_2$ (2)",
    "Ta có: $\\Delta$m = m$_1$ – m$_2$ (3)",
    "Thay các giá trị đã biết vào (1), (2) và (3) tính được: $\\Delta$m = 0,75 kg.",
    "",
    "53",
    "CHƯƠNG II – KHÍ LÍ TƯỞNG",
    "",
    "**Hoạt động**",
    "1. Hãy giải bài tập ví dụ 2 bằng cách vẽ đường đẳng tích thay cho đường đẳng áp.",
    "2. Hãy dùng phương trình $\\frac{pV}{T} = \\text{hằng số}$ để giải Bài tập ví dụ 3.",
    "",
    "## III. BÀI TẬP VẬN DỤNG",
    "1. Một lượng khí ở điều kiện tiêu chuẩn có thể tích 2 m$^3$. Nếu nén đẳng nhiệt lượng khí này tới áp suất 5.10$^5$ Pa thì thể tích của lượng khí sẽ là",
    "A. 10 m$^3$.",
    "B. 1 m$^3$.",
    "C. 0,4 m$^3$.",
    "D. 4 m$^3$.",
    "2. Một bóng thám không có các bộ phận chính như mô tả ở Hình 13.3.",
    "a) Tại sao vỏ bóng phải được làm bằng chất liệu đàn hồi?",
    "b) Tại sao để bóng bay lên, người ta phải bơm vào bóng một loại khí có khối lượng riêng nhỏ hơn không khí?",
    "c) Bóng thám không thường chỉ bay lên tới độ cao khoảng từ 30 km đến 40 km là bị vỡ. Tại sao bóng bị vỡ?",
    "[Hình 13.3. Bóng thám không]",
    "- Vỏ bóng bằng chất liệu đàn hồi",
    "- Dù",
    "- Hộp đựng thiết bị đo",
    "3. Một bình dung tích 40 dm$^3$ chứa 3,96 kg khí oxygen. Hỏi ở nhiệt độ nào thì bình có thể bị vỡ, biết bình chỉ chịu được áp suất không quá 60 atm. Lấy khối lượng riêng của oxygen ở điều kiện tiêu chuẩn là 1,43 kg/m$^3$.",
    "4. Một bình chứa một chất khí được nén ở nhiệt độ 27 $^\\circ$C và áp suất 40 atm. Nếu nhiệt độ của khí giảm xuống còn 12 $^\\circ$C và một nửa lượng khí thoát ra khỏi bình thì áp suất khí sẽ bằng bao nhiêu?",
    "5. Hình 13.4 vẽ đường biểu diễn bốn quá trình chuyển trạng thái liên tiếp của một lượng khí trong hệ toạ độ (p,T): (1 $\\rightarrow$ 2); (2 $\\rightarrow$ 3); (3 $\\rightarrow$ 4); (4 $\\rightarrow$ 1). Hãy chứng tỏ rằng chỉ có một trong bốn quá trình trên là đẳng tích.",
    "[Hình 13.4. Quá trình chuyển trạng thái]",
    "",
    "**EM ĐÃ HỌC**",
    "- Cách giải các bài tập về khí lí tưởng.",
    "",
    "**EM CÓ THỂ**",
    "- Vận dụng được các phương trình trạng thái của khí lí tưởng để giải các bài tập có liên quan.",
    "",
    "54"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH3' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI12')), 'B14', 'Từ trường', 58, 1, $JSON$
{
  "content": [
    "# Bài 14 TỪ TRƯỜNG",
    "",
    "**Khởi động:**",
    "*Ta đã biết nam châm và dòng điện đều tác dụng lực lên kim nam châm. Vậy xung quanh dòng điện có tồn tại từ trường không? Tính chất cơ bản của từ trường là gì? Từ trường được biểu diễn như thế nào?*",
    "",
    "## I. TƯƠNG TÁC TỪ",
    "[Hình 14.1. Thí nghiệm về tương tác giữa nam châm với kim nam châm]",
    "a) Kim nam châm tự do",
    "b) Khi hai cực cùng tên lại gần nhau",
    "c) Khi hai cực khác tên lại gần nhau",
    "[Hình 14.2. Thí nghiệm của Oersted (Ơ-xtét) về tương tác giữa dòng điện và kim nam châm]",
    "[Hình 14.3. Thí nghiệm tương tác giữa hai dòng điện]",
    "",
    "**Hoạt động**",
    "1. Khi đưa hai cực cùng tên hay khác tên của một nam châm thẳng và kim nam châm lại gần nhau (Hình 14.1) thì chúng đẩy nhau hay hút nhau?",
    "2. Khi cho dòng điện chạy qua dây dẫn ta thấy kim nam châm lệch một góc so với phương ban đầu (Hình 14.2). Dự đoán điều gì xảy ra nếu ta đổi chiều dòng điện chạy qua dây dẫn. Trong thí nghiệm này, kim nam châm có tác dụng lực lên dòng điện không?",
    "3. Khi cho dòng điện chạy qua hai tấm kim loại mỏng, nhẹ như ở Hình 14.3, ta thấy hai tấm kim loại đẩy nhau. Hãy dự đoán hiện tượng xảy ra nếu dòng điện qua hai tấm kim loại cùng chiều.",
    "",
    "Tương tác giữa nam châm với nam châm, giữa dòng điện với nam châm và giữa dòng điện với dòng điện đều gọi là tương tác từ. Lực tương tác trong các trường hợp đó gọi là lực từ.",
    "",
    "## II. TỪ TRƯỜNG",
    "**1. Khái niệm từ trường**",
    "Các thí nghiệm ở trên cho thấy khi kim nam châm đặt gần một nam châm hay một dòng điện, thì có lực từ tác dụng lên kim nam châm. Ta nói, xung quanh nam châm, xung quanh dòng điện có từ trường.",
    "",
    "56",
    "CHƯƠNG III – TỪ TRƯỜNG",
    "",
    "Từ trường là trường lực gây ra bởi dòng điện hoặc nam châm, là một dạng của vật chất tồn tại xung quanh dòng điện hoặc nam châm mà biểu hiện cụ thể là sự xuất hiện của lực từ tác dụng lên một dòng điện hay một nam châm khác đặt trong nó.",
    "",
    "**Hoạt động**",
    "Hãy mô tả một thí nghiệm khảo sát lực từ do nam châm tác dụng lên dòng điện.",
    "",
    "**2. Tính chất cơ bản của từ trường**",
    "Tính chất cơ bản của từ trường là nó gây ra lực từ tác dụng lên một nam châm hay một dòng điện đặt trong nó. Nhờ tính chất này người ta dùng kim nam châm, gọi là nam châm thử để phát hiện sự tồn tại của từ trường.",
    "",
    "**3. Cảm ứng từ**",
    "- Để đặc trưng cho từ trường về mặt tác dụng lực người ta đưa vào một đại lượng vectơ gọi là cảm ứng từ, kí hiệu là $\\vec{B}$. Khi nam châm thử nằm cân bằng ở các điểm khác nhau trong từ trường thì nói chung nó định hướng theo các phương khác nhau. Điều đó gợi ý rằng có thể coi phương của nam châm thử nằm cân bằng tại một điểm trong từ trường là phương của vectơ cảm ứng từ $\\vec{B}$ của từ trường tại điểm đó. Người ta quy ước lấy chiều từ cực Nam sang cực Bắc của nam châm thử là chiều của vectơ cảm ứng từ $\\vec{B}$.",
    "- Ta thừa nhận rằng lực từ tác dụng lên một dòng điện (đoạn dây dẫn có dòng điện chạy qua) hay một nam châm đặt trong từ trường ở điểm nào lớn hơn thì cảm ứng từ tại điểm đó lớn hơn. Độ lớn của cảm ứng từ $\\vec{B}$ được xác định ở bài sau (xem Bài 15).",
    "- Từ trường đều là từ trường có cảm ứng từ $\\vec{B}$ tại mọi điểm đều bằng nhau.",
    "",
    "## III. ĐƯỜNG SỨC TỪ",
    "**1. Từ phổ**",
    "Để có thể thấy hình ảnh trực quan của từ trường, ta sử dụng các mạt sắt mịn. Các mạt sắt mịn đặt trong từ trường bị nhiễm từ khiến chúng trở thành các nam châm thử.",
    "",
    "**Hoạt động**",
    "**Thí nghiệm 1**",
    "*Chuẩn bị:*",
    "- Hộp nhựa có một mặt trong suốt, bên trong chứa dầu và mạt sắt mịn.",
    "- Nam châm thẳng.",
    "- Nam châm hình chữ U.",
    "*Tiến hành:*",
    "- Lắc nhẹ hộp nhựa sao cho các mạt sắt phân bố đều. Đặt hộp nhựa trên mặt phẳng nằm ngang, mặt trong suốt hướng lên trên.",
    "- Đặt nhẹ nhàng thanh nam châm thẳng lên trên mặt trong suốt của hộp nhựa rồi gõ nhẹ. Quan sát hình ảnh mạt sắt vừa được tạo thành trong hộp nhựa (Hình 14.4a).",
    "",
    "[Hình 14.4. Hình ảnh các mạt sắt phân bố xung quanh nam châm thẳng]",
    "a)",
    "b)",
    "c)",
    "",
    "57",
    "CHƯƠNG III – TỪ TRƯỜNG",
    "",
    "- Nhấc thanh nam châm thẳng lên khỏi mặt hộp nhựa. Lắc nhẹ hộp nhựa cho các mạt sắt phân bố đều trở lại. Tiếp tục đặt nhẹ nhàng hai thanh nam châm thẳng lên trên mặt trong suốt của hộp nhựa (sao cho hai cực trái dấu của hai thanh nam châm thẳng gần nhau) rồi gõ nhẹ. Quan sát hình ảnh mạt sắt vừa được tạo thành trong hộp nhựa (Hình 14.4b).",
    "- Thực hiện tương tự như trên nhưng cho hai cực cùng tên của hai thanh nam châm gần nhau. Quan sát hình ảnh mạt sắt vừa được tạo thành trong hộp nhựa (Hình 14.4c).",
    "- Tiến hành thí nghiệm tương tự đối với nam châm hình chữ U (Hình 14.5).",
    "*Thực hiện các yêu cầu sau:*",
    "1. Nhận xét hình ảnh sự phân bố mạt sắt ở khoảng giữa của hai nam châm thẳng Hình 14.4b và ở khoảng giữa của hai nam châm thẳng Hình 14.4c.",
    "2. Nhận xét về hình ảnh sự phân bố mạt sắt ở giữa hai cực của nam châm hình chữ U. Từ đó có thể rút ra kết luận gì về từ trường trong khoảng giữa hai cực của nam châm hình chữ U.",
    "",
    "[Hình 14.5. Hình ảnh các mạt sắt phân bố xung quanh nam châm hình chữ U]",
    "",
    "**Thí nghiệm 2**",
    "*Chuẩn bị:*",
    "- Hộp nhựa có một mặt trong suốt, bên trong chứa dầu và mạt sắt mịn.",
    "- Ống dây gắn với hộp nhựa.",
    "- Dây dẫn thẳng.",
    "- Nguồn điện một chiều.",
    "*Tiến hành:*",
    "- Lắc nhẹ hộp nhựa có gắn ống dây sao cho các mạt sắt phân bố đều ở bên ngoài và bên trong lòng ống dây.",
    "- Cho dòng điện chạy qua ống dây.",
    "- Gõ nhẹ vào hộp nhựa để các mạt sắt phân bố ổn định (Hình 14.6).",
    "Tiến hành thí nghiệm tương tự với dây dẫn thẳng ta thu được hình ảnh như Hình 14.7.",
    "*Thực hiện các yêu cầu sau:*",
    "1. Mô tả hình ảnh sự phân bố mạt sắt phân bố xung quanh dòng điện thẳng.",
    "2. Nhận xét về hình ảnh sự phân bố mạt sắt bên trong ống dây và bên ngoài ống dây.",
    "3. So sánh hình ảnh và sự phân bố mạt sắt ở bên ngoài ống dây với hình ảnh đường sức từ của nam châm thẳng.",
    "",
    "[Hình 14.6. Hình ảnh các mạt sắt phân bố bên trong và bên ngoài ống dây mang dòng điện]",
    "[Hình 14.7. Hình ảnh các mạt sắt phân bố xung quanh dòng điện thẳng]",
    "",
    "Hình ảnh những đường tạo ra bởi các mạt sắt trong các thí nghiệm trên được gọi là *từ phổ*. Từ phổ cho ta thấy hình ảnh trực quan của từ trường.",
    "",
    "58",
    "CHƯƠNG III – TỪ TRƯỜNG",
    "",
    "**2. Đường sức từ**",
    "Để biểu diễn về mặt hình học của từ trường trong không gian, người ta đưa ra khái niệm đường sức từ.",
    "*Đường sức từ là những đường vẽ ở trong không gian có từ trường sao cho tiếp tuyến với nó tại mỗi điểm trùng với phương của vectơ cảm ứng từ tại điểm đó. Chiều của đường sức từ là chiều của vectơ cảm ứng từ.*",
    "",
    "[Hình: a) Đường sức từ của nam châm thẳng]",
    "[Hình: b) Đường sức từ của nam châm hình chữ U]",
    "[Hình: c) Đường sức từ của dòng điện thẳng]",
    "[Hình: d) Đường sức từ của dòng điện chạy trong ống dây]",
    "Hình 14.8. Đường sức từ",
    "",
    "Đường sức từ vẽ trong Hình 14.8 tương ứng với các từ phổ của nam châm thẳng, nam châm hình chữ U, của dòng điện thẳng và dòng điện chạy qua ống dây.",
    "Đối với nam châm, các đường sức từ ở ngoài nam châm có chiều đi ra từ cực Bắc, đi vào cực Nam.",
    "- Các đặc điểm của đường sức từ:",
    "  + Tại mỗi điểm trong từ trường, chỉ có thể vẽ được một đường sức từ đi qua và chỉ một mà thôi.",
    "  + Các đường sức từ là những đường cong khép kín.",
    "  + Nơi nào từ trường mạnh hơn thì các đường sức từ ở đó vẽ dày hơn, nơi nào từ trường yếu hơn thì các đường sức từ vẽ thưa hơn.",
    "",
    "Dùng nam châm thử đặt trên đường sức từ, ta biết được chiều của đường sức từ (Hình 14.8). Ta cũng có thể xác định chiều của đường sức từ theo quy tắc nắm bàn tay phải như sau:",
    "+ *Đối với dòng điện thẳng:* Giơ ngón cái của bàn tay phải hướng theo chiều dòng điện, khum bốn ngón tay kia xung quanh dây dẫn thì chiều từ cổ tay đến bốn ngón tay đó là chiều của đường sức từ (Hình 14.9).",
    "",
    "[Hình 14.9. Quy tắc nắm bàn tay phải đối với dòng điện thẳng]",
    "",
    "59",
    "CHƯƠNG III – TỪ TRƯỜNG",
    "",
    "+ *Đối với dòng điện tròn và ống dây:* Khum bàn tay phải sao cho chiều từ cổ tay đến các ngón tay trùng với chiều dòng điện chạy qua các vòng dây thì chiều ngón tay cái choãi ra chỉ chiều của đường sức từ (Hình 14.10).",
    "",
    "[Hình 14.10. Quy tắc nắm bàn tay phải đối với dòng điện tròn]",
    "",
    "**? Câu hỏi:**",
    "Đặt một kim nam châm nhỏ trên mặt phẳng vuông góc với dòng điện thẳng. Khi cân bằng, kim nam châm nằm ở vị trí như Hình 14.11. Hãy xác định chiều của dòng điện chạy qua dây dẫn.",
    "[Hình 14.11. Kim nam châm đặt trong từ trường của dây dẫn thẳng mang dòng điện]",
    "",
    "**EM ĐÃ HỌC**",
    "- Từ trường là trường lực gây ra bởi dòng điện hoặc nam châm, là một dạng vật chất tồn tại xung quanh dòng điện hoặc nam châm mà biểu hiện cụ thể là sự xuất hiện của lực từ tác dụng lên một dòng điện hay một nam châm khác đặt trong nó.",
    "- Đường sức từ là những đường vẽ ở trong không gian có từ trường sao cho tiếp tuyến với nó tại mỗi điểm trùng với phương của vectơ cảm ứng từ tại điểm đó. Chiều của đường sức từ là chiều của vectơ cảm ứng từ.",
    "",
    "**EM CÓ THỂ**",
    "- Giải thích được nguyên tắc hoạt động của la bàn.",
    "- Nêu được ứng dụng của nam châm trong cuộc sống như tàu đệm từ, nam châm điện.",
    "",
    "60"
  ]
}
