INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH3' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI12')), 'B15', 'Lực từ tác dụng lên dây dẫn mang dòng điện. Cảm ứng từ', 63, 2, $JSON$
{
  "content": [
    "# Bài 15 LỰC TỪ TÁC DỤNG LÊN DÀY DẪN MANG DÒNG ĐIỆN. CẢM ỨNG TỪ",
    "",
    "**Khởi động:**",
    "*Tính chất cơ bản của từ trường là gây ra lực từ tác dụng lên một nam châm hay một dòng điện đặt trong từ trường đó. Vậy lực từ có đặc điểm như thế nào?*",
    "",
    "## I. THÍ NGHIỆM VỀ LỰC TỪ TÁC DỤNG LÊN ĐOẠN DÂY DẪN MANG DÒNG ĐIỆN",
    "Để khảo sát lực từ tác dụng lên đoạn dây dẫn mang dòng điện người ta sử dụng thiết bị như Hình 15.1.",
    "",
    "**Hoạt động**",
    "**Thí nghiệm**",
    "*Chuẩn bị:* Thiết bị thí nghiệm gồm:",
    "- Hộp gỗ có gắn các thiết bị dưới đây:",
    "  + Nam châm điện có gắn hai tấm thép (1).",
    "  + Đòn cân (2) có gắn gia trọng (3) và khớp nối với khung dây dẫn (4).",
    "  + Hai ampe kế có giới hạn đo 2 A (5), (6).",
    "  + Hai biến trở xoay 100 $\\Omega$ – 2 A (7).",
    "  + Hai công tắc dùng để đảo chiều dòng điện qua nam châm điện và khung dây (8), (9).",
    "- Khung dây n = 200 vòng có chiều dài một cạnh $l$ = 10 cm (10).",
    "- Lực kế có giới hạn đo 0,5 N (11).",
    "- Đèn chỉ hướng từ trường trong lòng nam châm điện (12).",
    "- Nguồn điện một chiều, điện áp 12 V (13) và các dây nối.",
    "[Hình 15.1. Bộ thí nghiệm lực từ và cảm ứng từ]",
    "",
    "*Tiến hành:*",
    "- Nối hai cực của nguồn điện DC với hai chốt cắm trên hộp gỗ. Cắm khung dây vào khớp nối trên đòn cân, sao cho cạnh dưới của khung dây nằm trong từ trường của nam châm.",
    "- Đóng công tắc điện.",
    "*Thực hiện các yêu cầu sau:*",
    "1. Quan sát và giải thích hiện tượng xảy ra với khung dây.",
    "2. Quan sát đèn chỉ hướng từ trường trong lòng nam châm điện, các cực của nguồn điện nối với khung dây, chiều chuyển động của khung dây; từ đó xác định chiều của cảm ứng từ bên trong lòng nam châm điện, chiều dòng điện và chiều của lực từ tác dụng lên đoạn dây dẫn mang dòng điện $l$ trong từ trường.",
    "3. Dự đoán hiện tượng xảy ra nếu đổi chiều dòng điện chạy qua nam châm điện hoặc khung dây.",
    "4. Đề xuất cách xác định chiều của lực từ.",
    "",
    "Từ kết quả thí nghiệm và nhiều thí nghiệm khác cũng cho thấy:",
    "- Khi cho dòng điện có cường độ I chạy qua đoạn dây dẫn đặt trong từ trường thì xuất hiện lực từ $\\vec{F}$ tác dụng lên đoạn dây dẫn mang dòng điện.",
    "- Lực từ $\\vec{F}$ có phương vuông góc với đoạn dây dẫn mang dòng điện đặt trong từ trường và vuông góc với đường sức từ (Hình 15.2).",
    "",
    "[Hình 15.2. Phương, chiều của lực từ $\\vec{F}$ tác dụng lên đoạn dây dẫn mang dòng điện I đặt trong từ trường của nam châm chữ U]",
    "",
    "61",
    "CHƯƠNG III – TỪ TRƯỜNG",
    "",
    "Chiều của lực từ được xác định theo quy tắc bàn tay trái:",
    "*Đặt bàn tay trái sao cho vectơ cảm ứng từ $\\vec{B}$ hướng vào lòng bàn tay, chiều từ cổ tay đến các ngón tay trùng với chiều dòng điện, thì ngón tay cái choãi ra 90$^\\circ$ chỉ chiều của lực từ $\\vec{F}$ tác dụng lên dòng điện* (Hình 15.3).",
    "",
    "**Hoạt động**",
    "Sử dụng quy tắc bàn tay trái để kiểm chứng chiều của lực từ tác dụng lên thanh kim loại M$_1$M$_2$ trong Hình 15.2.",
    "[Hình 15.3. Hình vẽ mô tả quy tắc bàn tay trái]",
    "",
    "**? Câu hỏi:**",
    "Ba dây dẫn mang dòng điện đặt trong từ trường như Hình 15.4.",
    "1. Hãy xác định phương và chiều của lực từ tác dụng lên dây dẫn ở Hình 15.4a, 15.4b.",
    "2. Trong trường hợp Hình 15.4c, có lực từ tác dụng lên dây dẫn không? Dự đoán lực từ còn phụ thuộc vào yếu tố nào khác?",
    "[Hình 15.4. Dây dẫn mang dòng điện đặt trong từ trường]",
    "a)",
    "b)",
    "c)",
    "Quy ước:",
    "$\\otimes$ Chiều dòng điện hướng vuông góc từ ngoài vào trong trang giấy.",
    "$\\odot$ Chiều dòng điện hướng vuông góc từ trong ra ngoài trang giấy.",
    "",
    "## II. ĐỘ LỚN CẢM ỨNG TỪ",
    "**1. Biểu thức**",
    "Gọi góc $\\alpha$ là góc hợp bởi dòng điện I (đoạn dây dẫn L mang dòng điện đặt trong từ trường) và đường sức từ (Hình 15.5).",
    "Tiếp tục tiến hành thí nghiệm như mô tả ở mục I. Trong đó, lần lượt cho L, I và góc $\\alpha$ thay đổi, các kết quả cho thấy thương số tương ứng $\\frac{F}{L}$, $\\frac{F}{I}$ và $\\frac{F}{\\sin\\alpha}$ đều là các hằng số. Nghĩa là độ lớn của lực từ F tác dụng lên đoạn dây dẫn mang dòng điện tỉ lệ với chiều dài L của đoạn dây dẫn, tỉ lệ với cường độ dòng điện I chạy qua đoạn dây và tỉ lệ với $\\sin\\alpha$. Nói cách khác thì thương số $\\frac{F}{IL\\sin\\alpha}$ có giá trị không đổi.",
    "[Hình 15.5. Đoạn dây dẫn mang dòng điện hợp với vectơ cảm ứng từ $\\vec{B}$ một góc $\\alpha$]",
    "",
    "Do đó, với một nam châm nhất định có thể lấy thương số này làm đại lượng đặc trưng cho từ trường về phương diện tác dụng lực. Người ta gọi thương số này là độ lớn của cảm ứng từ của từ trường tại vị trí khảo sát, kí hiệu là B.",
    "$B = \\frac{F}{IL\\sin\\alpha}$ (15.1)",
