    "1. Xét một đoạn dây dẫn thẳng có chiều dài L = 1 m, có dòng điện I = 3 A chạy qua được đặt trong từ trường đều có cảm ứng từ B = 5.10$^{-2}$ T. Hãy xác định độ lớn của lực từ tác dụng lên đoạn dây dẫn mang dòng điện nếu phương của dây dẫn hợp với vectơ cảm ứng từ một góc 60$^\\circ$.",
    "2. Một dây dẫn dài 50 cm có dòng điện chạy qua được đặt vuông góc với từ trường có độ lớn cảm ứng từ là 5 mT.",
    "a) Nếu có 10$^{18}$ electron chạy qua dây dẫn trong mỗi giây thì cường độ dòng điện chạy qua dây dẫn bằng bao nhiêu? (Cho biết độ lớn điện tích electron là $|e| = 1,60.10^{-19}$ C).",
    "b) Tính độ lớn của lực từ tác dụng lên dây dẫn.",
    "",
    "## III. THỰC HÀNH ĐO ĐỘ LỚN CẢM ỨNG TỪ",
    "**1. Mục đích thí nghiệm**",
