    "  - Có độ lớn $B = \\frac{F}{IL\\sin\\alpha}$.",
    "- Cách xác định độ lớn cảm ứng từ của từ trường đều bằng thiết bị thí nghiệm.",
    "",
    "**EM CÓ THỂ**",
    "- Giải thích được nguyên tắc hoạt động của tàu đệm từ.",
