{
  "content": [
    "# Bài 16 TỪ THÔNG. HIỆN TƯỢNG CẢM ỨNG ĐIỆN TỪ",
    "",
    "**Khởi động:**",
    "*Khi số đường sức từ xuyên qua tiết diện của cuộn dây dẫn kín biến thiên thì trong cuộn dây dẫn đó xuất hiện dòng điện cảm ứng. Hãy cho biết có những cách nào làm cho số đường sức từ qua tiết diện của cuộn dây dẫn kín biến thiên?*",
    "",
    "## I. TỪ THÔNG",
    "Xét một vòng dây dẫn kín (C) có diện tích S, được đặt trong từ trường đều $\\vec{B}$. Vẽ vectơ đơn vị pháp tuyến $\\vec{n}$ của S. Chiều của $\\vec{n}$ có thể chọn tuỳ ý. Góc hợp thành bởi $\\vec{B}$ và $\\vec{n}$ kí hiệu là $\\alpha$ (Hình 16.1).",
    "Ta đặt: $\\Phi = BS\\cos\\alpha$ (16.1)",
    "Đại lượng $\\Phi$ gọi là từ thông qua diện tích S.",
    "Đơn vị của từ thông trong hệ SI là vêbe (weber), kí hiệu Wb.",
    "Ta có: 1 Wb = 1 T.1 m$^2$.",
    "[Hình 16.1. Mô tả đường sức từ xuyên qua diện tích S giới hạn bởi vòng dây dẫn kín (C)]",
    "",
    "Khi cảm ứng từ $\\vec{B}$ vuông góc với mặt phẳng vòng dây thì $\\alpha$ = 0, ta có: $\\cos\\alpha$ = 1. Nếu vòng dây có diện tích là 1 m$^2$, theo biểu thức (16.1), ta có trị số của từ thông bằng độ lớn của cảm ứng từ.",
    "Trong trường hợp này, từ thông qua một đơn vị diện tích của vòng dây trong từ trường có vectơ pháp tuyến của vòng dây đặt song song với vectơ cảm ứng từ và có độ lớn bằng độ lớn cảm ứng từ $\\vec{B}$. Do đó, từ thông có thể diễn tả số đường sức từ xuyên qua một diện tích nào đó.",
    "",
    "[Hình 16.2. Các đường sức từ xuyên qua diện tích giới hạn bởi khung dây trong trường hợp góc $\\alpha$ là góc nhọn]",
    "[Hình 16.3. Các đường sức từ xuyên qua diện tích giới hạn bởi khung dây trong trường hợp góc $\\alpha$ là góc tù]",
    "",
    "**? Câu hỏi:**",
    "Từ biểu thức (16.1) hãy cho biết trong trường hợp nào thì từ thông qua vòng dây diện tích S giới hạn bởi dẫn kín (C) có trị số bằng 0, có trị số dương, trị số âm.",
    "",
    "66",
    "CHƯƠNG III – TỪ TRƯỜNG",
    "",
    "Để làm từ thông biến thiên, có thể biến đổi từng đại lượng B, S, $\\alpha$ trong biểu thức (16.1). Hãy đề xuất các cách có thể làm biến thiên từ thông qua tiết diện khung dây dẫn mềm nối với điện kế thành mạch kín trong các trường hợp sau:",
    "Trường hợp 1: Khung dây dẫn đặt cạnh nam châm vĩnh cửu (Hình 16.4).",
