    "",
    "[Hình 16.7. Thí nghiệm với nam châm điện và cuộn dây dẫn]",
    "",
    "*Từ kết quả thí nghiệm quan sát được, thực hiện các yêu cầu sau:*",
    "1. Khi đóng, ngắt khoá K hoặc di chuyển con chạy trên biến trở thì kim điện kế có lệch khỏi vạch 0 không? Giải thích.",
    "2. Khi đóng hoặc ngắt khoá K, đại lượng nào trong công thức (16.1) thay đổi làm xuất hiện dòng điện cảm ứng trong cuộn dây dẫn kín?",
    "",
    "Dựa vào công thức từ thông (16.1), ta thấy rằng khi một trong các đại lượng B, S hoặc $\\alpha$ thay đổi thì từ thông $\\Phi$ biến thiên.",
    "Các thí nghiệm trên và nhiều thí nghiệm tương tự khác chứng tỏ rằng:",
    "*Khi từ thông qua cuộn dây dẫn kín biến thiên thì trong cuộn dây dẫn đó xuất hiện một dòng điện gọi là dòng điện cảm ứng. Hiện tượng xuất hiện dòng điện cảm ứng trong cuộn dây dẫn gọi là hiện tượng cảm ứng điện từ.*",
