    "",
    "## III. CHIỀU DÒNG ĐIỆN CẢM ỨNG. ĐỊNH LUẬT LENZ",
    "Để xác định chiều dòng điện cảm ứng trong thí nghiệm 1 (Hình 16.6), ta có thể sử dụng sơ đồ thí nghiệm tương tự như trên Hình 16.8.",
