    "CHƯƠNG III – TỪ TRƯỜNG",
    "",
    "[Hình 16.8. Thí nghiệm về chiều dòng điện cảm ứng. $\\vec{B_c}$ là kí hiệu cảm ứng từ của từ trường do dòng điện cảm ứng $i_c$ trong cuộn dây sinh ra; $\\vec{B_0}$ là cảm ứng từ của từ trường nam châm]",
    "a) Dịch chuyển cực Bắc của nam châm lại gần cuộn dây",
    "b) Dịch chuyển cực Bắc của nam châm ra xa cuộn dây",
    "",
    "Từ thí nghiệm, ta có nhận xét rằng khi nam châm lại gần cuộn dây ($\\vec{B_c}$ và $\\vec{B_0}$ ngược chiều – Hình 16.8a) thì từ trường của dòng điện cảm ứng trong cuộn dây có xu hướng ngăn cản nam châm lại gần nó; còn khi nam châm ra xa cuộn dây ($\\vec{B_c}$ và $\\vec{B_0}$ cùng chiều – Hình 16.8b) thì từ trường của dòng điện cảm ứng lại có xu hướng ngăn cản nam châm ra xa nó.",
    "Nhận xét trên về chiều của dòng điện cảm ứng có thể phát biểu khái quát: *Dòng điện cảm ứng xuất hiện trong mạch kín có chiều sao cho từ trường do nó sinh ra có tác dụng chống lại sự biến thiên của từ thông qua mạch kín đó.* Phát biểu này là nội dung định luật Lenz về chiều dòng điện cảm ứng.",
    "",
    "**Hoạt động**",
    "Hãy xác định chiều quấn của cuộn dây (2) trong thí nghiệm 2 (Hình 16.7) và vận dụng định luật Lenz để kiểm chứng chiều dòng điện cảm ứng trong cuộn dây này khi đóng hoặc ngắt khoá K (4).",
    "",
    "## IV. SUẤT ĐIỆN ĐỘNG CẢM ỨNG. ĐỊNH LUẬT FARADAY",
    "Nếu một mạch điện kín có dòng điện thì trong mạch tồn tại suất điện động. Do đó, ta gọi suất điện động sinh ra dòng điện cảm ứng trong mạch kín như trong cuộn dây dẫn (thí nghiệm 1 và thí nghiệm 2) là suất điện động cảm ứng, kí hiệu $e_c$. Ở các thí nghiệm đó, khi có sự biến thiên của từ thông qua cuộn dây dẫn kín thì trong mạch xuất hiện suất điện động cảm ứng.",
    "*Thực nghiệm chứng tỏ rằng: Độ lớn của suất điện động cảm ứng trong mạch kín tỉ lệ với tốc độ biến thiên của từ thông qua mạch.* Phát biểu này được gọi là định luật Faraday về cảm ứng điện từ.",
    "Nếu trong khoảng thời gian $\\Delta t$ đủ nhỏ, từ thông qua mạch kín biến thiên một lượng $\\Delta\\Phi$ thì $|\\frac{\\Delta\\Phi}{\\Delta t}|$ là tốc độ biến thiên của từ thông. Vì vậy, định luật Faraday có thể viết:",
    "$|e_c| = k|\\frac{\\Delta\\Phi}{\\Delta t}|$",
    "",
    "69",
    "CHƯƠNG III – TỪ TRƯỜNG",
    "",
    "Trong hệ SI, hệ số tỉ lệ k = 1. Nếu kế đến định luật Lenz thì công thức xác định suất điện động cảm ứng được viết dưới dạng:",
    "$e_c = - \\frac{\\Delta\\Phi}{\\Delta t}$",
    "Trong trường hợp mạch điện là một cuộn dây có N vòng dây thì:",
    "$e_c = -N \\frac{\\Delta\\Phi}{\\Delta t}$",
    "Trong đó $\\Phi$ là từ thông qua diện tích giới hạn bởi một vòng dây.",
    "",
    "**Hoạt động**",
    "Thí nghiệm với thanh kim loại MN trượt trên hai đoạn dây dẫn điện MQ và NP được nối với ampe kế thành mạch điện kín như Hình 16.9. Mạch điện được đặt trong từ trường đều có cảm ứng từ $\\vec{B}$ vuông góc với mặt phẳng MNPQ. Xác định chiều dòng điện cảm ứng và biểu thức suất điện động cảm ứng trong mạch khi thanh kim loại trượt đều với tốc độ v trên hai đoạn dây dẫn.",
    "[Hình 16.9. Mô tả thí nghiệm thanh kim loại trượt trên hai đoạn dây dẫn]",
    "",
    "**EM ĐÃ HỌC**",
    "- Từ thông qua diện tích S đặt trong từ trường đều $\\vec{B}$ dùng để diễn tả số đường sức từ xuyên qua diện tích S đó: $\\Phi = BS\\cos\\alpha$. Từ thông có đơn vị weber (kí hiệu Wb).",
    "- Hiện tượng cảm ứng điện từ chỉ tồn tại trong khoảng thời gian từ thông qua cuộn dây dẫn kín biến thiên.",
    "- Định luật Lenz về chiều dòng điện cảm ứng.",
    "- Định luật Faraday về độ lớn của suất điện động cảm ứng trong mạch kín.",
    "Biểu thức suất điện động cảm ứng:",
    "$e_c = -N \\frac{\\Delta\\Phi}{\\Delta t}$",
    "Trong đó, N là số vòng dây và $|\\frac{\\Delta\\Phi}{\\Delta t}|$ là tốc độ biến thiên của từ thông qua mạch kín.",
    "",
    "**EM CÓ THỂ**",
    "- Nêu được nguyên tắc hoạt động của máy phát điện.",
    "",
    "70",
    "CHƯƠNG III – TỪ TRƯỜNG",
    "",
    "**EM CÓ BIẾT**",
    "Cho nam châm thẳng rơi qua cuộn dây dẫn kín. Cuộn dây này được nối với cảm biến điện thế (Hình 16.10) thì ta sẽ thu được suất điện động của cuộn dây như mô tả trong Hình 16.11 và 16.12. Thí nghiệm này chứng tỏ trọng lực sinh công làm biến thiên từ thông qua cuộn dây để sinh ra suất điện động cảm ứng, nghĩa là cơ năng đã chuyển hoá thành điện năng. Do đó, bản chất của hiện tượng cảm ứng điện từ là quá trình chuyển hoá cơ năng thành điện năng. Nhà bác học Faraday (Fa-ra-đây) là người đầu tiên khám phá ra hiện tượng này làm cơ sở để tạo ra phương thức sản xuất điện năng mới cho cuộc cách mạng khoa học lần thứ hai trong lịch sử.",
    "",
    "[Hình 16.10. Bố trí thí nghiệm gồm nam châm, cuộn dây nối với cảm biến điện thế]",
    "[Hình 16.11. Đồ thị suất điện động của cuộn dây khi thả cực Bắc của nam châm rơi xuống trước]",
    "[Hình 16.12. Đồ thị suất điện động của cuộn dây khi thả cực Nam của nam châm rơi xuống trước]",
    "",
    "71"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH3' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI12')), 'B17', 'Máy phát điện xoay chiều', 74, 4, $JSON$
{
  "content": [
    "# Bài 17 MÁY PHÁT ĐIỆN XOAY CHIỀU",
    "",
    "**Khởi động:**",
    "*Dòng điện xoay chiều được sử dụng rất phổ biến trong đời sống. Dòng điện xoay chiều được tạo ra bằng cách nào?*",
    "",
    "## I. NGUYÊN TẮC TẠO RA DÒNG ĐIỆN XOAY CHIỀU",
    "Xét một khung dây dẫn MNPQ có diện tích S, quay đều với tốc độ góc $\\omega$ quanh một trục OO’ vuông góc với các đường sức của một từ trường đều có cảm ứng từ $\\vec{B}$ (Hình 17.1).",
    "Theo hiện tượng cảm ứng điện từ đã học ở Bài 16, trong khung dây xuất hiện một suất điện động biến đổi theo thời gian:",
    "$e = E_0\\cos(\\omega t + \\varphi_0)$ (17.1)",
    "Trong đó, $E_0 = BS\\omega$ là suất điện động cực đại trong khung dây; $\\varphi_0$ là pha ban đầu của suất điện động.",
    "Nếu khung dây dẫn MNPQ có N vòng dây thì suất điện động cực đại của khung dây là $E_0 = NBS\\omega$.",
    "",
    "[Hình 17.1. Khung dây dẫn MNPQ có trục quay OO’ đặt vuông góc với cảm ứng từ $\\vec{B}$]",
    "",
    "Suất điện động biến đổi theo thời gian theo định luật dạng cosin (hoặc sin) trong biểu thức (17.1) được gọi là suất điện động xoay chiều. Chu kì T và tần số f của suất điện động liên hệ với tần số góc $\\omega$ bởi các công thức:",
    "$T = \\frac{2\\pi}{\\omega} \\text{ (s)}, f = \\frac{\\omega}{2\\pi} \\text{ (Hz)}$",
    "Khi nối hai đầu khung dây dẫn trên với điện trở thuần R tạo thành mạch kín, thì dòng điện trong khung dây dẫn biến thiên theo thời gian với tần số bằng tần số của suất điện động xoay chiều. Dòng điện này gọi là dòng điện xoay chiều.",
    "Do đó, nguyên tắc tạo ra dòng điện xoay chiều dựa trên hiện tượng cảm ứng điện từ là làm cho từ thông qua khung dây dẫn biến thiên điều hoà theo thời gian.",
    "",
    "**? Câu hỏi:**",
    "1. Khung dây dẫn trong Hình 17.2 ở vị trí nào thì suất điện động có giá trị cực đại? Giải thích.",
    "2. Giả sử tại thời điểm t, từ thông qua khung dây dẫn phẳng MNPQ là:",
    "$\\Phi = BS\\cos\\alpha = BS\\cos\\omega t$",
    "Hãy chứng tỏ, suất điện động cảm ứng xuất hiện trong khung dây này có dạng:",
    "$e = BS\\omega\\cos(\\omega t + \\varphi_0)$ (V)",
    "",
    "72",
    "CHƯƠNG III – TỪ TRƯỜNG",
    "",
    "[Hình 17.2. Mô tả suất điện động xoay chiều khi khung dây MNPQ quay trong từ trường $\\vec{B}$]",
    "",
    "**Hoạt động**",
    "Dựa trên nguyên tắc tạo ra dòng điện xoay chiều, hãy thực hiện các nhiệm vụ sau:",
    "1. Làm thế nào để dẫn dòng điện ra mạch ngoài khi khung dây dẫn quay đều trong từ trường (Hình 17.2)?",
    "2. Thảo luận về:",
    "- nguyên tắc tạo ra suất điện động xoay chiều.",
    "- các yếu tố cần để tạo ra dòng điện xoay chiều.",
    "- thiết kế phương án tạo ra dòng điện xoay chiều.",
    "",
    "## II. DÒNG ĐIỆN XOAY CHIỀU",
    "**1. Biểu thức dòng điện xoay chiều**",
    "Nếu nối hai đầu của khung dây dẫn MNPQ (Hình 17.1) với đoạn mạch tiêu thụ điện thì giữa hai đầu đoạn mạch có một hiệu điện thế. Hiệu điện thế này biến thiên theo thời gian theo quy luật dạng cosin (hoặc sin) gọi là hiệu điện thế xoay chiều hay điện áp xoay chiều. Điện áp xoay chiều có cùng chu kì, tần số với suất điện động xoay chiều và có dạng:",
    "$u = U_0\\cos(\\omega t + \\varphi_u) \\text{ (V)}$ (17.2)",
    "Khi đó, dòng điện chạy qua mạch điện tiêu thụ là dòng điện xoay chiều có dạng:",
    "$i = I_0\\cos(\\omega t + \\varphi_i) \\text{ (A)}$ (17.3)",
    "Trong các biểu thức (17.2), (17.3):",
    "- u và i tương ứng là giá trị điện áp tức thời và cường độ dòng điện tức thời tại thời điểm t;",
    "- $U_0$ và $I_0$ tương ứng là giá trị cực đại của điện áp và cường độ dòng điện xoay chiều;",
    "- $\\omega$ là tần số góc của dòng điện xoay chiều, có đơn vị là rad/s;",
    "- $\\varphi_u$, $\\varphi_i$ lần lượt là pha ban đầu của điện áp và cường độ dòng điện xoay chiều.",
    "",
    "73",
    "CHƯƠNG III – TỪ TRƯỜNG",
    "",
    "Các đại lượng $(\\omega t + \\varphi_u)$ và $(\\omega t + \\varphi_i)$ là pha của điện áp và cường độ dòng điện xoay chiều; $\\Delta\\varphi = \\varphi_u - \\varphi_i$ gọi là độ lệch pha giữa điện áp và cường độ dòng điện xoay chiều.",
    "*Dòng điện có cường độ biến thiên điều hoà với thời gian theo quy luật của hàm cosin (hoặc sin) như biểu thức (17.3), gọi là dòng điện xoay chiều.*",
    "",
    "**2. Giá trị hiệu dụng**",
    "Dòng điện xoay chiều cũng có tác dụng nhiệt như dòng điện không đổi.",
    "Cho dòng điện xoay chiều có cường độ $i = I_0\\cos(\\omega t + \\varphi_i)$ (A) chạy qua đoạn mạch chỉ có điện trở R, nhiệt lượng toả ra trong thời gian t (đủ lớn so với chu kì T của dòng điện) là Q.",
    "Cho dòng điện không đổi có cường độ I chạy qua điện trở nói trên trong cùng khoảng thời gian t sao cho nhiệt lượng toả ra cũng bằng Q.",
    "Người ta đã thiết lập được mối liên hệ giữa giá trị I và giá trị cực đại $I_0$ của cường độ dòng điện xoay chiều:",
    "$I = \\frac{I_0}{\\sqrt{2}}$ (17.4)",
    "Đại lượng I gọi là giá trị hiệu dụng của cường độ dòng điện xoay chiều hay cường độ hiệu dụng của dòng điện xoay chiều.",
    "Người ta cũng xác định được mối liên hệ giữa giá trị hiệu dụng U và giá trị cực đại U$_0$ của điện áp xoay chiều:",
    "$U = \\frac{U_0}{\\sqrt{2}}$ (17.5)",
    "",
    "**Hoạt động**",
    "Dựa vào đồ thị biểu diễn cường độ dòng điện xoay chiều theo thời gian như Hình 17.3, hãy thực hiện các yêu cầu sau:",
    "- Xác định chu kì T (s) và tần số f (Hz) của dòng điện xoay chiều.",
    "- Xác định giá trị cực đại, giá trị hiệu dụng và pha ban đầu của cường độ dòng điện xoay chiều.",
    "- Viết biểu thức cường độ dòng điện theo thời gian.",
    "[Hình 17.3. Đồ thị biểu diễn cường độ dòng điện xoay chiều theo thời gian]",
    "",
    "## III. MÁY PHÁT ĐIỆN XOAY CHIỀU",
    "**1. Cấu tạo**",
    "Máy phát điện xoay chiều hoạt động dựa trên hiện tượng cảm ứng điện từ, có hai bộ phận chính là phần cảm và phần ứng. Một trong hai bộ phận chính được đặt cố định, gọi là stato, phần còn lại quay quanh một trục, gọi là rôto.",
    "- Phần cảm là nam châm điện hoặc nam châm vĩnh cửu dùng để tạo ra từ trường.",
    "- Phần ứng là các cuộn dây dẫn, trong đó xuất hiện suất điện động cảm ứng khi máy hoạt động.",
    "",
    "74",
    "CHƯƠNG III – TỪ TRƯỜNG",
    "",
    "**2. Nguyên tắc hoạt động**",
    "Các máy phát điện xoay chiều hoạt động theo cách thứ nhất có stato là nam châm đặt cố định, rôto là khung dây quay quanh một trục trong từ trường tạo bởi stato (Hình 17.4). Để dẫn điện ra ngoài thì cần có hai vành khuyên, trong đó mỗi vành khuyên được gắn chặt vào một đầu của khung dây. Cả hai vành khuyên này được đặt đồng trục với trục quay của khung dây và cùng quay với khung dây.",
    "Khi máy hoạt động, mỗi vành khuyên có một chổi quét tì vào nên khi khung dây quay, hai vành khuyên trượt trên hai chổi quét, dòng điện truyền từ khung dây qua hai chổi quét ra mạch ngoài.",
    "Các máy phát điện xoay chiều hoạt động theo cách thứ hai có rôto là nam châm, thường là nam châm điện được nuôi bởi dòng điện một chiều (các cuộn dây của rôto cũng có lõi sắt và xếp thành vòng tròn, Hình 17.5a) và stato gồm nhiều cuộn dây có lõi sắt, xếp thành một vòng tròn (Hình 17.5b) thì không cần vành khuyên và chổi quét, mà dòng điện được dẫn trực tiếp ra mạch ngoài bởi các cuộn dây đặt cố định.",
    "",
    "[Hình 17.4. Mô tả nguyên tắc hoạt động của máy phát điện xoay chiều theo cách thứ nhất]",
    "[Hình 17.5. Rôto (a) và stato (b) của máy phát điện xoay chiều]",
    "",
    "**Hoạt động**",
    "1. Hãy viết biểu thức suất điện động của máy phát điện xoay chiều trong trường hợp khung dây có N vòng dây, quay với tốc độ góc $\\omega$ trong từ trường đều có cảm ứng từ $\\vec{B}$ ($\\vec{B}$ vuông góc với trục quay của khung).",
    "2. Vì sao cần sử dụng vành khuyên và chổi quét để dẫn điện ra mạch ngoài đối với các máy phát điện xoay chiều hoạt động theo cách thứ nhất?",
    "",
    "**EM CÓ BIẾT**",
    "[Hình 17.6. Các bộ phận của máy phát điện xoay chiều có phần ứng là stato]",
    "Khi khung dây quay với tốc độ cao thì vành khuyên, chổi quét sẽ nhanh mòn. Do đó, người ta chế tạo máy phát điện xoay chiều có stato là phần ứng gồm nhiều cuộn dây như Hình 17.6.",
    "",
    "75",
    "CHƯƠNG III – TỪ TRƯỜNG",
    "",
    "## IV. ỨNG DỤNG VÀ QUY TẮC AN TOÀN KHI SỬ DỤNG DÒNG ĐIỆN XOAY CHIỀU",
    "**1. Ứng dụng của dòng điện xoay chiều trong cuộc sống**",
    "Dòng điện xoay chiều có ưu thế trong việc truyền tải điện năng đi xa, dẫn điện đến các nhà máy, xí nghiệp sản xuất, nơi tiêu thụ có sử dụng dòng điện xoay chiều.",
    "Dòng điện xoay chiều được sử dụng rộng rãi trong cuộc sống là nhờ vào các tác dụng nhiệt, tác dụng từ, tác dụng phát sáng và tác dụng sinh lí của nó.",
    "Các thiết bị như quạt điện, động cơ điện, đèn điện,... đã chuyển hoá năng lượng điện thành các dạng năng lượng khác nhằm đáp ứng các nhu cầu sống, sinh hoạt, lao động, sản xuất,... của con người.",
    "Trong y học, dòng điện xoay chiều được sử dụng để vận hành các thiết bị y tế bao gồm: máy chẩn đoán hình ảnh (như máy chụp cộng hưởng từ, máy siêu âm, máy chụp X – quang) hoặc các máy hỗ trợ điều trị bệnh nhân (như máy sốc điện, máy điện tim),...",
    "",
    "**Hoạt động**",
    "Thảo luận để thực hiện các yêu cầu sau:",
    "1. Ngoài thắp sáng, chạy máy thì dòng điện xoay chiều còn được sử dụng vào những việc gì?",
    "2. Tìm hiểu thông qua sách báo, internet về các biện pháp giảm hao phí trong truyền tải điện năng đi xa bằng dòng điện xoay chiều.",
    "",
    "**2. Quy tắc an toàn khi sử dụng dòng điện xoay chiều**",
    "Để cảnh báo về an toàn điện, người ta đã đưa ra các biển báo an toàn điện.",
    "Một số quy tắc an toàn khi sử dụng dòng điện xoay chiều:",
    "- Tuân thủ theo các biển báo an toàn điện.",
    "- Tuyệt đối không chạm tay vào chỗ hở của đường dây điện hay cắm vật trực tiếp bằng kim loại cắm vào ổ điện.",
    "- Tránh lại gần những khu vực có điện thế nguy hiểm.",
    "- Kiểm tra, bảo trì các thiết bị điện định kì theo đúng hướng dẫn.",
    "- Ngắt nguồn điện khi có thiên tai, sấm sét.",
    "[Hình 17.7. Biển cảnh báo an toàn điện]",
    "",
    "**Hoạt động**",
    "Thảo luận để thực hiện các yêu cầu sau:",
    "1. Nhận biết được ý nghĩa của những biển báo an toàn điện.",
    "2. Vì sao không nên sử dụng thiết bị điện trong quá trình sạc pin?",
    "3. Vì sao cần lựa chọn và lắp đặt thiết bị đóng, ngắt điện ở vị trí phù hợp, dễ tiếp cận nhất tại gia đình?",
    "4. Vì sao cần lựa chọn thiết bị điện có chất lượng, có công suất phù hợp với mạng lưới điện?",
    "5. Nêu tầm quan trọng của việc tuân thủ quy tắc an toàn khi sử dụng dòng điện xoay chiều trong cuộc sống.",
    "",
    "76",
    "CHƯƠNG III – TỪ TRƯỜNG",
    "",
    "**EM ĐÃ HỌC**",
    "- Dòng điện xoay chiều là dòng điện có cường độ biến thiên điều hoà với thời gian theo quy luật hàm số sin hoặc cosin.",
    "$i = I_0\\cos(\\omega t + \\varphi_i)$",
    "- Mối liên hệ giữa giá trị hiệu dụng và giá trị cực đại của dòng điện và điện áp xoay chiều lần lượt là: $I = \\frac{I_0}{\\sqrt{2}}$ và $U = \\frac{U_0}{\\sqrt{2}}$.",
    "- Dòng điện xoay chiều có ưu thế trong việc truyền tải điện năng đi xa nên được sử dụng phổ biến.",
    "- Máy phát điện xoay chiều hoạt động dựa trên hiện tượng cảm ứng điện từ, chuyển hoá cơ năng thành điện năng. Máy phát điện xoay chiều có cấu tạo gồm hai bộ phận chính là phần cảm và phần ứng. Phần cảm là bộ phận tạo ra từ trường và phần ứng là những cuộn dây xuất hiện suất điện động cảm ứng khi máy hoạt động.",
    "- Cần tuân thủ các quy tắc an toàn khi sử dụng dòng điện xoay chiều.",
    "",
    "**EM CÓ THỂ**",
    "- Nêu được ý nghĩa của các thông số ghi trên các thiết bị điện.",
    "- Giải thích được cách tạo ra dòng điện xoay chiều trong nhà máy thuỷ điện.",
    "- Đề xuất được một số biện pháp sử dụng điện an toàn trong gia đình.",
    "",
    "**EM CÓ BIẾT**",
    "Máy phát điện xoay chiều ba pha thường được sử dụng trong thực tế có sơ đồ cấu tạo đơn giản như Hình 17.8.",
    "Trong đó rôto là nam châm điện quay quanh trục (phần cảm) còn stato là ba cuộn dây riêng rẽ, đặt trên vòng tròn và lệch nhau 120$^\\circ$ (phần ứng).",
    "Suất điện động trong ba cuộn dây khi máy hoạt động tạo ra có đặc điểm là lệch pha nhau $\\frac{2\\pi}{3}$.",
    "Nếu suất điện động xoay chiều trong cuộn dây A$_1$B$_1$ là $e_1 = E_0\\cos\\omega t$ (V) thì suất điện động trong các cuộn dây A$_2$B$_2$ và A$_3$B$_3$ tương ứng là:",
    "$e_2 = E_0\\cos(\\omega t + \\frac{2\\pi}{3}) \\text{ (V)}$",
    "$e_3 = E_0\\cos(\\omega t - \\frac{2\\pi}{3}) \\text{ (V)}$",
    "[Hình 17.8. Sơ đồ nguyên tắc cấu tạo của một máy phát điện xoay chiều ba pha]",
    "",
    "77"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH3' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI12')), 'B18', 'Ứng dụng hiện tượng cảm ứng điện từ', 80, 5, $JSON$
{
  "content": [
    "# Bài 18 ỨNG DỤNG HIỆN TƯỢNG CẢM ỨNG ĐIỆN TỪ",
    "",
    "**Khởi động:**",
    "*Sạc điện không dây ngày càng được sử dụng rộng rãi để sạc điện thoại, đồng hồ thông minh, máy hút bụi,... Sạc điện hoạt động dựa trên hiện tượng nào để truyền điện từ nguồn điện đến điện thoại?*",
    "[Hình: Sạc điện thoại không dây]",
    "",
    "## I. MÁY BIẾN ÁP",
    "Máy biến áp gồm hai cuộn dây có số vòng khác nhau quấn trên một lõi kín (lõi biến áp – Hình 18.1). Lõi thường làm bằng các lá sắt hoặc thép pha silicon, ghép cách điện với nhau để giảm hao phí điện năng do dòng điện Foucault (Phu-cô). Các cuộn dây gồm nhiều vòng thường làm bằng đồng, có phủ lớp cách điện. Một trong hai cuộn dây của máy biến áp được nối với nguồn điện xoay chiều, được gọi là cuộn sơ cấp.",
    "Điện áp xoay chiều u$_1$ giữa hai đầu cuộn sơ cấp có giá trị thay đổi theo thời gian. Cuộn thứ hai được nối với tải tiêu thụ điện năng, được gọi là cuộn thứ cấp.",
    "[Hình 18.1. Cấu tạo đơn giản của máy biến áp]",
    "",
    "Hoạt động của máy biến áp dựa trên hiện tượng cảm ứng điện từ. Dòng điện xoay chiều chạy trong cuộn sơ cấp gây ra từ thông biến thiên qua cuộn thứ cấp, làm xuất hiện trong cuộn thứ cấp một suất điện động xoay chiều thay đổi theo thời gian. Khi đó, nếu đo điện áp xoay chiều u$_2$ ở hai đầu cuộn thứ cấp thì thu được giá trị của nó thay đổi theo thời gian tương ứng. Nếu mạch thứ cấp kín thì có dòng điện chạy trong cuộn thứ cấp.",
    "Do cấu tạo của máy biến áp, hầu như mọi đường sức từ chỉ chạy trong lõi biến áp nên từ thông qua mỗi vòng dây ở cả hai cuộn bằng nhau, suất điện động cảm ứng trong mỗi vòng dây cũng bằng nhau.",
    "",
    "**Hoạt động**",
    "1. Dựa vào biểu thức suất điện động cảm ứng của định luật Faraday:",
    "$e_c = -N\\frac{\\Delta\\Phi}{\\Delta t}$",
    "Hãy chứng tỏ mối liên hệ sau:",
    "$\\frac{U_1}{U_2} = \\frac{N_1}{N_2}$",
    "trong đó, U$_1$ và U$_2$ lần lượt là điện áp hiệu dụng giữa hai đầu cuộn dây sơ cấp và cuộn dây thứ cấp; với N$_1$ và N$_2$ lần lượt là số vòng dây của cuộn sơ cấp và thứ cấp.",
    "2. Giải thích nguyên nhân xuất hiện điện áp u$_2$ ở hai đầu cuộn thứ cấp.",
    "",
    "78",
    "CHƯƠNG III – TỪ TRƯỜNG",
    "",
    "**EM CÓ BIẾT**",
    "Sạc điện thoại không dây hoạt động dựa trên hiện tượng cảm ứng điện từ như máy biến áp. Ở trên sạc có cuộn dây được nối với dòng điện xoay chiều, đóng vai trò như cuộn sơ cấp (Hình 18.2). Phía sau của điện thoại có cuộn dây được nối với pin, đóng vai trò như cuộn thứ cấp. Khi đặt mặt sau của điện thoại lên mặt trên của sạc thì hai cuộn dây này được đặt cạnh nhau (Hình 18.3). Dòng điện xoay chiều qua cuộn dây của sạc biến thiên sẽ sinh ra suất điện động cảm ứng trong cuộn dây để sạc pin điện thoại.",
    "",
    "[Hình 18.2. Hình ảnh cuộn dây trong sạc điện không dây]",
    "[Hình 18.3. Mô tả các cuộn dây trong sạc và điện thoại]",
    "- Điện thoại",
    "- Pin điện thoại",
    "- Cuộn dây dẫn được nối với pin điện thoại",
    "- Mặt trên của sạc không dây",
    "- Cuộn dây dẫn trong sạc không dây",
    "",
    "## II. ĐÀN GHI TA ĐIỆN",
    "Đàn ghi ta điện có cấu tạo đặc, không có hộp cộng hưởng (Hình 18.4a). Sở dĩ ta nghe được âm phát ra từ dây đàn là nhờ sáu cuộn dây cảm ứng gắn vào đàn ở bên dưới sáu dây đàn này.",
    "Vì dây đàn bằng thép nên đoạn dây đàn nằm sát ngay bên trên nam châm của cuộn dây cảm ứng được từ hoá, nghĩa là nó trở thành một nam châm có cực từ được mô tả như Hình 18.4b.",
    "",
    "[Hình 18.4. a) Đàn ghi ta điện, b) Dây đàn và cuộn dây cảm ứng trong đàn ghi ta điện. Mỗi cuộn dây cảm ứng gồm một nam châm vĩnh cửu nhỏ (1) đặt bên trong một cuộn dây (2) đặt ngay dưới dây đàn (3). Cuộn dây (2) được nối với máy tăng âm]",
    "- 3 (Dây đàn)",
    "- Nối với máy tăng âm (2 - cuộn dây)",
    "- 1 (nam châm)",
    "",
    "**? Câu hỏi:**",
    "Trong Hình 18.4, khi gảy dây đàn (3) thì nó dao động. Khi đó, từ trường của đoạn dây đàn (3) gây ra sự biến thiên từ thông qua cuộn dây cảm ứng (2) như thế nào?",
    "",
    "79",
    "CHƯƠNG III – TỪ TRƯỜNG",
    "",
    "Khi từ thông qua cuộn dây (2) thay đổi thì trong cuộn dây xuất hiện dòng điện cảm ứng, biến đổi cả về chiều và cường độ phù hợp với dao động của dây đàn, nghĩa là cùng tần số với dao động của âm. Dòng điện cảm ứng được đưa đến máy tăng âm rồi đến loa làm ta nghe được âm do dây đàn phát ra.",
    "",
    "**Hoạt động**",
    "1. Tại sao dây đàn ghi ta điện cần làm bằng thép?",
    "2. Vì sao đàn ghi ta điện có cấu tạo đặc và không có hộp cộng hưởng mà ta vẫn nghe được âm thanh phát ra từ dây đàn?",
    "3. Vận dụng biểu thức về suất điện động cảm ứng:",
    "$e_c = -N\\frac{\\Delta\\Phi}{\\Delta t}$",
    "hãy giải thích vì sao khi gảy dây đàn mạnh hoặc nhẹ thì độ to của âm thay đổi tương ứng.",
    "",
    "**? Câu hỏi:**",
    "Nêu một số ứng dụng đơn giản khác của hiện tượng cảm ứng điện từ trong cuộc sống.",
    "",
    "**EM ĐÃ HỌC**",
    "- Nguyên tắc hoạt động của máy biến áp, đàn ghi ta điện dựa trên hiện tượng cảm ứng điện từ, định luật Lenz, định luật Faraday.",
    "",
    "**EM CÓ THỂ**",
    "- Vận dụng định luật Faraday và định luật Lenz để giải thích được một số ứng dụng của hiện tượng cảm ứng điện từ trong cuộc sống như phanh điện từ, bếp từ, sạc điện thoại không dây,...",
    "",
    "**EM CÓ BIẾT**",
    "**Dòng điện Foucault**",
    "Trong thí nghiệm về dòng điện Foucault (Hình 18.5a), khi tấm kim loại K dao động, nó cắt các đường sức từ của nam châm. Do đó trong tấm kim loại sinh ra dòng điện cảm ứng. Tấm kim loại dừng lại nhanh, vì dòng điện cảm ứng trong tấm kim loại có tác dụng ngăn cản sự chuyển động của chính tấm kim loại đó.",
    "Nếu một khối vật dẫn đặt trong từ trường biến đổi theo thời gian, thì trong khối vật dẫn đó cũng sinh ra dòng điện cảm ứng. Dòng điện cảm ứng được sinh ra ở trong khối vật dẫn khi vật dẫn chuyển động trong từ trường hay được đặt trong từ trường biến thiên theo thời gian gọi là dòng điện Foucault.",
    "",
    "80",
    "CHƯƠNG III – TỪ TRƯỜNG",
    "",
    "[Hình 18.5. Thí nghiệm về dòng điện Foucault]",
    "a) K là tấm kim loại (đồng hay nhôm) liền khối được treo vào thanh T. Cho K dao động trong từ trường giữa hai cực của nam châm thì nó sẽ dừng lại khá nhanh",
    "b) Thay tấm kim loại K bằng tấm kim loại có rãnh xẻ dao động giữa hai cực của nam châm, nó sẽ dao động được lâu hơn",
    "",
    "Đặc tính chung của các dòng điện Foucault là tính chất xoáy. Nói cách khác, các dòng điện Foucault là các đường cong kín trong khối vật dẫn. Điều này giải thích vì sao nếu thay tấm kim loại liền khối trong thí nghiệm Hình 18.5a bằng tấm kim loại có rãnh xẻ như Hình 18.5b, thì thấy tấm kim loại này dao động lâu hơn, vì khi đó điện trở của tấm kim loại đối với dòng điện Foucault tăng, làm cho cường độ dòng điện Foucault giảm.",
    "Dòng điện Foucault có nhiều ứng dụng trong thực tế như trong luyện kim, làm đệm từ trường, chế tạo bếp từ, đồng hồ đo điện, phanh điện từ,...",
    "Dòng điện Foucault cũng có tác hại đối với thiết bị điện. Ví dụ như trong máy biến áp, do tác dụng toả nhiệt của dòng điện Foucault làm lõi biến áp nóng lên gây hao phí điện năng. Để giảm tác hại của dòng điện Foucault, trong máy biến áp, người ta không dùng lõi biến áp liền khối, mà dùng những lá thép pha silicon mỏng có phủ lớp sơn cách điện ghép sát với nhau và đặt song song với đường sức từ. Làm như vậy điện trở của lõi biến áp đối với dòng Foucault sẽ tăng lên, làm giảm tác dụng toả nhiệt của nó.",
    "",
    "81"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH3' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI12')), 'B19', 'Điện từ trường. Mô hình sóng điện từ', 84, 6, $JSON$
{
  "content": [
    "# Bài 19 ĐIỆN TỪ TRƯỜNG. MÔ HÌNH SÓNG ĐIỆN TỪ",
    "",
    "**Khởi động:**",
    "*Thang sóng điện từ bao gồm rất nhiều vùng như hồng ngoại, tử ngoại, ánh sáng nhìn thấy,... Sóng điện từ được tạo thành và lan truyền như thế nào?*",
    "",
    "## I. LIÊN HỆ GIỮA ĐIỆN TRƯỜNG BIẾN THIÊN VÀ TỪ TRƯỜNG BIẾN THIÊN",
    "**1. Từ trường biến thiên và điện trường xoáy**",
    "Trong thí nghiệm về hiện tượng cảm ứng điện từ, khi cho nam châm rơi qua ống dây, từ thông qua ống dây kín biến thiên thì trong ống dây xuất hiện dòng điện cảm ứng (Hình 19.1). Sự xuất hiện của dòng điện cảm ứng chứng tỏ trong dây dẫn đã xuất hiện một điện trường, có chiều là chiều của dòng điện cảm ứng; đường sức của điện trường mới này là các đường cong kín. Điện trường có tính chất này là điện trường xoáy.",
    "James Clerk Maxwell (Giêm Cờ-lếch Mắc-xoen) đã phân tích bản chất của hiện tượng trên và cho rằng: điện trường xoáy vẫn xuất hiện ngay cả khi không có ống dây và vai trò của các vòng dây giúp ta nhận biết điện trường ấy trong suốt thời gian từ thông biến thiên.",
    "Khái quát bản chất của hiện tượng trên, Maxwell kết luận: *Trong vùng không gian có từ trường biến thiên theo thời gian thì trong vùng đó xuất hiện một điện trường xoáy.*",
    "",
    "[Hình 19.1. Thí nghiệm xuất hiện điện trường xoáy khi nam châm rơi qua ống dây]",
    "",
    "**Hoạt động**",
    "So sánh sự giống nhau và khác nhau giữa điện trường gây ra bởi điện tích đứng yên và điện trường xoáy.",
    "",
    "**2. Điện trường biến thiên và từ trường**",
    "Trong thí nghiệm Hình 19.1, khi từ trường biến thiên theo thời gian làm xuất hiện điện trường xoáy. Một câu hỏi ngược lại có thể đặt ra là điện trường biến thiên theo thời gian có làm xuất hiện từ trường không?",
    "",
    "82",
    "CHƯƠNG III – TỪ TRƯỜNG",
    "",
    "Thí nghiệm với dòng điện xoay chiều qua tụ điện cho thấy điện trường biến thiên theo thời gian và làm xuất hiện từ trường. Khi một tụ điện đang tích điện hoặc phóng điện, do sự thay đổi điện tích trên các bản tụ điện thì giữa hai bản tụ điện có một điện trường biến thiên tương đương với một dòng điện gọi là dòng điện dịch (Hình 19.3). Chính dòng điện này gây ra từ trường. Các đường sức của từ trường này bao quanh các đường sức của điện trường và luôn khép kín.",
    "[Hình 19.2. James Clerk Maxwell (1831-1879), nhà vật lí người Anh]",
    "",
    "**3. Điện từ trường**",
    "Maxwell đã đưa ra kết luận về mối liên quan chặt chẽ giữa điện trường biến thiên và từ trường biến thiên:",
    "*Từ trường biến thiên theo thời gian sinh ra trong không gian xung quanh một điện trường biến thiên theo thời gian; ngược lại, điện trường biến thiên theo thời gian cũng sinh ra một từ trường biến thiên theo thời gian trong không gian xung quanh.*",
    "Như vậy, hai trường biến thiên này cùng tồn tại trong không gian, có thể chuyển hoá lẫn nhau trong một trường thống nhất, gọi là điện từ trường (Hình 19.4).",
    "",
    "[Hình 19.3. Điện trường biến thiên giữa hai bản tụ điện và từ trường do nó sinh ra (trường hợp tụ điện đang tích điện, điện trường đang tăng)]",
    "[Hình 19.4. Điện từ trường]",
    "a) Điện trường biến thiên gây ra từ trường",
    "b) Từ trường biến thiên gây ra điện trường",
    "",
    "Sự biến thiên của từ trường và điện trường bao gồm sự thay đổi chiều và về độ lớn. Tuy nhiên, tại mỗi điểm trong không gian, vectơ cảm ứng từ $\\vec{B}$ luôn vuông góc với vectơ cường độ điện trường $\\vec{E}$.",
    "",
    "**? Câu hỏi:**",
    "So sánh điểm khác nhau cơ bản giữa điện từ trường với điện trường, từ trường.",
    "",
    "83",
    "CHƯƠNG III – TỪ TRƯỜNG",
    "",
    "## II. MÔ HÌNH SÓNG ĐIỆN TỪ",
    "**1. Sự tạo thành sóng điện từ**",
    "Nếu tại điểm O có một điện trường biến thiên $\\vec{E}_1$, thì theo kết luận của Maxwell, tại vùng lân cận sẽ xuất hiện một từ trường biến thiên $\\vec{B}_1$. Tiếp theo, vì có từ trường biến thiên, nên lại xuất hiện một điện trường $\\vec{E}_2$ biến thiên ở vùng lân cận khác, rồi tương tự, lại xuất hiện $\\vec{B}_2$,... Cứ như thế điện trường và từ trường lan truyền trong không gian như minh hoạ ở Hình 19.5.",
    "Quá trình lan truyền điện từ trường trong không gian được gọi là *sóng điện từ*.",
    "",
    "[Hình 19.5. Sự tạo thành sóng điện từ]",
    "",
    "**2. Sự lan truyền sóng điện từ**",
    "Tại mỗi điểm trong quá trình truyền sóng điện từ:",
    "- Vectơ cường độ điện trường $\\vec{E}$ luôn vuông góc với vectơ cảm ứng từ $\\vec{B}$, cả hai vectơ này luôn vuông góc với phương truyền sóng. Do đó, sóng điện từ là sóng ngang (Hình 19.6).",
    "- Cả $\\vec{E}$ và $\\vec{B}$ đều biến thiên điều hoà theo không gian và thời gian và luôn đồng pha.",
    "",
    "[Hình 19.6. Sự lan truyền sóng điện từ]",
    "",
    "**Hoạt động**",
    "1. Nêu mô hình sóng điện từ.",
    "2. Hãy cho biết phương truyền sóng điện từ trong Hình 19.5.",
    "3. Dựa vào mô hình sóng điện từ, hãy chứng tỏ sóng điện từ là sóng ngang, có thể lan truyền trong chân không.",
    "",
    "84",
    "CHƯƠNG III – TỪ TRƯỜNG",
    "",
    "Sóng điện từ truyền được trong chân không.",
    "Trong chân không, sóng điện từ có bước sóng $\\lambda$ là:",
    "$\\lambda = cT = \\frac{c}{f}$",
    "trong đó c là tốc độ ánh sáng trong chân không, T là chu kì của dao động điện từ, f là tần số của sóng điện từ.",
    "Trong quá trình lan truyền, sóng điện từ mang theo năng lượng. Sóng có tần số càng cao thì khả năng truyền càng xa. Sóng điện từ tuân theo quy luật truyền thẳng, phản xạ, khúc xạ, giao thoa và nhiễu xạ giống như sóng cơ.",
    "",
    "**? Câu hỏi:**",
    "1. Sóng điện từ khác sóng cơ ở điểm nào?",
    "2. Phát biểu nào sau đây là **sai** khi nói về sóng điện từ?",
    "A. Sóng điện từ là điện từ trường lan truyền trong không gian.",
    "B. Sóng điện từ không lan truyền được trong chân không.",
    "C. Sóng điện từ là sóng ngang.",
    "D. Tại một điểm trong không gian truyền sóng điện từ, vectơ $\\vec{E}$ và vectơ $\\vec{B}$ luôn đồng pha nhau.",
    "",
    "**EM ĐÃ HỌC**",
    "- Nếu tại một khoảng không gian có từ trường biến thiên theo thời gian thì trong khoảng không gian đó xuất hiện một điện trường biến thiên theo thời gian (gọi là điện trường xoáy).",
    "- Nếu tại một khoảng không gian có điện trường biến thiên theo thời gian thì trong khoảng không gian đó xuất hiện một từ trường biến thiên theo thời gian. Đường sức của từ trường bao giờ cũng khép kín.",
    "- Sóng điện từ là quá trình lan truyền điện từ trường trong không gian.",
    "- Sóng điện từ truyền được trong mọi môi trường vật chất, kể cả trong chân không. Đây chính là sự khác biệt giữa sóng điện từ và sóng cơ.",
    "- Tốc độ lan truyền sóng điện từ trong chân không bằng tốc độ ánh sáng.",
    "- Tại mỗi điểm trong quá trình truyền sóng, các vectơ $\\vec{E}$ và $\\vec{B}$ luôn vuông góc với nhau và vuông góc với phương truyền sóng. Sóng điện từ là sóng ngang.",
    "- Bước sóng của sóng điện từ trong chân không là $\\lambda = cT$, trong đó: c là tốc độ ánh sáng trong chân không, T là chu kì của dao động điện từ.",
    "",
    "**EM CÓ THỂ**",
    "- Mô tả được sự lan truyền sóng điện từ trong không gian.",
    "- Sử dụng mô hình sóng điện từ giải thích được tính chất của sóng điện từ.",
    "",
    "85"
  ]
}
