{
  "content": [
    "# Bài 20 BÀI TẬP VỀ TỪ TRƯỜNG",
    "",
    "**Khởi động:**",
    "*Để giải các bài tập về từ trường thì cần dùng những kiến thức cơ bản nào?*",
    "",
    "## I. MỘT SỐ LƯU Ý TRONG VIỆC GIẢI BÀI TẬP VỀ TỪ TRƯỜNG",
    "Phần từ trường bao gồm những nội dung chính như: mô tả từ trường, lực từ tác dụng lên đoạn dây dẫn thẳng mang dòng điện; cảm ứng điện từ; dòng điện xoay chiều; sóng điện từ.",
    "**1. Lưu ý khi giải bài tập định tính**",
    "Các bài tập này thường yêu cầu mô tả tính chất của từ trường, xác định phương, chiều của cảm ứng từ $\\vec{B}$ do các loại dòng điện tạo ra; xác định phương, chiều của lực từ tác dụng lên đoạn dây dẫn mang dòng điện; xác định chiều dòng điện cảm ứng, xác định điều kiện xuất hiện dòng điện cảm ứng; mô tả quá trình lan truyền sóng điện từ; giải thích các ứng dụng của lực từ, hiện tượng cảm ứng điện từ trong đời sống và trong kĩ thuật,...",
    "**2. Lưu ý khi giải bài tập định lượng**",
    "Các bài tập này thường yêu cầu vận dụng công thức xác định độ lớn của lực từ tác dụng lên đoạn dây dẫn, các công thức tính suất điện động cảm ứng, công thức xác định suất điện động của máy phát điện xoay chiều; công thức về mối quan hệ giữa các đại lượng hiệu dụng của dòng điện xoay chiều trong máy biến áp,...",
    "**3. Lưu ý khi giải bài tập thí nghiệm và bài tập đồ thị**",
    "Các bài tập này thường yêu cầu vận dụng các kiến thức và kĩ năng tiến hành, thu thập kết quả, xử lí số liệu, phân tích đồ thị. Để giải các bài tập này cần lưu ý việc chọn trục toạ độ, đơn vị cho phù hợp.",
    "",
    "## II. BÀI TẬP VÍ DỤ",
    "1. Đưa một nam châm lại gần vòng dây như Hình 20.1. Hãy xác định chiều dòng điện cảm ứng trong vòng dây và cho biết vòng dây sẽ chuyển động về phía nào?",
    "*Giải*",
    "- Cảm ứng từ của nam châm có chiều đi vào cực Nam (S), đi ra ở cực Bắc (N).",
    "- Vì nam châm đang lại gần vòng dây nên từ thông qua vòng dây tăng. Theo định luật Lenz, trong vòng dây sẽ xuất hiện dòng điện cảm ứng có chiều chống lại sự tăng của từ thông. Dòng điện cảm ứng tạo ra cảm ứng từ $\\vec{B}_c$ ngược chiều với cảm ứng từ $\\vec{B}$ của nam châm, suy ra cảm ứng từ $\\vec{B}_c$ có chiều từ phải sang trái.",
    "- Áp dụng quy tắc nắm bàn tay phải suy ra chiều của dòng điện cảm ứng có chiều như Hình 20.2.",
    "",
    "[Hình 20.1]",
    "[Hình 20.2]",
    "",
    "86",
    "CHƯƠNG III – TỪ TRƯỜNG",
    "",
    "- Cảm ứng từ của vòng dây có chiều đi vào mặt Nam, đi ra ở mặt Bắc, suy ra mặt đối diện của vòng dây với nam châm là mặt Bắc.",
    "- Vì cực Bắc của nam châm lại gần mặt Bắc của vòng dây nên vòng dây bị đẩy ra xa.",
    "",
    "2. Một dây dẫn có chiều dài 10 cm được đặt trong từ trường đều có cảm ứng từ B = 5.10$^{-2}$ T. Cho dòng điện có cường độ 10 A chạy qua dây dẫn.",
    "a) Xác định lực từ tác dụng lên dây dẫn khi dây dẫn đặt vuông góc với cảm ứng từ $\\vec{B}$.",
    "b) Khi lực từ tác dụng có độ lớn bằng 0,043 N, xác định góc giữa cảm ứng từ $\\vec{B}$ và chiều dòng điện.",
    "",
    "*Giải*",
    "a) Lực từ $\\vec{F}$ có đặc điểm:",
    "- Điểm đặt tại trung điểm đoạn dây dẫn mang dòng điện I.",
    "- Có phương vuông góc với đoạn dây dẫn mang dòng điện I và cảm ứng từ $\\vec{B}$ có chiều tuân theo quy tắc bàn tay trái.",
    "- Độ lớn: F = BIL$\\sin\\alpha$ = (5.10$^{-2}$).0,1.10.$\\sin90^\\circ$ = 0,05 N.",
    "b) Ta có:",
    "F = BIL$\\sin\\alpha \\Rightarrow \\sin\\alpha = \\frac{F}{BIL} = \\frac{0,043}{5.10^{-2}.10.0,1} \\approx 0,86 \\Rightarrow \\alpha \\approx 60^\\circ$",
    "",
    "3. Một khung dây dẫn phẳng có diện tích S = 20 cm$^2$, có N = 100 vòng dây (Hình 20.3), quay đều với tốc độ 50 vòng/giây quanh một trục vuông góc với các đường sức của một từ trường đều có cảm ứng từ B = 0,1 T. Chọn gốc thời gian t = 0 là lúc vectơ pháp tuyến $\\vec{n}$ của diện tích S của khung dây cùng chiều với vectơ cảm ứng từ $\\vec{B}$ và chiều dương là chiều quay của khung dây.",
    "a) Viết biểu thức xác định từ thông qua khung dây.",
    "b) Viết biểu thức xác định suất điện động xuất hiện trong khung dây.",
    "",
    "[Hình 20.3]",
    "",
    "*Giải*",
    "a) Khung dây dẫn quay đều với tốc độ góc: $\\omega = 50.2\\pi = 100\\pi$ (rad/s).",
    "Tại thời điểm ban đầu t = 0, vectơ pháp tuyến $\\vec{n}$ của diện tích S của khung dây có chiều trùng với chiều vectơ cảm ứng từ $\\vec{B}$ của từ trường. Đến thời điểm t, pháp tuyến $\\vec{n}$ của khung dây đã quay được một góc bằng $\\omega t$. Lúc này từ thông qua khung dây là: $\\Phi = NBS\\cos(\\omega t)$.",
    "Như vậy, từ thông qua khung dây biến thiên điều hoà theo thời gian với tần số góc $\\omega$ và với giá trị cực đại (biên độ) là $\\Phi_0 = NBS$.",
    "Thay N = 100, B = 0,1 T, S = 20 cm$^2$ = 20.10$^{-4}$ m$^2$ và $\\omega = 100\\pi$ (rad/s) ta được biểu thức của từ thông qua khung dây là: $\\Phi = 0,02\\cos(100\\pi t)$ (Wb).",
    "",
    "87",
    "CHƯƠNG III – TỪ TRƯỜNG",
    "",
    "b) Từ thông qua khung dây biến thiên điều hoà theo thời gian, theo định luật cảm ứng điện từ của Faraday thì trong khung dây xuất hiện một suất điện động cảm ứng.",
    "Suất điện động cảm ứng xuất hiện trong khung dây được xác định theo công thức:",
    "$e = \\omega NBS\\cos(\\omega t - \\frac{\\pi}{2})$",
    "Thay N = 100, B = 0,1 T, S = 20 cm$^2$ = 20. 10$^{-4}$ m$^2$ và $\\omega = 100\\pi$ (rad/s), ta được biểu thức xác định suất điện động xuất hiện trong khung dây là: $e = 6,28\\cos(100\\pi t - \\frac{\\pi}{2})$ (V).",
    "",
    "## III. BÀI TẬP VẬN DỤNG",
    "1. Đặt một khung dây dẫn hình chữ nhật có dòng điện chạy qua trong từ trường, sao cho mặt phẳng khung dây vuông góc với các đường cảm ứng từ (Hình 20.4) thì lực từ",
    "A. làm dãn khung.",
    "B. làm khung dây quay.",
    "C. làm nén khung.",
    "D. không tác dụng lên khung.",
    "[Hình 20.4]",
    "",
    "2. Đặt một thanh nam châm thẳng ở gần một khung dây kín ABCD như Hình 20.5. Xác định chiều của dòng điện cảm ứng xuất hiện trong khung dây khi đưa nam châm lại gần khung dây.",
    "[Hình 20.5]",
    "",
    "3. Một vòng dây phẳng giới hạn diện tích S = 40 cm$^2$ đặt trong từ trường đều có cảm ứng từ B = 0,1 T. Mặt phẳng vòng dây hợp với cảm ứng từ $\\vec{B}$ một góc $\\alpha = 30^\\circ$. Tính từ thông qua S.",
    "",
    "4. Hình 20.6 là ảnh chụp thí nghiệm đo lực từ của nam châm vĩnh cửu tác dụng lên đoạn dây dẫn đặt trong từ trường. Biết dây dẫn được cố định vào giá thí nghiệm (1) sao cho phương của đoạn dây dẫn (2) nằm ngang vuông góc với vectơ cảm ứng từ $\\vec{B}$ của nam châm (3) và không chạm vào nam châm nằm trên cân. Số liệu thí nghiệm thu được như trong Bảng 20.1. Trong đó L là chiều dài đoạn dây dẫn mang dòng điện đặt trong từ trường, F là độ lớn của lực từ tác dụng lên đoạn dây dẫn, I là cường độ dòng điện.",
    "[Hình 20.6. Thí nghiệm đo lực từ]",
    "",
    "88",
    "CHƯƠNG III – TỪ TRƯỜNG",
    "",
    "**Bảng 20.1.** *Kết quả thí nghiệm*",
    "| | | | | | | |",
    "|---|---|---|---|---|---|---|",
    "| I (A) | 2,5 | 5,1 | 10,1 | 20,2 | 5,1 | 10,1 |",
    "| L (cm) | 1,2 | 1,2 | 1,2 | 1,2 | 0,7 | 0,7 |",
    "| F (N) | 0,008 | 0,015 | 0,030 | 0,060 | 0,009 | 0,017 |",
    "",
    "a) Vì sao sử dụng cân điện tử như trong Hình 20.6 có thể xác định được độ lớn lực từ tác dụng lên đoạn dây?",
    "b) Từ số liệu trong bảng, hãy tính độ lớn cảm ứng từ B của nam châm.",
    "",
    "**EM ĐÃ HỌC**",
    "- Cách giải các bài tập về từ trường.",
    "",
    "**EM CÓ THỂ**",
    "- Vận dụng các kiến thức về từ trường, lực từ tác dụng lên đoạn dây dẫn thẳng mang dòng điện, cảm ứng từ, dòng điện xoay chiều, sóng điện từ để giải các bài tập có liên quan.",
    "",
    "89"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH4' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI12')), 'B21', 'Cấu trúc hạt nhân', 93, 1, $JSON$
{
  "content": [
    "# Bài 21 CẤU TRÚC HẠT NHÂN",
    "",
    "**Khởi động:**",
    "*Kích thước nguyên tử nhỏ tới mức kính hiển vi quang học hiện đại nhất cũng không thể giúp chúng ta quan sát rõ. Hạt nhân có kích thước còn nhỏ hơn rất nhiều (khoảng 0,0001 lần) so với nguyên tử. Các nhà khoa học đã làm thế nào để phát hiện ra điều đó?*",
    "",
    "## I. THÍ NGHIỆM TÁN XẠ HẠT ALPHA",
    "Mô hình nguyên tử đầu tiên giống như một chiếc bánh ngọt có mận khô bên trong, các mẩu mận khô biểu diễn các electron mang điện tích âm có khối lượng và kích thước rất nhỏ so với nguyên tử (Hình 21.1). Phần còn lại của bánh biểu diễn phần còn lại của nguyên tử mang điện tích dương, nặng gần bằng nguyên tử và chiếm gần như toàn bộ không gian nguyên tử.",
    "Năm 1911, Ernest Rutherford (Ê-nét Ru-gơ-pho) tiến hành thí nghiệm khám phá cấu tạo nguyên tử vàng (Hình 21.2) và đề xuất mô hình nguyên tử mới có tên mô hình hành tinh nguyên tử. Trong thí nghiệm này, Rutherford sử dụng chùm hạt alpha mang điện tích dương (kí hiệu $\\alpha$, chính là hạt nhân nguyên tử He). Chùm hạt này được phát ra từ nguồn R bắn vào lá vàng D rất mỏng (độ dày chỉ khoảng $4.10^{-7} \\text{ m}$), được đặt trong hộp chân không G. Để phát hiện các hạt alpha sau khi đi qua lá vàng, ông dùng kính hiển vi M để quan sát các đốm sáng phát ra khi các hạt này đập vào kính S có phủ chất huỳnh quang.",
    "",
    "[Hình 21.1. Ảnh chụp bánh ngọt có mận khô]",
    "[Hình 21.2. Bố trí thí nghiệm tán xạ hạt alpha]",
    "a) Hình vẽ phối cảnh",
    "b) Hình vẽ mặt cắt",
    "",
    "Khi di chuyển kính hiển vi từ vị trí (1) đến vị trí (2) (Hình 21.2b), tần suất đốm sáng xuất hiện trên màn S giảm đi rất nhanh. Tại vị trí (2) vẫn thấy xuất hiện các đốm sáng nhưng tần suất ít hơn so với tại vị trí (1) cỡ $10^4$ lần. Kết quả thí nghiệm có thể được minh hoạ như Hình 21.3.",
    "",
    "91",
    "CHƯƠNG IV – VẬT LÍ HẠT NHÂN VÀ PHÓNG XẠ",
    "",
    "[Hình 21.3. Minh hoạ kết quả thí nghiệm tán xạ hạt alpha]",
    "[Hình 21.4. Hiện tượng tán xạ hạt alpha]",
    "",
    "Hiện tượng lệch hướng chuyển động của hạt alpha khi đến gần hạt nhân vàng gọi là *hiện tượng tán xạ hạt alpha* (Hình 21.4).",
    "",
    "**Hoạt động**",
    "1. Dựa vào kết quả thí nghiệm tán xạ hạt $\\alpha$ để trả lời các câu hỏi sau:",
    "a) Tần suất đốm sáng xuất hiện khi kính hiển vi ở vị trí (1) (vị trí đối diện với nguồn phát tia $\\alpha$ – Hình 21.2 b) là lớn nhất chứng tỏ điều gì?",
    "b) Tại sao có một số hạt $\\alpha$ đổi hướng chuyển động khi đi qua lá vàng?",
    "c) Số hạt $\\alpha$ không đi qua lá vàng mà bật lại tới vị trí (2) với tần suất chỉ bằng $10^{-4}$ lần tần suất hạt $\\alpha$ đi qua lá vàng tới vị trí (1) chứng tỏ điều gì?",
    "2. Dựa trên thí nghiệm tán xạ hạt $\\alpha$, Rutherford đề xuất một mô hình hành tinh nguyên tử (Hình 21.5 a).",
    "a) Mô tả mô hình hành tinh nguyên tử của Rutherford.",
    "b) Giải thích mô hình cấu tạo nguyên tử của Rutherford dựa vào các câu trả lời ở ý 1.",
    "",
    "[Hình 21.5. Một số mô hình nguyên tử]",
    "a) Mô hình hành tinh nguyên tử của Rutherford",
    "b) Mô hình đám mây electron",
    "",
    "92",
    "CHƯƠNG IV – VẬT LÍ HẠT NHÂN VÀ PHÓNG XẠ",
    "",
    "**EM CÓ BIẾT**",
    "Mẫu hành tinh nguyên tử của Rutherford không giải thích được tính bền vững của các nguyên tử và sự tạo thành quang phổ vạch của các nguyên tử. Năm 1913, Bohr (Bo) đã dựa trên mô hình nguyên tử của Rutherford và vận dụng thuyết lượng tử ánh sáng để đề xuất mẫu nguyên tử mới gọi là mẫu nguyên tử Bohr. Trong mẫu này, Bohr vẫn giữ mô hình hành tinh nguyên tử của Rutherford nhưng đã bổ sung các tiên đề về cấu trúc nguyên tử. Mẫu này đã giải thích được sự tạo thành quang phổ vạch của các nguyên tử, đặc biệt là của nguyên tử hydrogen. Tuy nhiên, mô hình nguyên tử của Bohr không giải thích được nhiều tính chất của các nguyên tử khác. Hiện nay, người ta vận dụng các lí thuyết của Erwin Schrödinger (Ê-uyn Srô-đin-gơ) để đưa ra mô hình đám mây điện tử. Trong mô hình này, các electron có thể xuất hiện ở mọi vị trí trong không gian nguyên tử với xác suất nào đó và mật độ xác suất có mặt của electron được biểu diễn bằng các đám mây electron (Hình 21.5b). Mô hình này có thể giải thích được quang phổ vạch của các loại nguyên tử.",
    "",
    "## II. NUCLEON VÀ KÍ HIỆU HẠT NHÂN",
    "**1. Nucleon**",
    "Theo mô hình nguyên tử Rutherford, hạt nhân tích điện dương bằng Z.e (Z là số thứ tự trong bảng tuần hoàn, gọi là số hiệu nguyên tử), với kích thước của hạt nhân rất nhỏ.",
    "*Hạt nhân được tạo thành bởi hai loại hạt là proton và neutron, hai loại hạt này có tên chung là nucleon (Hình 21.6).*",
    "Proton (kí hiệu p), có khối lượng m$_p \\approx 1,67262.10^{-27}$ kg, điện tích là q = +e $\\approx 1,6.10^{-19}$ C và hạt neutron (kí hiệu n) có khối lượng m$_n \\approx 1,67493.10^{-27}$ kg, trung hoà về điện.",
    "[Hình 21.6. Hạt nhân $^{28}_{14}Si$ có cấu tạo gồm 14 proton và 14 neutron]",
    "",
    "Khối lượng nguyên tử bằng tổng khối lượng hạt nhân và electron có trong nguyên tử. Hạt nhân có khối lượng rất lớn so với khối lượng của các electron, vì vậy khối lượng nguyên tử gần như tập trung toàn bộ ở hạt nhân.",
    "Để thuận lợi tính toán khối lượng của hạt nhân, người ta định nghĩa một đơn vị mới gọi là *đơn vị khối lượng nguyên tử*, kí hiệu là amu. Đơn vị amu có giá trị bằng $\\frac{1}{12}$ khối lượng nguyên tử của đồng vị carbon-12:",
    "$1 \\text{ amu} \\approx 1,66054.10^{-27} \\text{ kg}$",
    "",
    "**? Câu hỏi:**",
    "Xác định khối lượng của proton và neutron theo đơn vị amu.",
    "",
    "Số proton trong hạt nhân bằng Z. Tổng số nucleon trong một hạt nhân được kí hiệu là A; A gọi là *số khối*.",
    "",
    "93",
    "CHƯƠNG IV – VẬT LÍ HẠT NHÂN VÀ PHÓNG XẠ",
    "",
    "Các nucleon nằm sát nhau và không chồng lấn vào nhau. Có thể coi hạt nhân nguyên tử như một quả cầu bán kính R; R phụ thuộc vào tổng số hạt nucleon A theo công thức gần đúng:",
    "$R = 1,2.10^{-15}.A^{\\frac{1}{3}} (m)$ (21.1)",
    "",
    "**? Câu hỏi:**",
    "Công thức 21.1 cho kết quả tốt hơn với A > 12. Nghiệm lại sự chính xác của công thức này cho các hạt nhân trong Bảng 21.1",
    "",
    "**Bảng 21.1.** *Kích thước của một số hạt nhân*",
    "| Tên nguyên tố | Số khối | Bán kính nguyên tử ($10^{-10} m$) | Bán kính hạt nhân ($10^{-15} m$) |",
    "|---|---|---|---|",
    "| Hydrogen | 1 | 1,2 | 0,9 |",
    "| Helium | 4 | 1,4 | 1,7 |",
    "| Oxigen | 16 | 1,5 | 2,7 |",
    "| Silicon | 28 | 2,1 | 3,1 |",
    "| Sắt | 56 | 1,9 | 3,7 |",
    "| Cadimium | 114 | 1,6 | 4,6 |",
    "| Vàng | 197 | 1,7 | 5,4 |",
    "| Uranium | 238 | 1,9 | 5,9 |",
    "",
    "**EM CÓ BIẾT**",
    "Hạt nucleon vẫn chưa phải là hạt nhỏ nhất, còn có các hạt nhỏ bé hơn cấu tạo lên các nucleon, gọi là hạt quark (Hình 21.7).",
    "[Hình 21.7. Cỡ kích thước của một số loại hạt vi mô]",
    "Tinh thể: $10^{-2} \\text{ m}$",
    "Phân tử: $10^{-9} \\text{ m}$",
    "Nguyên tử: $10^{-10} \\text{ m}$",
    "Hạt nhân: $10^{-14} \\text{ m}$",
    "Proton: $10^{-15} \\text{ m}$",
    "Electron: $10^{-18} \\text{ m}$",
    "Quark",
    "",
    "**2. Kí hiệu hạt nhân**",
    "Người ta dùng kí hiệu hoá học X của nguyên tố để kí hiệu cho hạt nhân, kèm theo hai số Z và A như sau: $^A_Z\\text{X}$.",
    "Ví dụ: hạt nhân carbon có 12 nucleon trong đó có 6 proton được kí hiệu $^{12}_6\\text{C}$.",
    "Để kí hiệu gọn hơn, người ta thường chỉ ghi theo dạng $^A\\text{X}$ (ví dụ $^{12}\\text{C}$).",
    "",
    "94",
    "CHƯƠNG IV – VẬT LÍ HẠT NHÂN VÀ PHÓNG XẠ",
    "",
    "**? Câu hỏi:**",
    "1. Trong kí hiệu hạt nhân, đại lượng N = A – Z cho biết số lượng của loại hạt nào trong hạt nhân? Vì sao?",
    "2. Bằng cách nào có thể tìm được số Z và số N của hạt nhân có kí hiệu dạng $^A\\text{X}$?",
    "3. Viết kí hiệu hạt nhân vàng (Au), helium (He) và nitrogen (N), biết rằng số lượng nucleon của các hạt nhân này lần lượt là 197; 4 và 14.",
    "",
    "**3. Đồng vị**",
    "*Các hạt nhân đồng vị là những hạt nhân có cùng số Z, khác số A, nghĩa là cùng số proton và khác số neutron.*",
    "Ví dụ: Hydrogen có ba đồng vị: hydrogen thường $^1_1\\text{H}$; hydrogen nặng $^2_1\\text{H}$ còn gọi là deuterium ($^2_1\\text{D}$); hydrogen siêu nặng $^3_1\\text{H}$ còn gọi là tritium ($^3_1\\text{T}$).",
    "Các đồng vị được chia làm hai loại: đồng vị bền và đồng vị phóng xạ (không bền). Hầu hết các mẫu chất trong tự nhiên đều là hỗn hợp của nhiều đồng vị.",
    "Carbon có ba đồng vị chính là $^{12}_6\\text{C}$, $^{13}_6\\text{C}$, $^{14}_6\\text{C}$, trong đó đồng vị $^{12}_6\\text{C}$ và $^{13}_6\\text{C}$ là đồng vị bền chiếm hơn 99% carbon tự nhiên.",
    "",
    "**? Câu hỏi:**",
    "Giải thích tại sao các chất cấu tạo từ cùng một loại nguyên tố nhưng khối lượng riêng vẫn có thể khác nhau.",
    "",
    "**EM ĐÃ HỌC**",
    "- Hạt nhân mang điện tích dương, có khối lượng gần bằng khối lượng nguyên tử chứa nó nhưng kích thước nhỏ hơn kích thước nguyên tử cỡ 10$^4$ lần.",
    "- Đơn vị khối lượng nguyên tử kí hiệu là amu; 1amu có giá trị bằng $\\frac{1}{12}$ khối lượng nguyên tử của đồng vị $^{12}_6\\text{C}$; $1 \\text{ amu} \\approx 1,66054.10^{-27} \\text{ kg}$.",
    "- Hạt nhân nguyên tử được tạo thành bởi các hạt nucleon. Có hai loại nucleon là proton mang điện tích +1e và neutron trung hoà về điện. Các nucleon có khối lượng xấp xỉ bằng 1amu.",
    "- Kí hiệu hạt nhân $^A_Z\\text{X}$, trong đó X, A, Z lần lượt là kí hiệu hoá học nguyên tố, số khối và số hiệu nguyên tử.",
    "",
    "**EM CÓ THỂ**",
    "- Giải thích được thế giới vật chất vĩ mô đa dạng quanh ta đều được tạo thành bởi các hạt proton, neutron và electron.",
    "- Đánh giá được kích thước của hạt nhân từ thí nghiệm tán xạ hạt $\\alpha$.",
    "",
    "95"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH4' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI12')), 'B22', 'Phản ứng hạt nhân và năng lượng liên kết', 98, 2, $JSON$
{
  "content": [
    "# Bài 22 PHẢN ỨNG HẠT NHÂN VÀ NĂNG LƯỢNG LIÊN KẾT",
    "",
    "**Khởi động:**",
    "*Chiếc tem thư phát hành năm 1971 có in hình Rutherford và phương trình phản ứng hạt nhân được thực hiện lần đầu tiên trên thế giới vào năm 1909. Người ta đã thực hiện thí nghiệm phát hiện phản ứng hạt nhân như thế nào? Các hạt nhân có thể biến đổi thành các hạt nhân khác không?*",
    "[Hình: Chiếc tem thư phát hành năm 1971]",
    "",
    "## I. PHẢN ỨNG HẠT NHÂN",
    "**1. Thí nghiệm phát hiện phản ứng hạt nhân**",
    "Rutherford đã cho chùm hạt alpha ($^4_2\\text{He}$), phóng ra từ nguồn phóng xạ $^{210}_{84}\\text{Po}$ đặt tại P, bắn phá hạt nhân $^{14}_7\\text{N}$ có trong không khí được dẫn theo đường nạp và hút khí A (Hình 22.1). Kính hiển vi K dùng để quan sát vết sáng được tạo ra do hạt nhân đập vào màn phủ huỳnh quang S. Từ kết quả thí nghiệm, ông cho rằng có hạt nhân $^1_1\\text{H}$ trong sản phẩm. Tuy nhiên, ông chưa đưa ra được kết luận về bản chất diễn biến của quá trình tương tác trên.",
    "",
    "[Hình 22.1. Sơ đồ thí nghiệm của Rutherford]",
    "",
    "Năm 1925, Patrick Blackett (Pa-trích Bơ-lách-két) đã sử dụng buồng sương để chụp được dấu vết tương tác này, đó chính là vết sương rẽ nhánh trong Hình 22.2. Buồng sương là một buồng hơi ở trạng thái siêu bão hòa, có thể tạo ra các vệt sương đủ to dọc theo đường đi của các hạt mang điện chuyển động mà mắt thường có thể nhìn thấy được. Kết quả phân tích hình ảnh của vết sương rẽ nhánh là bằng chứng giúp ông đi tới kết luận: Trong một số trường hợp, hạt $^4_2\\text{He}$ bắn phá vào hạt nhân $^{14}_7\\text{N}$ đã tạo ra hai hạt nhân mới đó là $^{17}_8\\text{O}$ và $^1_1\\text{H}$.",
    "",
    "[Hình 22.2. Ảnh kết quả thí nghiệm của Blackett]",
    "",
    "96",
    "CHƯƠNG IV – VẬT LÍ HẠT NHÂN VÀ PHÓNG XẠ",
    "",
    "**Hoạt động**",
    "So sánh tổng số điện tích, tổng số nucleon của các hạt nhân trước và sau khi tương tác trong thí nghiệm như mô tả ở Hình 22.2.",
    "",
    "**2. Các loại phản ứng hạt nhân**",
    "Người ta gọi quá trình biến đổi hạt nhân này thành hạt nhân khác là *phản ứng hạt nhân*.",
    "Phương trình phản ứng hạt nhân trong thí nghiệm của Blackett là:",
    "$^4_2\\text{He} + ^{14}_7\\text{N} \\rightarrow ^{17}_8\\text{O} + ^1_1\\text{H}$",
    "Phản ứng hạt nhân thường được chia làm hai loại:",
    "- *Phản ứng hạt nhân kích thích:* là quá trình các hạt nhân tương tác với các hạt khác (ví dụ: hạt nhân, neutron,...) tạo ra các hạt nhân mới. Ví dụ: phản ứng phân hạch, phản ứng tổng hợp hạt nhân (xem mục III và IV).",
    "- *Phản ứng hạt nhân tự phát:* là quá trình tự phân rã của một hạt nhân không bền vững thành các hạt nhân mới. Ví dụ: hiện tượng phân rã hạt nhân $^{238}_{92}\\text{U}$ được công bố lần đầu tiên trên thế giới bởi Henri Becquerel (Hen-ri Be-cơ-ren) (xem Bài 23):",
    "$^{238}_{92}\\text{U} \\rightarrow ^{234}_{90}\\text{Th} + ^4_2\\text{He}$",
    "",
    "**? Câu hỏi:**",
    "Hãy trình bày sự khác nhau giữa phản ứng hạt nhân và phản ứng hoá học.",
    "",
    "**3. Định luật bảo toàn số khối và bảo toàn điện tích trong phản ứng hạt nhân**",
    "Phản ứng hạt nhân là một quá trình vật lí, trong đó hệ các hạt tương tác được xem là hệ kín, do đó phản ứng hạt nhân tuân theo nhiều định luật bảo toàn.",
    "**Định luật bảo toàn số nucleon (bảo toàn số khối A)**",
    "*Trong phản ứng hạt nhân, tổng số nucleon của các hạt trước phản ứng bằng tổng số nucleon của các hạt tạo thành sau phản ứng. Bảo toàn số nucleon cũng là bảo toàn số khối A.*",
    "**Định luật bảo toàn điện tích**",
    "*Tổng đại số các điện tích của các hạt trước phản ứng bằng tổng đại số các điện tích của các hạt tạo thành sau phản ứng.*",
    "",
    "**Hoạt động**",
    "1. Hãy viết biểu thức liên hệ giữa các số khối và biểu thức liên hệ giữa các điện tích của các hạt nhân trong phản ứng hạt nhân:",
    "$^{A_1}_{Z_1}\\text{X}_1 + ^{A_2}_{Z_2}\\text{X}_2 \\rightarrow ^{A_3}_{Z_3}\\text{X}_3 + ^{A_4}_{Z_4}\\text{X}_4$",
    "2. Khi bắn phá $^{235}_{92}\\text{U}$ bằng neutron $^1_0\\text{n}$ người ta thấy chúng hợp nhất thành hạt nhân X, ngay sau đó hạt nhân X phân rã thành $^{99}_{42}\\text{Mo}$, ba hạt neutron và một hạt nhân Y.",
    "a) Viết các phương trình phản ứng hạt nhân mô tả trong quá trình trên.",
    "b) Sử dụng bảng hệ thống tuần hoàn hãy xác định tên gọi và kí hiệu các hạt nhân X và Y.",
    "",
    "97",
    "CHƯƠNG IV – VẬT LÍ HẠT NHÂN VÀ PHÓNG XẠ",
    "",
    "## II. NĂNG LƯỢNG LIÊN KẾT",
    "**1. Lực hạt nhân và năng lượng liên kết**",
    "*Lực tương tác giữa các nucleon trong hạt nhân là lực hút, gọi là lực hạt nhân, có tác dụng liên kết các nucleon với nhau.* Lực hạt nhân không phải là lực tĩnh điện, nó không phụ thuộc vào điện tích của nucleon. So với lực điện từ và lực hấp dẫn, lực hạt nhân có cường độ rất lớn. Tương tác hạt nhân chỉ đáng kể khi các hạt nucleon nằm cách nhau một khoảng rất ngắn, bằng hoặc nhỏ hơn kích thước của hạt nhân. Nói một cách khác, bán kính tác dụng của lực hạt nhân cỡ $10^{-15} \\text{ m}$. Muốn tách nucleon ra khỏi hạt nhân, cần phải tốn năng lượng để thắng lực hạt nhân.",
    "*Năng lượng tối thiểu dùng để tách toàn bộ số nucleon ra khỏi hạt nhân bằng năng lượng liên kết hạt nhân $E_{lk}$.*",
    "Mức độ bền vững của một hạt nhân phụ thuộc vào năng lượng liên kết riêng, năng lượng này được tính theo công thức:",
    "$E_{lkr} = \\frac{E_{lk}}{A}$ (22.1)",
    "Hạt nhân có $E_{lkr}$ càng lớn thì càng bền vững và ngược lại.",
    "",
    "**? Câu hỏi:**",
    "Vì sao để tách được các nucleon ra khỏi hạt nhân cần một năng lượng lớn?",
    "",
    "**Hoạt động**",
    "1. Nêu mối liên hệ giữa độ bền vững của hạt nhân và năng lượng liên kết riêng.",
    "2. Giá trị năng lượng liên kết riêng $E_{lkr}$ của nhiều hạt nhân được biểu diễn trên đồ thị Hình 22.3. Em hãy:",
    "a) Chỉ ra hai hạt nhân bền vững nhất, ước lượng $E_{lkr}$ của chúng.",
    "b) Xác định năm hạt nhân nhẹ (A $\\le$ 30) và bốn hạt nhân nặng (A $\\ge$ 160) có $E_{lkr} < 8,2 \\text{ MeV}$.",
    "",
    "[Hình 22.3. Phân bố giá trị năng lượng liên kết riêng theo số khối của các hạt nhân]",
    "",
    "98",
    "CHƯƠNG IV – VẬT LÍ HẠT NHÂN VÀ PHÓNG XẠ",
    "",
    "**2. Độ hụt khối**",
    "Khi so sánh khối lượng của hạt nhân $^4_2\\text{He}$ ($m_{\\text{He}} \\approx 4,00015 \\text{ amu}$) với tổng khối lượng các nucleon tạo thành hạt nhân đó:",
    "$2m_p + 2m_n \\approx 2.1,00728 + 2.1,00866 = 4,03188 \\text{ amu}$,",
    "ta thấy khối lượng của hạt nhân $^4_2\\text{He}$ nhỏ hơn tổng khối lượng của các nucleon thành phần (Hình 22.4).",
    "Tính chất này là tổng quát đối với mọi hạt nhân. *Độ chênh lệch giữa tổng khối lượng của các nucleon tạo thành hạt nhân và khối lượng $m_X$ của hạt nhân gọi là độ hụt khối của hạt nhân, kí hiệu là $\\Delta m$:*",
    "$\\Delta m = [Zm_p + (A - Z)m_n] - m_X$ (22.2)",
    "",
    "[Hình 22.4. Minh hoạ các nucleon đã liên kết thành hạt nhân nhẹ hơn các nucleon thành phần]",
    "",
    "**? Câu hỏi:**",
    "Hãy tính độ hụt khối của hạt nhân oxygen $^{16}_8\\text{O}$, biết khối lượng hạt nhân oxygen là $m_O \\approx 15,99492 \\text{ amu}$.",
    "",
    "**3. Mối liên hệ giữa năng lượng và khối lượng**",
    "Theo thuyết tương đối của Einstein (Anh-xtanh), một vật có khối lượng m thì cũng có năng lượng tương ứng là E và ngược lại:",
    "E = mc$^2$ (22.3)",
    "Với c là tốc độ của ánh sáng trong chân không.",
    "",
    "**! Lưu ý:** Cũng theo thuyết tương đối của Einstein, một vật có khối lượng m$_0$ ở trạng thái nghỉ sẽ có năng lượng nghỉ E$_0$ = m$_0$c$^2$ thì khi chuyển động vật có khối lượng m và năng lượng của vật khi đó gọi là năng lượng toàn phần E = mc$^2$.",
    "",
    "Xét một hạt nhân $^A_Z\\text{X}$, ở trạng thái 1 có Z proton và (A – Z) neutron liên kết chặt chẽ với nhau, hạt nhân có năng lượng là E$_1$ = m$_X$c$^2$. Giả sử, trạng thái 2 ứng với hệ gồm Z proton và (A – Z) neutron không liên kết với nhau, hệ ở trạng thái 2 có năng lượng là E$_2$ = [Zm$_p$ + (A – Z)m$_n$]c$^2$.",
    "Năng lượng liên kết $E_{lk}$ của hạt nhân $^A_Z\\text{X}$ được xác định như sau:",
    "$E_{lk} = E_2 - E_1 = [Zm_p + (A - Z)m_n - m_X]c^2 = \\Delta mc^2$ (22.4)",
    "*Năng lượng liên kết của một hạt nhân được tính bằng tích của độ hụt khối của hạt nhân với thừa số c$^2$.*",
    "",
    "99",
    "CHƯƠNG IV – VẬT LÍ HẠT NHÂN VÀ PHÓNG XẠ",
    "",
    "**Hoạt động**",
    "Hãy thực hiện các yêu cầu sau:",
    "a) Tính năng lượng liên kết và năng lượng liên kết riêng của hạt nhân $^4_2\\text{He}$.",
    "b) Tìm hệ số chuyển đổi giữa các đơn vị amu và MeV/c$^2$.",
    "",
    "## III. PHẢN ỨNG PHÂN HẠCH HẠT NHÂN",
    "Hình 22.5, là đồ thị phân bố năng lượng liên kết riêng $E_{lkr}$ theo số khối A được vẽ đơn giản hoá từ đồ thị 22.3. Đồ thị này cho thấy, $E_{lkr}$ của hạt nhân nặng (ứng với đoạn đồ thị PQ) nhỏ hơn $E_{lkr}$ của hạt nhân có số khối trung bình (ứng với đoạn đồ thị QT). Do đó, quá trình biến đổi từ hạt nhân nặng vỡ thành các hạt nhân có số khối trung bình sẽ thu được các hạt nhân bền vững hơn.",
    "",
    "[Hình 22.5. Đồ thị đơn giản hoá phân bố năng lượng liên kết riêng theo số khối]",
    "$E_{lkr}$ (MeV)",
    "",
    "*Phản ứng phân hạch là phản ứng trong đó một hạt nhân nặng vỡ thành hai hạt nhân nhẹ hơn.* Hai hạt nhân này, hay còn gọi là sản phẩm phân hạch, có số khối trung bình và bền vững hơn so với hạt nhân ban đầu.",
    "",
    "**1. Sự phân hạch của uranium**",
    "Năm 1939, Otto Hahn (Ốt-tô Han) đã làm thí nghiệm dùng neutron nhiệt (động năng nhỏ hơn 0,1 eV) bắn vào $^{235}_{92}\\text{U}$. Kết quả cho thấy hạt nhân $^{235}_{92}\\text{U}$ vỡ thành hai hạt nhân có khối lượng nhỏ hơn. Kèm theo quá trình phân hạch này có một số neutron được giải phóng (Hình 22.6).",
    "Phương trình phản ứng là:",
    "$^1_0\\text{n} + ^{235}_{92}\\text{U} \\rightarrow ^{236}_{92}\\text{U}^* \\rightarrow ^{95}_{39}\\text{Y} + ^{138}_{53}\\text{I} + 3^1_0\\text{n}$",
    "Phản ứng toả ra năng lượng khoảng 200 MeV dưới dạng động năng của các hạt nhân sản phẩm.",
    "",
    "100",
    "CHƯƠNG IV – VẬT LÍ HẠT NHÂN VÀ PHÓNG XẠ",
    "",
    "$^{235}_{92}\\text{U}$ hấp thụ neutron thành $^{236}_{92}\\text{U}^*$ ở trạng thái kích thích.",
    "$^{236}_{92}\\text{U}^*$ bị biến dạng.",
    "Sau khoảng $10^{-14}$ s, $^{236}_{92}\\text{U}^*$ bị biến dạng đến mức không thể phục hồi.",
    "$^{236}_{92}\\text{U}^*$ phân hạch thành $^{95}_{39}\\text{Y}$, $^{138}_{53}\\text{I}$ và giải phóng 3 neutron.",
    "",
    "[Hình 22.6. Tiến trình phân hạch của $^{235}_{92}\\text{U}$]",
    "- Neutron",
    "- Proton",
    "",
    "Các thí nghiệm đã cho thấy rằng phản ứng phân hạch của một hạt nhân $^A_Z\\text{X}$ có thể xảy ra theo nhiều cách vỡ khác nhau. Quá trình này có thể viết dưới dạng phương trình phản ứng khái quát:",
    "$^1_0\\text{n} + ^A_Z\\text{X} \\rightarrow ^{A+1}_Z\\text{X}^* \\rightarrow ^{A_1}_{Z_1}\\text{X}_1 + ^{A_2}_{Z_2}\\text{X}_2 + k^1_0\\text{n}$",
    "Trong đó, $\\text{X}_1$ và $\\text{X}_2$ là các hạt nhân có số khối trung bình và hầu hết là các hạt nhân phóng xạ; k = 1, 2, 3 là số hạt neutron được sinh ra. Quá trình phân hạch của $^A_Z\\text{X}$ là không trực tiếp mà phải qua trạng thái kích thích $^{A+1}_Z\\text{X}^*$ không bền vững.",
    "",
    "**! Lưu ý:** Ngoài $^{235}_{92}\\text{U}$ còn có một số đồng vị hạt nhân khác như $^{237}_{93}\\text{Np}$, $^{239}_{94}\\text{Pu}$, $^{251}_{98}\\text{Cf}$,... cũng có tính chất phân hạch tương tự.",
    "",
    "**Hoạt động**",
    "Sự phân hạch hạt nhân là gì? Nêu đặc điểm phản ứng phân hạch của uranium.",
    "",
    "**2. Phản ứng phân hạch dây chuyền**",
    "*Các neutron sinh ra sau mỗi phân hạch của uranium (hoặc plutonium,...) có thể kích thích các hạt nhân khác trong mẫu chất phân hạch tạo nên những phản ứng phân hạch mới. Kết quả là các phản ứng phân hạch xảy ra liên tiếp tạo ra phản ứng dây chuyền và toả ra năng lượng rất lớn.*",
    "",
    "**? Câu hỏi:**",
    "1. Nêu đặc điểm của phản ứng phân hạch dây chuyền.",
    "2. Tính năng lượng toả ra khi phân hạch hoàn toàn 1 kg $^{235}_{92}\\text{U}$. Biết mỗi phân hạch toả ra năng lượng 200 MeV.",
    "",
    "101",
    "CHƯƠNG IV – VẬT LÍ HẠT NHÂN VÀ PHÓNG XẠ",
    "",
    "**EM CÓ BIẾT**",
    "Gọi k là số neutron trung bình được giải phóng sau mỗi phân hạch đến kích thích các hạt nhân $^{235}_{92}\\text{U}$ khác để tạo nên những phản ứng phân hạch mới hình thành dây chuyền phản ứng. Khi k < 1 ứng với phản ứng phân hạch dây chuyền tắt dần, k $\\ge$ 1 ứng với phân hạch dây chuyền tự duy trì (Hình 22.7).",
    "",
    "Trong phản ứng phân hạch dây chuyền tự duy trì, để giảm thiểu số neutron bị mất vì thoát ra ngoài, chất phân hạch phải có khối lượng lớn hơn một giá trị tối thiểu gọi là khối lượng tới hạn $m_{th}$. Nếu chất phân hạch $^{235}_{92}\\text{U}$, $^{239}_{94}\\text{Pu}$ không bị nén, không đặt trong thiết bị phản xạ neutron,... thì khối lượng tới hạn tương ứng của chúng đã được làm giàu khoảng 90% là $m_{th} \\approx 47 \\text{ kg}$ và $m_{th} \\approx 10 \\text{ kg}$ (làm giàu là biện pháp làm tăng tỉ lệ % khối lượng của đồng vị mong muốn trong chất phân hạch).",
    "",
    "[Hình 22.7. Minh hoạ phản ứng phân hạch dây chuyền với k > 1]",
    "",
    "## IV. PHẢN ỨNG TỔNG HỢP HẠT NHÂN",
    "*Phản ứng tổng hợp hạt nhân là phản ứng hạt nhân trong đó hai hay nhiều hạt nhân nhẹ tổng hợp lại thành một hạt nhân nặng hơn.* Từ đồ thị (Hình 22.5), có thể thấy quá trình các hạt nhân nhẹ (ứng với đoạn đồ thị MN) tổng hợp thành hạt nhân có số khối nặng hơn (ứng với đoạn đồ thị NT) sẽ thu được hạt nhân bền vững hơn vì hạt nhân đó có năng lượng liên kết riêng lớn hơn.",
    "Vào năm 1927, Oliphant (Ô-li-phan) đã dùng máy gia tốc để các hạt nhân $^2_1\\text{H}$ tương tác với nhau, kết quả tạo ra phản ứng tổng hợp hạt nhân đầu tiên trên thế giới:",
    "$^2_1\\text{H} + ^2_1\\text{H} \\rightarrow ^3_2\\text{He} + ^1_0\\text{n}$",
    "Phản ứng này toả năng lượng khoảng 4 MeV.",
    "Vì các hạt nhân đều mang điện tích dương, nên muốn cho hai hạt nhân nhẹ (số khối nhỏ) có thể hợp lại thành hạt nhân nặng hơn, ta phải cung cấp cho chúng một động năng đủ lớn để thắng lực đẩy tĩnh điện Coulomb giữa chúng và cho chúng tiến lại gần nhau đến mức mà lực hạt nhân phát huy tác dụng, làm chúng kết hợp với nhau. Phép tính chứng tỏ rằng, muốn có được một động năng lớn như vậy, khí $^2_1\\text{H}$ phải có nhiệt độ cỡ $10^9 \\text{ K}$. Trên thực tế, chỉ cần nhiệt độ vào khoảng $10^7$ đến $10^8 \\text{ K}$ là phản ứng tổng hợp hạt nhân này đã có thể xảy ra. Chính vì sự tổng hợp hạt nhân chỉ xảy ra ở nhiệt độ rất cao nên phản ứng này còn được gọi là *phản ứng nhiệt hạch*.",
    "",
    "102",
    "CHƯƠNG IV – VẬT LÍ HẠT NHÂN VÀ PHÓNG XẠ",
    "",
    "**EM CÓ BIẾT**",
    "Ngoài điều kiện nhiệt độ cao còn phải thoả mãn hai điều kiện nữa để phản ứng tổng hợp hạt nhân có thể xảy ra. Đó là: mật độ hạt nhân n phải đủ lớn, đồng thời thời gian $\\Delta t$ duy trì nhiệt độ cao (vào khoảng $10^7$ đến $10^8 \\text{ K}$) cũng phải đủ dài. J. D. Lawson (Lau-sơn, nhà khoa học người Anh) đã chứng minh điều kiện: $n.\\Delta t > 10^{14} \\text{ s/cm}^3$.",
    "",
    "**? Câu hỏi:**",
    "1. Sự tổng hợp hạt nhân là gì? Nêu điều kiện xảy ra phản ứng tổng hợp hạt nhân.",
    "2. So sánh định tính phản ứng tổng hợp hạt nhân và phản ứng phân hạch về các đặc điểm: nhiên liệu phản ứng và điều kiện xảy ra phản ứng.",
    "",
    "**EM ĐÃ HỌC**",
    "- Phản ứng hạt nhân là quá trình biến đổi từ hạt nhân này thành hạt nhân khác, bao gồm phản ứng hạt nhân kích thích và phản ứng hạt nhân tự phát.",
    "- Trong phản ứng hạt nhân, số khối và điện tích của hệ được bảo toàn.",
    "- Phản ứng phân hạch là phản ứng hạt nhân trong đó một hạt nhân nặng vỡ thành hai mảnh nhẹ hơn.",
    "- Phản ứng tổng hợp hạt nhân là phản ứng trong đó hai hay nhiều hạt nhân nhẹ tổng hợp lại thành một hạt nhân nặng hơn.",
    "- Độ hụt khối ($\\Delta m$) của hạt nhân là độ chênh lệch tổng khối lượng của các nucleon tạo thành hạt nhân và khối lượng của hạt nhân.",
    "$\\Delta m = [Zm_p + (A - Z)m_n] - m_X$",
    "- Năng lượng E và khối lượng m tương ứng của cùng một vật được liên hệ với nhau thông qua hệ thức Einstein:",
    "E = mc$^2$",
    "trong đó, c là tốc độ của ánh sáng trong chân không.",
    "- Năng lượng liên kết riêng $E_{lkr}$ của một hạt nhân có số khối A bằng:",
    "$E_{lkr} = \\frac{E_{lk}}{A}$",
    "trong đó, $E_{lk}$ là năng lượng tối thiểu dùng để tách toàn bộ số nucleon ra khỏi hạt nhân, gọi là năng lượng liên kết hạt nhân. Hạt nhân càng bền vững khi $E_{lkr}$ càng lớn.",
    "",
    "**EM CÓ THỂ**",
    "- Nêu được nguyên tắc để biến một chất bất kì thành một chất mong muốn.",
    "- Nêu được tiềm năng khai thác sử dụng năng lượng hạt nhân.",
    "- Giải thích được vì sao phản ứng phân hạch và tổng hợp hạt nhân toả năng lượng.",
    "- Giải thích nguồn gốc vạn vật.",
    "",
    "103"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH5' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI12')), 'B23', 'Hiện tượng phóng xạ', 106, 1, $JSON$
{
  "content": [
    "# Bài 23 HIỆN TƯỢNG PHÓNG XẠ",
    "",
    "**Khởi động:**",
    "*Khi gói miếng kim loại hình chữ thập (+) cùng một hòn đá có chứa uranium bằng tấm phim và để trong bóng tối vài ngày, Becquerel đã phát hiện trên tấm phim có vết sáng giống dấu chữ thập như hình bên. Nguyên nhân nào gây tác dụng lên phim dù nó được để trong bóng tối?*",
    "[Hình: Kết quả thí nghiệm của Becquerel thực hiện năm 1896]",
    "",
    "## I. HIỆN TƯỢNG PHÓNG XẠ",
    "**1. Định nghĩa hiện tượng phóng xạ**",
    "*Thí nghiệm buồng sương:* Khi đặt mẫu quặng uranium vào trong buồng sương, chúng ta thấy có nhiều vết sương màu trắng có dạng như các tia đi ra từ mẫu phóng xạ ở các hướng và các thời điểm ngẫu nhiên khác nhau (Hình 23.1). Các vết sương dạng tia này chính là đường đi của các hạt phóng ra từ mẫu quặng uranium, gọi là các tia phóng xạ.",
    "[Hình 23.1. Các vết sương dạng tia xuất hiện quanh mẫu quặng uranium]",
    "",
    "Ngoài quặng uranium còn có rất nhiều chất có thể phát ra tia phóng xạ. Tia phóng xạ không nhìn thấy được bằng mắt thường, nhưng có thể có những tác dụng như: ion hoá không khí, gây ra các hiệu ứng quang điện, phát xạ thứ cấp, làm đen kính ảnh, xuyên thấu lớp vật chất mỏng, phá huỷ tế bào, kích thích một số phản ứng hoá học,...",
    "*Hiện tượng một hạt nhân không bền vững tự phát biến đổi thành một hạt nhân khác đồng thời phát ra tia phóng xạ gọi là hiện tượng phóng xạ.* Quá trình biến đổi hạt nhân này còn được gọi là phân rã phóng xạ hoặc phân rã hạt nhân. Hạt nhân không bền vững, tự phân rã được gọi là hạt nhân mẹ. Hạt nhân được tạo thành, bền vững hơn được gọi là hạt nhân con.",
    "",
    "**Hoạt động**",
    "Tìm hiểu thông tin về phát hiện của Becquerel và thí nghiệm trên, cho biết:",
    "1. Hiện tượng phóng xạ xảy ra có tính tự phát hay phụ thuộc vào các yếu tố môi trường như nhiệt độ, áp suất,...?",
    "2. Có thể điều khiển được hiện tượng phóng xạ không? Tại sao?",
    "",
    "104",
    "CHƯƠNG IV – VẬT LÍ HẠT NHÂN VÀ PHÓNG XẠ",
    "",
    "**2. Tính ngẫu nhiên của phân rã phóng xạ**",
    "Xét thí nghiệm được bố trí như Hình 23.2: Nguồn phóng xạ (1) được đặt gần một đầu thu phóng xạ Geiger–Müller (Gai-gơ Muy-lơ) (2) theo một phương xác định. Mỗi khi có tia phóng xạ từ nguồn đến đầu thu, nó sẽ gửi tín hiệu đến thiết bị chuyển đổi tín hiệu (3) làm loa (4) phát ra một xung âm thanh đồng thời số đếm tia phóng xạ được hiển thị trên màn hình (5) sẽ nhảy lên 1 đơn vị. Kết quả thí nghiệm sau mỗi 5 s liên tiếp được thể hiện trong Bảng 23.1.",
    "[Hình 23.2. Thí nghiệm đếm tia phóng xạ]",
    "",
    "**Bảng 23.1.** *Kết quả ghi nhận số tia phóng xạ theo thời gian*",
    "| Khoảng thời gian (s) | 0 – 5 | 5 – 10 | 10 – 15 | 15 – 20 | 20 – 25 | 25 – 30 |",
    "|---|---|---|---|---|---|---|",
    "| Số tia phóng xạ | 1 | 3 | 2 | 0 | 3 | 1 |",
    "",
    "**Hoạt động**",
    "Sử dụng kết quả thí nghiệm trong Bảng 23.1 hãy thực hiện các yêu cầu sau:",
    "- Nhận xét về số lượng phân rã trong các khoảng thời gian bằng nhau liên tiếp.",
    "- Có thể dự đoán được thời điểm xảy ra và số lượng các phân rã phóng xạ không?",
    "",
    "Bằng nhiều thí nghiệm khác nữa, người ta đã thấy *quá trình phóng xạ là ngẫu nhiên.* Với một hạt nhân phóng xạ cho trước, thời điểm phân rã của nó là không xác định.",
    "",
    "**3. Các dạng phóng xạ**",
    "Khi cho các tia phóng xạ đi qua điện trường hoặc từ trường, các tia phóng xạ có thể lệch theo các cách khác nhau (Hình 23.3). Người ta thường phân loại phóng xạ thành 3 dạng như sau: phóng xạ alpha (kí hiệu $\\alpha$), phóng xạ beta (có hai loại kí hiệu là $\\beta^-$ và $\\beta^+$) và phóng xạ gamma (kí hiệu là $\\gamma$).",
    "[Hình 23.3. Sự lệch các tia phóng xạ trong điện trường (a) và từ trường (b)]",
    "Điện trường",
    "Từ trường",
    "",
    "105",
    "CHƯƠNG IV – VẬT LÍ HẠT NHÂN VÀ PHÓNG XẠ",
    "",
    "**a) Phóng xạ alpha**",
    "*Tia phóng xạ $\\alpha$ là hạt nhân $^4_2\\text{He}$ phóng ra từ hạt nhân mẹ có tốc độ khoảng $2.10^7$ m/s.* Tia $\\alpha$ làm ion hoá mạnh môi trường vật chất, do đó nó chỉ đi được khoảng vài cm trong không khí và dễ dàng bị tờ giấy dày 1 mm chặn lại (Hình 23.4). Hạt nhân mẹ X thường là các hạt nhân nặng, có số khối A > 190, phân rã tạo thành hạt nhân con Y, đồng thời phát ra tia phóng xạ $\\alpha$. Phương trình của phân rã phóng xạ $\\alpha$ có dạng:",
    "$^A_Z\\text{X} \\rightarrow ^{A-4}_{Z-2}\\text{Y} + ^4_2\\text{He}$",
    "[Hình 23.4. Khả năng đâm xuyên của các tia phóng xạ qua vật chất]",
    "Bìa giấy",
    "Nhôm",
    "Chì",
    "",
    "**? Câu hỏi:**",
    "1. Hãy nêu các tính chất của tia phóng xạ $\\alpha$.",
    "2. Hãy viết phương trình phân rã $\\alpha$ của hạt nhân $^{235}_{92}\\text{U}$.",
    "",
    "**b) Phóng xạ beta**",
    "Phóng xạ $\\beta$ gồm 2 loại: phóng xạ $\\beta^-$ và phóng xạ $\\beta^+$. Hai loại tia phóng xạ $\\beta^-$ và $\\beta^+$ có bản chất tương ứng là *hạt electron ($^0_{-1}e$)* và *hạt positron$^*$$^{0}_{+1}e$)* phóng ra từ hạt nhân mẹ với *tốc độ xấp xỉ tốc độ ánh sáng trong chân không.* Tia $\\beta$ làm ion hoá môi trường vật chất ở mức trung bình, nó có thể xuyên qua tờ giấy khoảng 1 mm nhưng có thể bị chặn bởi tấm nhôm dày khoảng 1 mm (Hình 23.4).",
    "Hạt nhân thực hiện phân rã tạo ra tia phóng xạ $\\beta$, ngoài sản phẩm là hạt nhân con, các $^0_{-1}e$ và $^{0}_{+1}e$ còn có hạt cơ bản khác là phản hạt neutrino ($\\bar{\\nu}$) và hạt neutrino ($\\nu$) không mang điện, có khối lượng nghỉ vô cùng nhỏ.",
    "Phương trình của phân rã phóng xạ $\\beta^-$ có dạng:",
    "$^A_Z\\text{X} \\rightarrow ^A_{Z+1}\\text{Y} + ^0_{-1}e + \\bar{\\nu}$",
    "Tương tự, đối với phóng xạ $\\beta^+$:",
    "$^A_Z\\text{X} \\rightarrow ^A_{Z-1}\\text{Y} + ^0_{+1}e + \\nu$",
    "",
    "**? Câu hỏi:**",
    "1. Hãy nêu các tính chất của phóng xạ $\\beta$.",
    "2. Viết phương trình phân rã $\\beta^-$ và $\\beta^+$ tương ứng của các đồng vị $^{90}_{38}\\text{Sr}$ và $^{18}_9\\text{F}$.",
    "",
    "**c) Phóng xạ gamma**",
    "Một số hạt nhân con sau quá trình phóng xạ $\\alpha$ hay $\\beta$ được tạo ra trong trạng thái kích thích $^A_Z\\text{Y}^*$. Khi đó, xảy ra tiếp quá trình hạt nhân đó chuyển từ trạng thái kích thích về trạng thái có mức năng lượng thấp hơn $^A_Z\\text{Y}$ *và phát ra bức xạ điện từ $\\gamma$ có bước sóng rất ngắn, cỡ nhỏ hơn $10^{-11}$ m, còn gọi là tia $\\gamma$*. Các tia $\\gamma$ có năng lượng cao, dễ dàng xuyên qua các vật liệu thông thường, ví dụ lớp bê tông dày hàng chục cm. Muốn cản trở được tia $\\gamma$, người ta thường dùng vật liệu có mật độ vật chất lớn và bề dày lớn, ví dụ tấm chì dày khoảng 10 cm (Hình 23.4).",
    "Phương trình của phân rã phóng xạ $\\gamma$ có dạng:",
    "$^A_Z\\text{Y}^* \\rightarrow ^A_Z\\text{Y} + \\gamma$",
    "",
    "106",
    "(*) Positron là phản hạt của electron, có cùng khối lượng với electron nhưng mang điện tích +e.",
    "CHƯƠNG IV – VẬT LÍ HẠT NHÂN VÀ PHÓNG XẠ",
    "",
    "**? Câu hỏi:**",
    "1. Hãy nêu các tính chất của phóng xạ $\\gamma$.",
    "2. Technetium ($^{99}_{43}\\text{Tc}^*$) là đồng vị phóng xạ $\\gamma$, được sử dụng rất phổ biến trong y học hạt nhân để chụp ảnh cơ quan bên trong cơ thể người. Viết phương trình phân rã của đồng vị này.",
    "",
    "**Hoạt động**",
    "Dựa vào đặc điểm các tia phóng xạ em hãy:",
    "1. Giải thích hướng lệch của từng tia phóng xạ trong điện trường và trong từ trường ở Hình 23.3.",
    "2. Giải thích lí do tại sao các tia $\\alpha$, $\\beta$ và $\\gamma$ có khả năng đâm xuyên khác nhau.",
    "",
    "## II. ĐỊNH LUẬT PHÓNG XẠ. ĐỘ PHÓNG XẠ",
    "**1. Định luật phóng xạ**",
    "Các quá trình phân rã phóng xạ đã nêu ở trên là quá trình ngẫu nhiên. Mặc dù, với một hạt nhân phóng xạ cho trước, thời điểm phân rã của nó là không xác định, nhưng khi xét một mẫu chất phóng xạ bao gồm một số lượng rất lớn các hạt nhân phóng xạ thì ta có thể khảo sát sự biến đổi mang tính quy luật của các hạt nhân đó.",
    "Khi thực hiện thí nghiệm phân rã phóng xạ một mẫu chất phóng xạ $^{220}_{86}\\text{Rn}$ với số hạt nhân ban đầu N$_0$, người ta thấy rằng cứ sau mỗi khoảng thời gian T = 55 s, chỉ còn một nửa số hạt nhân của mẫu chất phóng xạ chưa bị phân rã. Trong quá trình phân rã phóng xạ, số hạt nhân mẹ sẽ giảm theo thời gian.",
    "Thực nghiệm với các chất phóng xạ khác cũng thấy rằng, cứ sau một khoảng thời gian xác định T thì một nửa số hạt nhân hiện có sẽ bị phân rã, biến đổi thành hạt nhân khác; T được gọi là *chu kì bán rã* của chất phóng xạ.",
    "Điều đó có nghĩa là sau các thời gian t bằng T, 2T, 3T,... kT (k là số nguyên dương), số hạt nhân (số nguyên tử) N$_t$ chưa phân rã tương ứng bằng $\\frac{N_0}{2}$, $\\frac{N_0}{4}$, $\\frac{N_0}{8}$, ... $\\frac{N_0}{2^k}$. Tức là:",
    "$N_t = N_0.2^{-k}$, trong đó t = kT",
    "hay là:",
    "$N_t = N_0.2^{-\\frac{t}{T}}$ (23.1)",
    "Công thức (23.1) biểu diễn định luật phóng xạ: *Trong quá trình phân rã, số hạt nhân chất phóng xạ còn lại giảm theo thời gian theo định luật hàm số mũ.*",
    "Định luật này được minh hoạ bằng đồ thị trên Hình 23.5.",
    "Các đồng vị phóng xạ khác nhau có chu kì bán rã T khác nhau (Bảng 23.2).",
    "",
    "[Hình 23.5. Đồ thị minh hoạ sự thay đổi số hạt nhân chất phóng xạ còn lại thời gian]",
    "",
    "107",
    "CHƯƠNG IV – VẬT LÍ HẠT NHÂN VÀ PHÓNG XẠ",
    "",
    "**Bảng 23.2.** *Chu kì bán rã của một số đồng vị phóng xạ*",
    "| Đồng vị phóng xạ | Chu kì bán rã T |",
    "|---|---|",
    "| Carbon ($^{14}_6\\text{C}$) | $5,7.10^3$ năm |",
    "| Iodine ($^{131}_{53}\\text{I}$) | 8,0 ngày |",
    "| Oxygen ($^{15}_8\\text{O}$) | $1,2.10^2$ giây |",
    "| Polonium ($^{210}_{84}\\text{Po}$) | $1,4.10^2$ ngày |",
    "| Radium ($^{226}_{88}\\text{Ra}$) | $1,6.10^3$ năm |",
    "| Radon ($^{219}_{86}\\text{Rn}$) | 4,0 giây |",
    "| Uranium ($^{235}_{92}\\text{U}$) | $7,0.10^8$ năm |",
    "",
    "**? Câu hỏi:**",
    "1. Phát biểu định nghĩa chu kì bán rã?",
    "2. Đồng vị phóng xạ $^{15}_8\\text{O}$ sau khoảng thời gian 244 s có 75% số hạt nhân ban đầu đã bị phân rã thành hạt nhân khác. Tính chu kì bán rã của $^{15}_8\\text{O}$.",
    "",
    "**2. Độ phóng xạ**",
    "Để đặc trưng cho tính phóng xạ mạnh hay yếu của một lượng chất phóng xạ, người ta dùng đại lượng *độ phóng xạ (hay hoạt độ phóng xạ)*, kí hiệu là H, có giá trị bằng *số hạt nhân phân rã trong một giây.*",
    "Đơn vị độ phóng xạ là becơren (được lấy theo tên nhà bác học Becquerel), kí hiệu là Bq.",
    "1 Bq = 1 phân rã/1 giây.",
    "Trong thực tế, độ phóng xạ còn có đơn vị khác là curi (Curie, được lấy theo tên của hai nhà bác học: Marie Curie và chồng là Pierre Curie), kí hiệu là Ci.",
    "$1 \\text{ Ci} = 3,7.10^{10} \\text{ Bq}$, xấp xỉ bằng độ phóng xạ của một gam $^{226}_{88}\\text{Ra}$.",
    "Độ phóng xạ có thể được đo nhờ các thiết bị đo phóng xạ.",
    "Vì số hạt nhân của một lượng chất phóng xạ giảm dần, nên độ phóng xạ H của chất phóng xạ cũng giảm theo thời gian. Xét một mẫu chất phóng xạ có N$_t$ hạt nhân tại thời điểm t. Tại thời điểm $t + \\Delta t$, số hạt nhân đó giảm đi và trở thành $N_t + \\Delta N$, với $\\Delta N < 0$.",
    "Số hạt nhân đã phân rã trong khoảng thời gian $\\Delta t$ là $-\\Delta N$, do đó theo định nghĩa độ phóng xạ thì $H_t = -\\frac{\\Delta N}{\\Delta t}$. Xét khoảng thời gian $\\Delta t$ rất bé và sử dụng biểu thức (23.1) ta có độ phóng xạ H$_t$ tại thời điểm t bất kì là:",
    "$H_t = -\\frac{dN_t}{dt} = -N'_t = \\frac{\\ln2}{T} N_0.2^{-\\frac{t}{T}}$",
    "Vậy $H_t = \\lambda N_t$ (23.2)",
    "",
    "108",
    "CHƯƠNG IV – VẬT LÍ HẠT NHÂN VÀ PHÓNG XẠ",
    "",
    "trong đó, đại lượng $\\lambda = \\frac{\\ln2}{T}$ được gọi là hằng số phóng xạ, đặc trưng cho chất phóng xạ đang xét. Đơn vị của $\\lambda$ là s$^{-1}$. Với định nghĩa này, phương trình (23.1) và (23.2) có dạng:",
    "$N_t = N_0e^{-\\lambda t}$ (23.3)",
    "$H_t = H_0e^{-\\lambda t}$ (23.4)",
    "Trong đó H$_0$ là độ phóng xạ tại thời điểm ban đầu t = 0.",
    "",
    "**? Câu hỏi:**",
    "1. Nêu ý nghĩa của hằng số phóng xạ.",
    "2. Dược chất phóng xạ Flortaucipir (chứa $^{18}_9\\text{F}$ là đồng vị phóng xạ $\\beta^+$) được tiêm vào bệnh nhân nhằm chụp ảnh bên trong cơ thể (chụp ảnh PET – Bài 24). Biết $^{18}_9\\text{F}$ có chu kì bán rã khoảng 110 phút.",
    "a) Sau khi tiêm bao lâu thì lượng $^{18}_9\\text{F}$ giảm còn 10% và 1% so với lúc đầu?",
    "b) Mỗi mL dược chất phóng xạ Flortaucipir có độ phóng xạ ban đầu là $10^9 \\text{ Bq}$. Xác định số lượng hạt đồng vị $^{18}_9\\text{F}$ có trong mỗi mL dược chất tại thời điểm ban đầu và sau đó 1 ngày.",
    "",
    "**EM CÓ BIẾT**",
    "**Đồng vị Carbon $^{14}_6\\text{C}$, đồng hồ của Trái Đất**",
    "Năm 1947, Willand Frank Libby (Uy-lan Phờ-ranh Líp-bi) đã tìm ra phương pháp xác định niên đại của các cổ vật gốc hữu cơ, dựa vào các đặc tính của đồng vị phóng xạ carbon $^{14}_6\\text{C}$. Đồng vị $^{14}_6\\text{C}$ có chu kì bán rã là 5 730 năm. Sự phân rã này cân bằng với sự tạo ra $^{14}_6\\text{C}$ trong khí quyển (Hình 23.6), nên từ hàng vạn năm nay, mật độ của $^{14}_6\\text{C}$ trong khí quyển không đổi. Kí hiệu K (14) là tỉ lệ số nguyên tử của tất cả đồng vị carbon và số nguyên tử đồng vị $^{14}_6\\text{C}$ của một mẫu chất. Trong không khí K (14) $\\approx 10^{12}$, tỉ lệ này giữ không đổi trong các sinh vật còn sống.",
    "[Hình 23.6. Quy trình hình thành $^{14}_6\\text{C}$ trên Trái Đất]",
    "",
    "109",
    "CHƯƠNG IV – VẬT LÍ HẠT NHÂN VÀ PHÓNG XẠ",
    "",
    "Khi thực vật chết đi, không còn hấp thụ CO$_2$ trong không khí và $^{14}_6\\text{C}$ không còn tái sinh trong thực vật đó nữa. Vì $^{14}_6\\text{C}$ phóng xạ nên số lượng $^{14}_6\\text{C}$ giảm dần trong thực vật đó. Nói cách khác, tỉ lệ K (14) trong thực vật đang xét giảm đi so với tỉ lệ đó trong không khí. So sánh hai tỉ lệ đó cho phép ta xác định thời gian từ lúc thực vật đó chết cho đến nay.",
    "Động vật ăn thực vật nên tỉ lệ K (14) trong cơ thể cũng giảm sau khi chết. Vì vậy, có thể xác định tuổi các mẫu xương động vật tìm được trong các di chỉ khảo cổ bằng phương pháp này.",
    "Ngoài phương pháp xác định tuổi các mẫu vật có nguồn gốc hữu cơ dựa vào tính chất phóng xạ $^{14}_6\\text{C}$, người ta còn sử dụng nhiều phương pháp khác để xác định tuổi các mẫu vật vô cơ dựa vào tính chất phóng xạ của $^{238}_{92}\\text{U}$, $^{40}_{19}\\text{K}$, $^{36}_{17}\\text{Cl}$,...",
    "",
    "## III. ẢNH HƯỞNG CỦA TIA PHÓNG XẠ. BIỂN CẢNH BÁO PHÓNG XẠ",
    "**1. Ảnh hưởng của tia phóng xạ**",
    "Các tia phóng xạ có thể gây tác động mạnh tới tế bào của con người cũng như sinh vật. Vì vậy khi bị phơi nhiễm tia phóng xạ với liều lượng lớn trong một khoảng thời gian dài, có thể ảnh hưởng nghiêm trọng tới sức khoẻ cũng như di truyền (Hình 23.7).",
    "[Hình 23.7. Cà chua đột biến khi bị phơi nhiễm phóng xạ có hình dạng không bình thường]",
    "",
    "Trong một số trường hợp, với nguồn phóng xạ mạnh dù chỉ tiếp xúc thời gian ngắn nhưng cảm giác bỏng rát xuất hiện ngay, còn gọi là bỏng phóng xạ. Sau đó, nạn nhân xuất hiện các triệu chứng buồn nôn, nôn mửa, suy nhược thần kinh,... Các triệu chứng này còn gọi là nhiễm độc phóng xạ, ảnh hưởng lâu dài đến sức khoẻ, gây đột biến trong di truyền, ung thư,...",
    "Ảnh hưởng của tia phóng xạ lên cơ thể người phụ thuộc vào cường độ, khả năng ion hoá, khả năng đâm xuyên, thời gian chiếu,... của tia phóng xạ.",
    "- Với tia phóng xạ $\\alpha$: khả năng đâm xuyên của tia $\\alpha$ kém nên khi nguồn phóng xạ ở bên ngoài cơ thể thì nó không gây hậu quả đáng kể. Tuy nhiên, do khả năng ion hoá mạnh nên nếu nguồn phóng xạ $\\alpha$ xâm nhập vào cơ thể thì sẽ gây hậu quả rất nghiêm trọng.",
    "- Với tia phóng xạ $\\beta$: khả năng ion hoá và khả năng đâm xuyên ở mức trung bình, khi nguồn phóng xạ $\\beta$ ở trong hay ở ngoài cơ thể đều có thể gây ra các hậu quả đáng kể.",
    "- Với tia phóng xạ $\\gamma$: khả năng ion hoá kém hơn tia $\\alpha$, tia $\\beta$ nhưng khả năng đâm xuyên mạnh, khi nguồn phóng xạ $\\gamma$ ở trong hay ở ngoài cơ thể đều có thể gây ra hậu quả nghiêm trọng nếu cơ thể phơi nhiễm tia $\\gamma$ có cường độ lớn trong thời gian dài.",
    "",
    "110",
    "CHƯƠNG IV – VẬT LÍ HẠT NHÂN VÀ PHÓNG XẠ",
    "",
    "**2. Biển cảnh báo phóng xạ**",
    "Biển cảnh báo phóng xạ (Hình 23.8), được đặt tại khu vực lắp đặt thiết bị phát ra tia phóng xạ và nguồn phóng xạ, hoặc trên chính thiết bị và vật chứa của nguồn phóng xạ. Mục đích cảnh báo mọi người không nên tiếp cận hoặc làm hỏng thiết bị hoặc vật chứa thiết bị phóng xạ, vì điều này rất nguy hiểm.",
    "",
    "[Hình 23.8. Biển cảnh báo phóng xạ]",
    "",
    "**Hoạt động**",
    "1. Tìm hiểu qua sách báo, internet về tác hại của phóng xạ đến sức khoẻ của con người và cho biết:",
    "a) các loại phơi nhiễm phóng xạ",
    "b) biểu hiện khi bị phơi nhiễm phóng xạ.",
    "c) cách phòng tránh nhiễm phóng xạ.",
    "2. Nêu tên các địa điểm có nguy cơ phóng xạ trong Hình 23.9. Nếu gặp các biển cảnh báo đó em sẽ làm gì?",
    "",
    "[Hình 23.9. Biển cảnh báo phóng xạ xuất hiện trong nhiều trường hợp]",
    "",
    "## IV. NGUYÊN TẮC AN TOÀN PHÓNG XẠ",
    "Ngoài các nguồn phóng xạ được kiểm soát trong các hoạt động nghiên cứu và ứng dụng, con người có nguy cơ bị nhiễm phóng xạ thụ động như: phóng xạ có sẵn trong không khí (ví dụ $^{222}_{86}\\text{Rn}$), từ các tia vũ trụ (ví dụ $^{14}_6\\text{C}$), từ đá và vật liệu xây dựng có chứa đồng vị phóng xạ, trong thực phẩm (ví dụ đồng vị $^{40}_{19}\\text{K}$),...",
    "",
    "[Hình 23.10. Tỉ lệ phơi nhiễm phóng xạ do các nguồn thụ động khác nhau]",
    "- Không khí: 51%",
    "- Đá: 14%",
    "- Y học hạt nhân: 12%",
    "- Thức ăn: 12%",
    "- Tia vũ trụ: 10%",
    "- Nguồn khác: 1%",
    "",
    "111",
    "CHƯƠNG IV – VẬT LÍ HẠT NHÂN VÀ PHÓNG XẠ",
    "",
    "Hình 23.11 minh hoạ các nguyên tắc an toàn phóng xạ sau:",
    "a) Giữ khoảng cách đủ xa đối với nguồn phóng xạ. Nếu tăng gấp đôi khoảng cách từ chúng ta đến nguồn phóng xạ thì liều hấp thụ phóng xạ giảm đi 4 lần.",
    "b) Cần sử dụng các tấm chắn nguồn phóng xạ đủ tốt. Tấm chắn càng dày và có khối lượng riêng càng lớn sẽ càng cản trở mạnh tia phóng xạ.",
    "c) Cần giảm thiểu thời gian phơi nhiễm phóng xạ.",
    "",
    "[Hình 23.11. Ba nguyên tắc an toàn phóng xạ]",
    "",
    "**Hoạt động**",
    "1. Hãy tìm hiểu và nêu thêm nguyên tắc an toàn phóng xạ. Việc tuân thủ quy tắc an toàn phóng xạ có vai trò gì?",
    "2. Trong y học và công nghiệp, nguồn phóng xạ và chất thải phóng xạ được bảo quản trong các thiết bị lưu trữ (ví dụ như Hình 23.12) hoặc đặt trong các hầm cách li với các nguồn nước (ví dụ Hình 24.2). Người ta đã áp dụng nguyên tắc an toàn phóng xạ nào?",
    "",
    "[Hình 23.12. Thiết bị bảo quản dược chất phóng xạ]",
    "",
    "**EM CÓ BIẾT**",
    "1. Kính pha thêm chì (Hình 23.13) còn gọi là thuỷ tinh pha lê có tác dụng cản trở các tia phóng xạ mạnh hơn thuỷ tinh thường. Pha lê ngoài được sử dụng để tạo các đồ vật trang trí nó còn được dùng làm tấm kính giúp cho chúng ta vẫn nhìn được nguồn phóng xạ, nhưng hạn chế các tia phóng xạ chiếu vào người.",
    "[Hình 23.13. Thuỷ tinh pha lê được lắp tại nơi làm việc có nguồn phóng xạ]",
    "",
    "2. Nguyên tắc an toàn định lượng",
    "Liều hấp thụ phóng xạ hiệu dụng D$_{hd}$ cho con người được tính bởi hệ thức:",
    "$D_{hd} = DW$",
    "trong đó D là liều hấp thụ phóng xạ (năng lượng hấp thụ phóng xạ trên mỗi kg của vật), đơn vị (J/kg) và được gọi là gray (Gy: 1 J/kg = 1 Gy); W là trọng số bức xạ, phụ thuộc vào loại phóng xạ, bộ phận cơ thể bị chiếu xạ, W không có đơn vị. (Ví dụ, khi xét toàn bộ cơ thể người thì W = 1 với tia gamma và beta, W = 20 với tia alpha,...)",
    "D$_{hd}$ có đơn vị trong hệ SI là sieverts (kí hiệu Sv).",
    "Trung bình một năm con người đã nhận một liều hấp thụ phóng xạ hiệu dụng từ các nguồn phóng xạ thụ động khoảng 2,4 mSv.",
    "",
    "112",
    "CHƯƠNG IV – VẬT LÍ HẠT NHÂN VÀ PHÓNG XẠ",
    "",
    "Người ta đã đưa ra nguyên tắc an toàn định lượng đối với liều hấp thụ phóng xạ hiệu dụng cho con người trong một năm. Ngoài liều hấp thụ phóng xạ hiệu dụng từ các nguồn thụ động (2,4 mSv), khi làm việc trong môi trường có yếu tố phóng xạ, chiếu chụp X quang,... thì giới hạn liều hiệu dụng phải nhỏ hơn giá trị D$_{hd(max)}$. Tại nước ta, theo thông tư 19/2012/TT-BKHCN, quy định chung cho mỗi người là: D$_{hd(max)}$ = 1 mSv. Trường hợp học sinh, sinh viên độ tuổi từ 16 đến 18, học nghề có thực hành với nguồn phóng xạ thì D$_{hd(max)}$ = 6 mSv. Ngoài ra, đối với người làm việc trong cơ sở bức xạ thì D$_{hd(max)}$ = 20 mSv.",
    "",
    "**EM ĐÃ HỌC**",
    "- Phân rã phóng xạ có tính tự phát và ngẫu nhiên.",
    "- Tia phóng xạ là tia không nhìn thấy được, nhưng có các tính chất như: ion hoá, gây ra các hiệu ứng quang điện, phát xạ thứ cấp, làm đen kính ảnh, xuyên thấu lớp vật chất mỏng, phá huỷ tế bào, kích thích một số phản ứng hoá học,...",
    "- Các loại tia phóng xạ chính:",
    "  - Tia phóng xạ $\\alpha$ là các hạt nhân $^4_2\\text{He}$ được phóng ra từ hạt nhân bị phân rã, chuyển động với tốc độ khoảng $2.10^7 \\text{ m/s}$.",
    "  - Tia phóng xạ $\\beta^-$ (hoặc $\\beta^+$) là dòng các hạt $^0_{-1}e$ (hoặc $^0_{+1}e$) phóng ra từ hạt nhân bị phân rã, chuyển động với tốc độ xấp xỉ tốc độ ánh sáng.",
    "  - Tia phóng xạ $\\gamma$ là sóng điện từ có bước sóng rất ngắn cỡ nhỏ hơn $10^{-11} \\text{ m}$.",
    "- Số hạt chưa phân rã của chất phóng xạ N$_t$ tại thời điểm t và số hạt ban đầu N$_0$ của chất phóng xạ được liên hệ với nhau theo công thức:",
    "  $N_t = N_0.2^{-\\frac{t}{T}} = N_0.e^{-\\lambda t}$",
