    "- Độ phóng xạ H đặc trưng cho tính phóng xạ mạnh hay yếu của một lượng chất phóng xạ, có giá trị bằng số hạt nhân phân rã trong một giây. Độ phóng xạ H$_t$ của một mẫu chất phóng xạ tại thời điểm t được xác định theo công thức:",
    "  $H_t = \\lambda.N_t = H_0.e^{-\\lambda t}$",
