INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH5' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI12')), 'B24', 'Công nghiệp hạt nhân', 116, 2, $JSON$
{
  "content": [
    "# Bài 24 CÔNG NGHIỆP HẠT NHÂN",
    "",
    "**Khởi động:**",
    "*Nhà máy điện hạt nhân có thể giải quyết vấn đề thiếu hụt năng lượng. Tuy vậy, một số quốc gia phát triển dự định sẽ đóng cửa các nhà máy điện hạt nhân trong tương lai. Nhà máy điện hạt nhân có những ưu điểm và nhược điểm gì?*",
    "[Hình: Nhà máy điện hạt nhân tại thị trấn Gundremmingen (Gun-đem-min-gen) – Đức]",
    "",
    "## I. NHÀ MÁY ĐIỆN HẠT NHÂN",
    "Năng lượng toả ra trong các phản ứng hạt nhân thường được chuyển hoá thành điện năng thông qua hệ thống lò phản ứng hạt nhân, tua bin và máy phát điện để hoà vào lưới điện hoặc cung cấp năng lượng cho tàu ngầm, tàu phá băng,... Hệ thống khai thác năng lượng hạt nhân có thể hoạt động trong thời gian dài mà không cần bổ sung nhiên liệu.",
    "Bộ phận chính của nhà máy điện hạt nhân là lò phản ứng hạt nhân. Chất tải nhiệt sơ cấp, sau khi chạy qua vùng tâm lò, sẽ chảy qua bộ trao đổi nhiệt, cung cấp nhiệt cho lò sinh hơi. Hơi nước làm chạy tua bin phát điện giống như trong nhà máy điện thông thường (Hình 24.1).",
    "",
    "[Hình 24.1. Sơ đồ đơn giản hoá của một nhà máy điện hạt nhân]",
    "",
    "114",
    "CHƯƠNG IV – VẬT LÍ HẠT NHÂN VÀ PHÓNG XẠ",
    "",
    "Nhà máy điện hạt nhân không trực tiếp phát khí thải ô nhiễm môi trường như CO$_2$, CO,... và có thể phát điện liên tục nhiều năm cho tới khi phải thay nhiên liệu mới.",
    "Tuy nhiên, việc xử lí chất thải hạt nhân đòi hỏi công nghệ phức tạp với chi phí cao. Vật liệu chứa chất thải hạt nhân cần có độ bền rất cao để bảo quản cất giữ hàng trăm năm sau khi khai thác vì chu kì bán rã của một số đồng vị trong thanh nhiên liệu hạt nhân đã qua sử dụng là rất lớn (Ví dụ $^{90}\\text{Sr}$, $^{137}\\text{Cs}$ có chu kì bán rã khoảng 30 năm) (Hình 24.2).",
    "",
    "[Hình 24.2. Cấu tạo thiết bị lưu trữ nhiên liệu hạt nhân đã qua sử dụng]",
    "",
    "**EM CÓ BIẾT**",
    "**Lò phản ứng hạt nhân**",
    "Năm 1942, Fermi và các cộng sự đã lần đầu tiên thực hiện thành công các chuỗi phản ứng phân hạch duy trì điều khiển được trong lò phản ứng ở trường đại học Chicago (Mĩ). Lò phản ứng hạt nhân là một hệ thống được sử dụng để khởi tạo và điều khiển chuỗi phản ứng phân hạch hạt nhân dây chuyền. Phần lớn các lò phản ứng hạt nhân đều có nhiều bộ phận chức năng giống nhau (Hình 24.3). Nhiên liệu phân hạch trong phần lớn các lò phản ứng là $^{235}\\text{U}$ hay $^{239}\\text{Pu}$. Để đảm bảo cho k = 1, trong các lò phản ứng người ta dùng các thanh điều khiển có chứa Bo hay Cd, là các chất có tác dụng hấp thụ neutron nhiệt (động năng dưới 0,1 eV). Khi số neutron trong lò tăng lên quá nhiều (k > 1), người ta cho các thanh điều khiển ngập sâu vào khu vực chứa nhiên liệu phân hạch để hấp thụ số neutron thừa. Nhờ vậy, năng lượng toả ra từ lò phản ứng không đổi theo thời gian.",
    "",
    "[Hình 24.3. Sơ đồ mặt cắt lò phản ứng neutron nhiệt sử dụng thanh điều khiển hấp thụ neutron]",
    "1. Thanh nhiên liệu; 2. Chất làm chậm neutron; 3. Vỏ kim loại; 4. Lớp tán xạ neutron bằng than chì; 5. Ống làm lạnh và chất tải nhiệt; 6. Thanh điều khiển tấm hấp thụ neutron; 7. Thành bảo vệ phóng xạ; 8. Đường ống làm thí nghiệm (dùng cho lò nghiên cứu).",
    "",
    "115",
    "CHƯƠNG IV – VẬT LÍ HẠT NHÂN VÀ PHÓNG XẠ",
    "",
    "**? Câu hỏi:**",
    "1. Vì sao các nhà máy điện hạt nhân thường được xây dựng cạnh hồ, sông và bờ biển?",
    "2. Liệt kê các nguy cơ ảnh hưởng tới sức khoẻ con người và môi trường nếu không may xảy ra sự cố tại lò phản ứng hạt nhân.",
    "",
    "**Hoạt động**",
    "Thảo luận để thực hiện các yêu cầu sau:",
    "1. Nêu vai trò của các nhà máy điện hạt nhân trong đời sống.",
    "2. Đánh giá các ưu điểm, nhược điểm và cơ hội phát triển của các nhà máy điện hạt nhân.",
    "",
    "## II. Y HỌC HẠT NHÂN",
    "Trong y học người ta khai thác các tính chất của tia phóng xạ để chẩn đoán và điều trị bệnh.",
    "**1. Chẩn đoán thông qua chụp ảnh phóng xạ cắt lớp bên trong cơ thể**",
    "Người ta đưa các đồng vị phóng xạ vào cơ thể thông qua dược chất phóng xạ. Thông qua thiết bị phát hiện tia phóng xạ và sử dụng máy vi tính, người ta có thể theo dõi sự dịch chuyển của các dược chất phóng xạ bên trong cơ thể (phương pháp theo dõi vết phóng xạ). Ví dụ: Khi tiêm dược chất phóng xạ vào tĩnh mạch để chụp ảnh phóng xạ gan mật, nhờ theo dõi vết phóng xạ chúng ta sẽ quan sát được toàn bộ quá trình sản xuất dịch mật của gan và sự dịch chuyển của dịch từ gan chảy tới túi mật.",
    "",
    "**EM CÓ BIẾT**",
    "Để tạo ra hình ảnh các bộ phận bên trong cơ thể người ta dùng kĩ thuật chụp ảnh phóng xạ cắt lớp SPECT (Single Photon Emission Computed Tomography) và PET (Positron Emission Tomography). Phương pháp chụp ảnh phóng xạ cắt lớp thường được phối hợp với chụp ảnh bằng các phương pháp khác (CT, MRI) để tăng độ chi tiết của hình ảnh cơ quan bên trong cơ thể (Hình 24.4). Theo dõi vết phóng xạ nhờ chụp ảnh phóng xạ cắt lớp cho ta các hình ảnh chi tiết của các bộ phận cơ thể theo nhiều góc quan sát khác nhau. Ngoài ra nó còn giúp ta theo dõi được sự luân chuyển của các chất trong cơ thể. Vì vậy, phương pháp này giúp cho việc chẩn đoán bệnh chính xác hơn.",
    "[Hình 24.4. Hệ thống chụp ảnh PET tại bệnh viện 19-8, Hà Nội]",
    "",
    "116",
    "CHƯƠNG IV – VẬT LÍ HẠT NHÂN VÀ PHÓNG XẠ",
    "",
    "**Hoạt động**",
    "Thảo luận và thực hiện các yêu cầu sau:",
    "1. Tại sao người ta sử dụng tia gamma trong chụp ảnh phóng xạ cắt lớp bên trong cơ thể?",
    "2. Nêu vai trò của y học hạt nhân trong đời sống.",
    "3. Đánh giá các ưu điểm, nhược điểm và cơ hội phát triển của y học hạt nhân.",
    "",
    "**2. Điều trị bệnh**",
    "Trong điều trị bệnh ung thư, bệnh nhân được uống hoặc tiêm dược chất phóng xạ với thành phần chứa đồng vị phóng xạ (ví dụ thuốc Xofigo có chứa đồng vị phóng xạ $^{223}_{86}\\text{Ra}$, hoặc thuốc Lutathe ra có chứa đồng vị phóng xạ $^{177}_{71}\\text{Lu}$,...). Các tế bào ung thư sẽ chết do hấp thụ tia phóng xạ có trong dược chất phóng xạ được mạch máu vận chuyển tới.",
    "Ngoài cách sử dụng dược chất phóng xạ, người ta còn dùng máy xạ trị để chiếu tia phóng xạ từ bên ngoài cơ thể vào tế bào ung thư để tiêu diệt chúng. Tia phóng xạ cũng được dùng để khử trùng, khử khuẩn,...",
    "",
    "**? Câu hỏi:**",
    "Khi sử dụng máy xạ trị để chữa bệnh, tia phóng xạ có tác động lên các tế bào khoẻ mạnh không? Hãy tìm thông tin về các triệu chứng của bệnh nhân sau khi xạ trị.",
    "",
    "## III. ỨNG DỤNG PHÓNG XẠ HẠT NHÂN TRONG CÔNG NGHỆ SINH HỌC VÀ TRONG BẢO QUẢN THỰC PHẨM",
    "Trong công nghệ sinh học, tia phóng xạ có thể được sử dụng hỗ trợ nghiên cứu gây đột biến gene, nhằm tạo ra các giống cây trồng mới có một số đặc điểm vượt trội như khả năng kháng sâu bệnh, năng suất cao, tạo quả trái mùa, hoặc một số loại quả không hạt,... Cây trồng đột biến gene có thể ít ảnh hưởng tới môi trường do cây chỉ cần sử dụng ít phân bón và các loại thuốc trừ sâu, thuốc kích thích sinh trưởng.",
    "[Hình 24.5. Vải thiều được chiếu xạ (a) và vải thiều thường (b) sau 7 ngày kể từ khi thu hoạch]",
    "Tuy nhiên, cây trồng biến đổi gene vẫn có thể gây tác động xấu đến côn trùng, ảnh hưởng đến hệ sinh thái và sức khoẻ con người khi thường xuyên sử dụng.",
    "Phương pháp đánh dấu phóng xạ cũng được sử dụng trong nghiên cứu sinh học, nông nghiệp và lâm nghiệp. Ví dụ: Để nghiên cứu đường đi của phân bón trong cây trồng, người ta sẽ bón phân có đồng vị $^{32}_{15}\\text{P}$ có tính phóng xạ $\\beta$. Quan sát ảnh chụp phóng xạ của cây tại các thời điểm cách đều nhau, có thể đưa ra các biện pháp chăm sóc cây trồng phù hợp, giúp nâng cao chất lượng và năng suất.",
    "",
    "117",
    "CHƯƠNG IV – VẬT LÍ HẠT NHÂN VÀ PHÓNG XẠ",
    "",
    "Nhờ khả năng diệt vi trùng có hại của tia phóng xạ, nên chúng còn được sử dụng rộng rãi trong bảo quản sản phẩm nông nghiệp và thực phẩm. Chiếu tia phóng xạ còn có thể giúp kéo dài thời hạn sử dụng của thực phẩm nhờ thay đổi một số tính chất hoá học của thực phẩm tươi, giúp thực phẩm tránh bị mọc mầm, phân huỷ (Hình 24.5).",
    "Bên cạnh các ưu điểm, một số loại thực phẩm chiếu xạ có thể bị thay đổi màu sắc, hương vị làm thay đổi chất lượng sản phẩm. Ngoài ra, thực phẩm chiếu xạ có giá thành cao.",
    "",
    "**Hoạt động**",
    "Thảo luận và thực hiện các yêu cầu sau:",
    "1. Nêu vai trò của ứng dụng phóng xạ hạt nhân trong công nghệ sinh học và trong bảo quản thực phẩm.",
    "2. Đánh giá ưu điểm, nhược điểm và cơ hội phát triển các ứng dụng phóng xạ hạt nhân trong công nghệ sinh học và trong bảo quản thực phẩm.",
    "",
    "**EM ĐÃ HỌC**",
    "- Một số ứng dụng công nghiệp hạt nhân như nhà máy điện hạt nhân, y học hạt nhân; ứng dụng phóng xạ hạt nhân trong công nghệ sinh học và trong bảo quản thực phẩm.",
    "",
    "**EM CÓ THỂ**",
    "- Nêu được ví dụ về vai trò và ứng dụng phóng xạ của một số ngành công nghiệp hạt nhân trong đời sống.",
    "- Giải thích được vì sao cần khai thác năng lượng hạt nhân vào mục đích hoà bình.",
    "",
    "118"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH5' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'LI12')), 'B25', 'Bài tập về vật lí hạt nhân', 121, 3, $JSON$
{
  "content": [
    "# Bài 25 BÀI TẬP VỀ VẬT LÍ HẠT NHÂN",
    "",
    "**Khởi động:**",
    "*Cần vận dụng những kiến thức cơ bản nào để giải những bài tập về vật lí hạt nhân?*",
    "",
    "## I. MỘT SỐ LƯU Ý TRONG VIỆC GIẢI BÀI TẬP VỀ VẬT LÍ HẠT NHÂN",
    "Phần vật lí hạt nhân bao gồm bốn nội dung chính: cấu trúc hạt nhân, phản ứng hạt nhân, phóng xạ và ứng dụng công nghiệp hạt nhân.",
    "**1. Lưu ý khi giải bài tập định tính**",
    "Các bài tập này thường yêu cầu mô tả cấu tạo hạt nhân, đặc điểm của hạt nhân tham gia phản ứng hạt nhân, tính chất của các tia phóng xạ, giải thích các ứng dụng của vật lí hạt nhân trong đời sống và trong kĩ thuật.",
    "**2. Lưu ý khi giải bài tập định lượng**",
    "Các bài tập này thường yêu cầu vận dụng công thức xác định số lượng và loại nucleon; khối lượng, số lượng hạt nhân hoặc thời gian thực hiện phóng xạ của mẫu phóng xạ.",
    "**3. Lưu ý khi giải bài tập có nội dung thực tiễn**",
    "Các bài tập này thường yêu cầu rèn luyện khả năng liên tưởng giữa kiến thức vật lí hạt nhân đã được học và các nội dung thực tiễn; đồng thời cũng yêu cầu trừu tượng hoá, khái quát hoá thực tiễn để thiết lập các mô hình sao cho có thể vận dụng nội dung các kiến thức vật lí hạt nhân để giải quyết vấn đề.",
    "",
    "## II. BÀI TẬP VÍ DỤ",
    "1. Giải thích tại sao khi đưa mẫu phóng xạ (1) vào gần đầu thu điện (2) của một tĩnh điện kế đã được tích điện (Hình 25.1) thì độ lệch của kim điện kế (3) giảm rất nhanh?",
    "",
    "*Giải*",
    "Độ lệch kim điện kế giảm nhanh cho ta biết tĩnh điện kế nhận thêm điện tích trái dấu hoặc mất bớt điện tích.",
    "Như vậy có thể có hai trường hợp:",
    "- Các tia phóng xạ làm ion hoá không khí xung quanh mẫu phóng xạ do vậy không khí sẽ dẫn điện dễ dàng hơn.",
    "- Điện tích của các hạt mang trong tia phóng xạ có thể trái dấu với điện tích đã tích điện trên tĩnh điện kế. Nếu vậy, tĩnh điện kế sẽ nhanh chóng trung hoà điện rồi lại tích điện trái dấu. Do đó độ lệch kim điện kế lúc đầu giảm dần sau đó tăng dần lên, không giống như hiện tượng đã mô tả.",
    "",
    "[Hình 25.1. Thí nghiệm đưa mẫu phóng xạ lại gần tĩnh điện kế]",
    "",
    "119",
    "CHƯƠNG IV – VẬT LÍ HẠT NHÂN VÀ PHÓNG XẠ",
    "",
    "Dựa vào phân tích trên ta thấy sự ion hoá môi trường của tia phóng xạ chính là nguyên nhân. Không khí xung quanh tĩnh điện kế trở nên dẫn điện tốt hơn do bị ion hoá khi đưa mẫu phóng xạ lại gần tĩnh điện kế. Chính vì vậy điện tích của tĩnh điện kế nhanh chóng bị dẫn ra môi trường, làm kim điện kế nhanh chóng dịch về vị trí 0.",
    "",
    "2. Viết phương trình phân hạch của $^{235}_{92}\\text{U}$ khi hấp thụ 1 neutron, biết rằng sản phẩm phân hạch gồm có $^{140}_{58}\\text{Ce}$, $^{94}_{40}\\text{Zr}$, các neutron và các tia $\\beta^-$.",
    "",
    "*Giải*",
    "Gọi x là hạt neutron $^1_0\\text{n}$ và y là số hạt electron $^0_{-1}e$ tạo thành trong phân hạch. Phương trình phản ứng hạt nhân có dạng:",
    "$^{235}_{92}\\text{U} + ^1_0\\text{n} \\rightarrow ^{140}_{58}\\text{Ce} + ^{94}_{40}\\text{Zr} + x^1_0\\text{n} + y^0_{-1}e$",
    "Ta thấy x và y bị ràng buộc bởi định luật bảo toàn số khối A và nguyên tử số Z của cả hạt tham gia phản ứng. Hai định luật cho ta hai phương trình liên hệ hai ẩn của x và y, nhờ vậy có thể tìm được x và y.",
    "Từ định luật bảo toàn số khối và định luật bảo toàn điện tích ta có hệ phương trình:",
    "$\\begin{cases}",
    "235 + 1 = 140 + 94 + x.1 + y.0 \\\\",
    "92 + 0 = 58 + 40 + x.0 + y.(-1)",
    "\\end{cases} \\Rightarrow",
    "\\begin{cases}",
    "x = 2 \\\\",
    "y = 6",
    "\\end{cases}$",
    "Do vậy, phương trình phản ứng là",
    "$^{235}_{92}\\text{U} + ^1_0\\text{n} \\rightarrow ^{140}_{58}\\text{Ce} + ^{94}_{40}\\text{Zr} + 2^1_0\\text{n} + 6^0_{-1}e$",
    "",
    "3. Máy xạ trị (Hình 25.2) thường sử dụng nguồn phóng xạ $^{60}_{27}\\text{Co}$ có chu kì bán rã là 5,3 năm. Để đáp ứng đúng các tiêu chí y học để điều trị bệnh, thiết bị sẽ bắt buộc phải bảo dưỡng để hiệu chỉnh lại chùm tia chiếu xạ trước khi độ phóng xạ giảm đi 7% và phải thay nguồn phóng xạ mới khi độ phóng xạ giảm đi 50%. Các kĩ sư thiết kế máy xạ trị cần thiết lập lịch bảo dưỡng và thay thế nguồn phóng xạ của máy xạ trị như thế nào để đưa vào các bản hướng dẫn cho các bệnh viện?",
    "[Hình 25.2. Máy xạ trị được sử dụng trong bệnh viện]",
    "",
    "*Giải*",
    "Lịch bảo dưỡng và thay thế nguồn phóng xạ liên hệ với sự giảm của độ phóng xạ của nguồn phóng xạ $^{60}_{27}\\text{Co}$. Như vậy khi biết chính xác sự phụ thuộc độ giảm độ phóng xạ theo thời gian ta có thể lập được lịch bảo dưỡng.",
    "Độ phóng xạ H$_t$ tại thời điểm t của nguồn phóng xạ có chu kì bán rã T liên hệ với độ phóng xạ tại thời điểm ban đầu H$_0$ theo công thức $H_t = H_0.2^{-\\frac{t}{T}}$. Từ công thức này ta thiết lập được các mốc thời gian ứng với độ giảm độ phóng xạ đã biết.",
    "Gọi chu kì bảo dưỡng là $t_{bd}$, chính là khoảng thời gian khi độ phóng xạ giảm đi 7%. Ta có:",
    "$\\frac{H_0 - H_{t_{bd}}}{H_0} = \\frac{H_0 - H_0.2^{-\\frac{t_{bd}}{T}}}{H_0} = \\frac{7}{100} \\Rightarrow t_{bd} = T\\log_2(\\frac{100}{93}) \\approx 6,65 \\text{ tháng}$",
    "",
    "120",
    "CHƯƠNG IV – VẬT LÍ HẠT NHÂN VÀ PHÓNG XẠ",
    "",
    "Gọi $t_{tm}$ là chu kì thay mới nguồn phóng xạ, đó chính là khoảng thời gian khi độ phóng xạ giảm đi 50%. Ta có:",
    "$\\frac{H_0 - H_{t_{tm}}}{H_0} = \\frac{H_0 - H_0.2^{-\\frac{t_{tm}}{T}}}{H_0} = \\frac{50}{100} \\Rightarrow t_{tm} = T\\log_2(\\frac{100}{50}) = T = 5,3 \\text{ năm}$",
    "Vậy lịch bảo dưỡng của máy xạ trị là sau mỗi 6 tháng và lịch thay thế nguồn phóng xạ là sau mỗi 5,3 năm.",
    "",
    "## III. BÀI TẬP VẬN DỤNG",
    "1. Lực nào đã làm thay đổi phương của hạt alpha ($^4_2\\text{He}$) khi được bắn vào lá vàng mỏng?",
    "A. Lực hạt nhân giúp hạt nhân $^{197}_{79}\\text{Au}$ đẩy $^4_2\\text{He}$.",
    "B. Lực hạt nhân giúp hạt nhân $^{197}_{79}\\text{Au}$ hút $^4_2\\text{He}$.",
    "C. Lực đẩy tĩnh điện giữa hạt nhân $^{197}_{79}\\text{Au}$ và $^4_2\\text{He}$.",
    "D. Lực hút tĩnh điện giữa các electron của phân tử vàng và $^4_2\\text{He}$.",
    "",
    "2. Người ta đo độ phóng xạ H của một đồng vị theo thời gian t và điền kết quả vào Bảng 25.1.",
    "a) Vẽ đồ thị độ phóng xạ theo thời gian.",
    "b) Ước lượng chu kì bán rã của đồng vị này.",
    "**Bảng 25.1.** *Độ phóng xạ theo thời gian*",
    "| t(s) | 0 | 30 | 60 | 120 |",
    "|---|---|---|---|---|",
    "| H (Bq) | 151 | 85 | 55 | 31 |",
    "| t(s) | 180 | 240 | 300 | 360 |",
    "| H (Bq) | 22 | 15 | 11 | 9 |",
    "",
    "3. Dùng máy đo phóng xạ của một mẫu gỗ của một cổ vật phát hiện được 240 phóng xạ mỗi phút. Biết rằng thành phần của mẫu gỗ có chứa 25 g $^{14}_6\\text{C}$ và $^{12}_6\\text{C}$, chu kì bán rã của $^{14}_6\\text{C}$ là 5 730 năm và tỉ lệ nguyên tử $^{12}_6\\text{C}$ và $^{14}_6\\text{C}$ khi một sinh vật còn sống $10^{12}$:1.",
    "a) Xác định số nguyên tử $^{14}_6\\text{C}$ có trong mẫu gỗ.",
    "b) Xác định độ tuổi của mẫu gỗ này.",
    "",
    "4. Một nhà máy điện hạt nhân sử dụng nguyên liệu hạt nhân là $^{235}\\text{U}$. Biết rằng mỗi phân hạch sẽ toả năng lượng 200 MeV. Hiệu suất phát điện của nhà máy là 36%. Công suất phát điện của nhà máy là 1 400 MW.",
    "a) Hãy tính khối lượng của nguyên liệu $^{235}\\text{U}$ nhà máy tiêu thụ trong 1 năm.",
    "b) Tính lượng than đá tiêu thụ để sản xuất ra năng lượng điện tương đương, biết rằng năng suất toả nhiệt của than đá là 30 MJ/kg.",
    "",
    "121",
    "CHƯƠNG IV – VẬT LÍ HẠT NHÂN VÀ PHÓNG XẠ",
    "",
    "5. Vào tháng 6 năm 2024, người lái xe tải sẽ phải chờ bao nhiêu lâu để toàn bộ lượng thuốc đông y chất đầy thùng xe tải được chiếu xạ để bảo quản tại Trung tâm chiếu xạ Hà Nội (Hình 25.3), biết rằng cũng tại nơi đó vào tháng 1 năm 2022 người lái xe đã phải chờ 150 phút chiếu xạ cùng lượng thuốc như vậy và trung tâm chiếu xạ vẫn sử dụng nguồn chiếu xạ là $^{60}_{27}\\text{Co}$ có chu kì bán rã là 5,3 năm?",
    "[Hình 25.3. Khu nạp nguyên liệu vào dây chuyền chiếu xạ – Trung tâm chiếu xạ Hà Nội]",
    "",
    "6. Dược chất phóng xạ FDG có thành phần là đồng vị $^{18}_9\\text{F}$ với chu kì bán rã là 110 phút, được sử dụng trong chụp ảnh cắt lớp PET. Dược chất này được sản xuất bằng cách bắn phá vào các hạt đồng vị $^{18}_8\\text{O}$ nhờ một loại hạt được tăng tốc bằng máy gia tốc (Hình 25.4).",
    "a) Xác định loại hạt được tăng tốc trong máy gia tốc biết rằng ngoài $^{18}_9\\text{F}$, sản phẩm bắn phá còn có neutron và phát xạ tia gamma.",
    "b) Trước khi chụp ảnh cắt lớp PET, bệnh nhân sẽ được tiêm liều lượng dược chất FDG để đảm bảo độ phóng xạ trên mỗi kg cân nặng là 0,1 mCi không đổi. Hai bệnh nhân cùng cân nặng, cùng sử dụng FDG trong cùng một đợt sản xuất, nhưng được tiêm ở 2 thời điểm cách nhau 60 phút. Hỏi người nào sẽ được tiêm lượng FDG nhiều hơn? Xác định phần trăm lượng FDG nhiều hơn này cần được tiêm.",
    "",
    "[Hình 25.4. Máy gia tốc tại trung tâm chiếu xạ Hà Nội]",
    "",
    "**EM ĐÃ HỌC**",
    "- Cách giải các bài tập về vật lí hạt nhân.",
    "",
    "**EM CÓ THỂ**",
    "- Vận dụng các kiến thức về cấu trúc hạt nhân, phản ứng hạt nhân, phóng xạ và ứng dụng công nghệ hạt nhân để giải các bài tập.",
    "",
    "122",
    "**GIẢI THÍCH MỘT SỐ THUẬT NGỮ DÙNG TRONG SÁCH**",
    "",
    "| THUẬT NGỮ | TRANG |",
    "|---|---|",
    "| *Chuyển động nhiệt:* Chuyển động của các phân tử, nguyên tử cấu tạo nên vật. | 18 |",
    "| *Công nghiệp hạt nhân:* Các lĩnh vực ứng dụng các kiến thức của vật lí hạt nhân vào nghiên cứu khoa học, sản xuất và cuộc sống. | 119 |",
    "| *Cặp nhiệt điện:* Thiết bị đo nhiệt độ hoạt động dựa trên sự thay đổi của hiệu điện thế theo mức chênh lệch nhiệt độ giữa hai đầu nối của một cặp dây dẫn làm bằng hai kim loại hoặc chất bán dẫn khác nhau. | 19 |",
    "| *Điện trường xoáy:* Điện trường có đường sức điện là các đường cong khép kín. | 82 |",
    "| *Nhiệt độ:* Đại lượng dùng để mô tả sự nóng lạnh, đặc trưng cho động năng trung bình của phân tử. | 37 |",
    "| *Nhiễu xạ:* Sự lệch khỏi phương truyền thẳng khi sóng đi sát mép của các vật cản hoặc truyền qua những lỗ nhỏ. | 85 |",
    "| *Liều phóng xạ:* Năng lượng mà vật nhận được từ các tia phóng xạ trên mỗi đơn vị khối lượng trong một khoảng thời gian xác định. | 107 |",
    "| *Phản ứng hạt nhân:* Quá trình dẫn đến sự biến đổi hạt nhân này thành hạt nhân khác. | 96 |",
    "| *Phân rã hạt nhân:* Loại phản ứng hạt nhân trong đó hạt nhân của các nguyên tử có số khối lớn tự vỡ ra thành các hạt nhân có số khối nhỏ hơn. | 97 |",
    "| *Trạng thái siêu bão hòa:* Trạng thái có nồng độ vượt ngưỡng trạng thái cân bằng cho phép. | 96 |",
    "| *Tác nhân:* Đối tượng có ảnh hưởng tới quá trình đang xét. | 13 |",
    "| *Y học hạt nhân:* Lĩnh vực y học áp dụng các kiến thức vật lí hạt nhân vào chẩn đoán và điều trị bệnh. | 107 |",
